```jac
"""Bug tracker: a connection hands back what it just created.

`here ++> Ticket(...)` evaluates to the freshly created ticket, so
the reporter walker can immediately grab its id and title without a
second lookup query.
"""

node Project {
    has name: str = "";
}

node Ticket {
    has title: str = "";
    has priority: str = "normal";
}

walker Reporter {
    has summary: str = "";
    has filed: int = 0;

    can start with Root entry {
        project = [-->][?:Project][0];
        print(f"[OUT]Filing bugs against {project.name}");
        visit project;  # hand off to the Project ability exactly once
    }

    can file with Project entry {
        t1 = here ++> Ticket(title="Login page crashes on Safari", priority="high");
        print(f"[OUT]Filed #{t1.title}: priority={t1.priority}");

        t2 = here ++> Ticket(title="Typo in footer");
        print(f"[OUT]Filed #{t2.title}: priority={t2.priority}");

        self.filed = 2;
        self.summary = f"{self.filed} tickets filed";
        report self.summary;
    }
}

with entry {
    root ++> Project(name="Website Redesign");
    result = root spawn Reporter(summary="");
    print(f"Result: {result.reports}");
}
```

```jac
"""Cave expedition transcript.

Entry abilities stamp arrival the moment a chamber is reached; exit
abilities stamp departure only after every deeper chamber is done, so
the transcript shows entries in walking order and exits unwinding in
reverse (innermost chamber leaves first).
"""

node Chamber {
    has label: str;

    can arrive with Explorer entry {
        print(f"ENTER {self.label}");
    }

    can depart with Explorer exit {
        print(f"EXIT  {self.label}");
    }
}

walker Explorer {
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Chamber entry {
        self.depth += 1;
        visit [-->];
    }

    can finish with Root exit {
        print(f"explorer reached depth {self.depth}");
    }
}

with entry {
    mouth = Chamber(label="Mouth");
    tunnel = Chamber(label="Tunnel");
    cavern = Chamber(label="Crystal Cavern");
    root ++> mouth ++> tunnel ++> cavern;

    root spawn Explorer();
}
