```jac
"""Count every build task in a dependency DAG that contains diamonds.

Shared libraries are depended on by several modules, so the graph has
diamonds: separate visit steps can enqueue the same logical task twice
(e.g. two distinct Task instances sharing the same name+minutes). The
auditor guards with a seen-set keyed on the value pair (name, minutes)
so each logical task is counted exactly once while distinct instances
with different attributes are still tracked separately.
"""

node Task {
    has name: str;
    has minutes: int;
}

edge Needs {}

walker Auditor {
    has seen: set = set();
    has total_minutes: int = 0;
    has double_enqueue_avoided: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        key = (here.name, here.minutes);
        # Diamond in the DAG: this logical task may already have been
        # enqueued from two different parents -- count it once
        if key in self.seen {
            print(f"{here.name}: already audited via another path, skipping");
            self.double_enqueue_avoided = True;
            skip;
        }
        self.seen.add(key);
        self.total_minutes += here.minutes;
        print(f"auditing {here.name} ({here.minutes} min, running total {self.total_minutes})");

        visit [->:Needs:->];
    }

    can finish with Root exit {
        print(f"-- Audit: {len(self.seen)} unique task(s), total {self.total_minutes} min --");
        if self.double_enqueue_avoided {
            print("Seen-guard caught at least one diamond re-entry");
        }
    }
}

with entry {
    app = Task(name="build-app", minutes=5);
    web = Task(name="compile-web", minutes=8);
    api = Task(name="compile-api", minutes=12);
    core = Task(name="link-core", minutes=20);

    root ++> app;
    app +>: Needs() :+> web;
    app +>: Needs() :+> api;
    web +>: Needs() :+> core;
    api +>: Needs() :+> core;

    root spawn Auditor();
}
```

```jac
"""Follow citation trails through a wiki-style knowledge graph.

Articles connect to other articles with Cites edges and to authors
with WrittenBy edges. Starting from one article, the reader follows a
chain that switches edge types mid-walk: cited article first, then the
author behind it.
"""

node Article {
    has title: str;
}

node Author {
    has name: str;
}

edge Cites {}
edge WrittenBy: Article --> Author {}

walker Reader {
    can start with Root entry {
        visit [-->];
    }

    can read with Article entry {
        print(f"Reading article: {here.title}");

        # Hop 1 crosses a Cites edge, hop 2 crosses a WrittenBy edge --
        # mixed edge types chain naturally in one query. The intermediate
        # Cites hop is materialized into a list, then traversed again
        # with the WrittenBy hop to reach the author.
        cited = [here ->:Cites:->];
        sources_authors = [->:WrittenBy:->];

        for n in cited {
            for a in [n ->:WrittenBy:->] {
                print(f"  '{here.title}' cites work by author {a.name}");
            }
        }

        # The reverse single hop also works from an article
        writers = [->:WrittenBy:->];
        if not writers {
            print("  (no author recorded)");
        } else {
            print(f"  written by {writers[0].name}");
        }

        # Walk both outgoing edges: continue along Cites to cited
        # articles, and along WrittenBy to the author. Author nodes
        # have no outgoing abilities, so no loop risk.
        visit [->:Cites:->];
        visit [->:WrittenBy:->];
    }

    can meet with Author entry {
        print(f"Met author {here.name} while reading");
    }
}

with entry {
    transformers = Article(title="Attention Is All You Need");
    bert = Article(title="BERT");
    vit = Article(title="Vision Transformer");
    ashish = Author(name="Ashish");
    jacob = Author(name="Jacob");

    transformers +>: Cites() :+> bert;
    transformers +>: Cites() :+> vit;
    bert +>: WrittenBy() :+> jacob;
    vit +>: WrittenBy() :+> ashish;

    root ++> transformers;
    root spawn Reader();
}
```

```jac
"""Aggregate stats over a private todo graph into one report.

Counters accumulate during the walk and a single dict is reported at
Root exit; division by zero is guarded for accounts with no todos.
"""

node Todo {
    has title: str;
    has done: bool = False;
    has points: int = 1;
}

walker add_todo {
    has title: str;
    has done: bool = False;
    has points: int = 1;

    can run with Root entry {
        here ++> Todo(title=self.title, done=self.done, points=self.points);
    }
}

walker get_stats {
    has total: int = 0;
    has completed: int = 0;
    has effort_done: int = 0;
    has effort_total: int = 0;

    can count with Root entry {
        visit [-->];
    }

    can tally with Todo entry {
        self.total += 1;
        self.effort_total += here.points;
        if here.done {
            self.completed += 1;
            self.effort_done += here.points;
        }
    }

    can summarize with Root exit {
        report [{
            "total": self.total,
            "completed": self.completed,
            "pending": self.total - self.completed,
            "completion_rate": (self.completed / self.total * 100) if self.total > 0 else 0.0,
            "points_burned": self.effort_done,
            "points_total": self.effort_total,
        }];
    }
}
```

