```jac
"""Team task board capstone: priv CRUD, aggregate stats, access hook."""

node Board {
    has name: str;

    # Per-archetype invariant: the board itself is open structure.
    def __jac_access__ -> AccessLevel {
        return AccessLevel.CONNECT;
    }
}

node Task {
    has title: str;
    has assignee: str = "";
    has done: bool = False;
}

edge Boards { }   # root --> Board
edge Holds { }    # Board --> Task

walker:priv open_board {
    has name: str;

    can run with Root entry {
        b = here +>: Boards() :+> Board(name=self.name);
        report {"board": jid(b), "name": b.name};
        print("[OUT]board:", jid(b), b.name);
    }
}

# ------------------------------------------------------------- CRUD set

walker:priv create_task {
    has title: str;
    has assignee: str = "";

    can find with Root entry {
        visit [->:Boards:->];  # land on my boards
    }

    can add with Board entry {
        t = here +>: Holds() :+> Task(title=self.title, assignee=self.assignee);
        grant(t, level=AccessLevel.READ);  # teammates can see the task
        report {"created": jid(t), "title": t.title};
        print("[OUT]created:", jid(t), t.title);
    }
}

walker:priv complete_task {
    has task_id: str;

    can find with Root entry {
        visit [->:Boards:-> ->:Holds:->];  # two hops to every task
    }

    can finish with Task entry {
        if jid(here) == self.task_id {
            here.done = True;
            report {"done": here.title};
            print("[OUT]done:", here.title);
            disengage;
        }
    }
}

walker:priv delete_task {
    has task_id: str;

    can find with Root entry {
        visit [->:Boards:-> ->:Holds:->];
    }

    can remove with Task entry {
        if jid(here) == self.task_id {
            del here;  # detaches its Holds edge automatically
            report {"deleted": self.task_id};
            print("[OUT]deleted:", self.task_id);
            disengage;
        }
    }
}

# -------------------------------------------------------- aggregate stats

walker:priv board_stats {
    has total: int = 0;
    has completed: int = 0;
    has by_assignee: dict[str, int] = {};

    can start with Root entry {
        visit [->:Boards:->];
    }

    can hop with Board entry {
        visit [->:Holds:->];
    }

    can tally with Task entry {
        self.total += 1;
        if here.done {
            self.completed += 1;
        }
        who = here.assignee or "unassigned";
        if who not in self.by_assignee {
            self.by_assignee[who] = 0;
        }
        self.by_assignee[who] += 1;
    }

    can summarize with Root exit {
        rate = (self.completed / self.total * 100) if self.total > 0 else 0.0;
        report {
            "total": self.total,
            "completed": self.completed,
            "open": self.total - self.completed,
            "completion_rate": rate,
            "by_assignee": self.by_assignee,
        };
        print("[OUT]stats:", {
            "total": self.total,
            "completed": self.completed,
            "open": self.total - self.completed,
            "completion_rate": rate,
            "by_assignee": self.by_assignee,
        });
    }
}

with entry {
    b = root spawn open_board(name="sprint 42");
    print("board:", b.reports);

    ids = [];
    for spec in [("wire auth", "kim"), ("seed data", "kim"), ("draft changelog", ""), ("load test", "raj")] {
        r = root spawn create_task(title=spec[0], assignee=spec[1]);
        ids.append(r.reports[0]["created"]);
    }

    root spawn complete_task(task_id=ids[0]);
    root spawn complete_task(task_id=ids[1]);
    root spawn delete_task(task_id=ids[3]);

    stats = root spawn board_stats();
    print("stats:", stats.reports);
}
```

```jac
"""Data center clearance walk: technicians traverse server rooms and are granted or denied per clearance level."""

node ServerRoom {
    has name: str = "";
    has required_level: int = 0;
}

node Corridor {
    has label: str = "";
}

walker Technician {
    has name: str = "Tech";
    has clearance: int = 0;
    has rooms_reached: int = 0;
    has denied_here: bool = False;
    has active: bool = True;

    def report_summary {
        final_count = self.rooms_reached;
        outcome = "DENIED mid-walk" if self.denied_here else "completed full walk";
        print(f"Technician {self.name} reached {final_count} room(s) ({outcome})");
    }

    can start with Root entry {
        print(f"Technician {self.name} (clearance {self.clearance}) begins walkthrough");
        visit [-->];
    }

    can enter_corridor with Corridor entry {
        if not self.active {
            disengage;
        }
        print(f"  Walking through corridor: {here.label}");
        visit [-->];
    }

    can check_room with ServerRoom entry {
        if not self.active {
            disengage;
        }
        if self.clearance >= here.required_level {
            self.rooms_reached += 1;
            print(f"  GRANTED [{self.clearance}>={here.required_level}] -> {here.name}");
            visit [-->];
        } else {
            self.denied_here = True;
            print(f"  DENIED  [{self.clearance}<{here.required_level}] -> {here.name} -- ending walk");
            self.active = False;
            self.report_summary();
            disengage;
        }
    }

    can summarize with exit {
        if self.active {
            self.report_summary();
        }
    }
}

walker Reporter {
    can start with Root entry {
        print("=== Clearance Walkthrough Report ===");
        visit [-->];
    }
}

with entry {
    root ++> Corridor(label="Outer Hall")
        ++> ServerRoom(name="Lobby Server Closet", required_level=1)
        ++> ServerRoom(name="Mail Server Room", required_level=2)
        ++> ServerRoom(name="App Server Room", required_level=3)
        ++> ServerRoom(name="DB Server Room", required_level=4)
        ++> ServerRoom(name="Root Datacenter", required_level=5);

    root spawn Technician(name="Alice", clearance=1);
    root spawn Technician(name="Bob", clearance=3);
    root spawn Technician(name="Carol", clearance=5);
}
