"""Bug tracker: connect a Project to a fresh Ticket and grab the returned node in one expression."""

node Project {
    has name: str = "";
}

node Ticket {
    has title: str = "";
    has priority: str = "low";
}

walker Triage {
    can start with Root entry {
        visit [-->];
    }

    can review with Project entry {
        print(f"Project: {here.name}");
        visit [-->];
    }

    can review_ticket with Ticket entry {
