```jac
"""Toll plaza collector for gate G-4: charge cars, trucks, and motorcycles, then report total revenue."""

node Vehicle {
    has kind: str = "";
    has tons: float = 0.0;
}

walker TollCollector {
    has gate: str = "G-4";
    has total: float = 0.0;

    can start with Root entry {
        print(f"=== Toll booth {self.gate} sweep starting ===");
        visit [-->];
    }

    can charge with Vehicle entry {
        amount = 0.0;
        rate_desc = "";
        if here.kind == "car" {
            amount = 2.50;
            rate_desc = "$2.50 flat";
        } elif here.kind == "truck" {
            amount = 2.50 + (0.50 * here.tons);
            rate_desc = f"$2.50 + $0.50 x {here.tons}t";
        } elif here.kind == "motorcycle" {
            amount = 1.00;
            rate_desc = "$1.00 flat";
        } else {
            rate_desc = "unknown rate";
        }
        weight_str = f", {here.tons}t" if here.kind == "truck" else "";
        print(f"{here.kind.upper()}{weight_str} -> {rate_desc} = ${amount:.2f}");
        self.total = self.total + amount;
        visit [-->];
    }

    can finish with Root exit {
        print(f"Gate {self.gate} revenue: ${self.total:.2f}");
    }
}

with entry {
    root ++> Vehicle(kind="car")
        ++> Vehicle(kind="truck", tons=3.0)
        ++> Vehicle(kind="motorcycle")
        ++> Vehicle(kind="car")
        ++> Vehicle(kind="truck", tons=1.5)
        ++> Vehicle(kind="truck", tons=8.0)
        ++> Vehicle(kind="motorcycle");
    root spawn TollCollector(gate="G-4");
}
```

```jac
"""Vending machine controller: model states as nodes, inputs as walker transitions, and trace an input sequence."""

node VendingMachine {
    has label: str = "idle";
}

walker Input {
    has inputs: list = [];

    can start with Root entry {
        print(f"Starting vending machine simulation with inputs: {self.inputs}");
        visit [-->] else { disengage; }
    }

    can step_machine with VendingMachine entry {
        for i in range(len(self.inputs)) {
            inp = self.inputs[i];
            next_label = here.label;

            if here.label == "idle" {
                if inp == "insert_coin" {
                    next_label = "waiting";
                } else {
                    next_label = "idle";
                }
            } elif here.label == "waiting" {
                if inp == "press_button" {
                    next_label = "vend";
                } else {
                    next_label = "waiting";
                }
            } elif here.label == "vend" {
                if inp == "insert_coin" {
                    next_label = "waiting";
                } else {
                    next_label = "vend";
                }
            }

            print(f"Step {i}: input='{inp}', state '{here.label}' -> '{next_label}'");
            here.label = next_label;
        }

        print(f"Final state: {here.label}");
        disengage;
    }
}

with entry {
    root ++> VendingMachine(label="idle");
    root spawn Input(inputs=["insert_coin", "press_button", "insert_coin", "press_button"]);
}
```

```jac
"""Online store checkout: polymorphic walker reacts to each product type and prints an itemized receipt."""

node Product {
    has name: str = "";
    has price: float = 0.0;
}

node PaperBook(Product) {
    has author: str = "";
    has weight_lb: float = 1.0;
}

node DigitalBook(Product) {
    has author: str = "";
    has file_size_mb: float = 5.0;
}

node Electronics(Product) {
    has warranty_months: int = 12;
}

node Clothing(Product) {
    has size: str = "M";
}

walker Checkout {
    has subtotal: float = 0.0;
    has shipping: float = 0.0;
    has lines: list = [];

    can start with Root entry {
        print("=== ONLINE STORE CHECKOUT ===");
        visit [-->];
    }

    can finish with Root exit {
        total = self.subtotal + self.shipping;
        print("\n--- ITEMIZED RECEIPT ---");
        for line in self.lines {
            print(line);
        }
        print("------------------------");
        print(f"Subtotal: ${self.subtotal:.2f}");
        print(f"Shipping: ${self.shipping:.2f}");
        print(f"TOTAL:    ${total:.2f}");
        print("--- Thank you for shopping! ---");
        disengage;
    }

    can scan_paper with PaperBook entry {
        ship = 3.50 + (here.weight_lb - 1.0) * 0.75;
        ship = ship if ship > 3.50 else 3.50;
        line_total = here.price + ship;
        self.subtotal += here.price;
        self.shipping += ship;
        self.lines.append(
            f"  [BOOK/Paper] {here.name} by {here.author} - ${here.price:.2f}"
        );
        self.lines.append(
            f"      Shipping (paper, {here.weight_lb:.1f} lb): ${ship:.2f}"
        );
        self.lines.append(f"      Line total: ${line_total:.2f}");
    }

    can scan_digital with DigitalBook entry {
        ship = 0.0;
        line_total = here.price + ship;
        self.subtotal += here.price;
        self.shipping += ship;
        self.lines.append(
            f"  [BOOK/Digital] {here.name} by {here.author} ({here.file_size_mb:.1f} MB) - ${here.price:.2f}"
        );
        self.lines.append(f"      Shipping (digital, instant delivery): ${ship:.2f}");
        self.lines.append(f"      Line total: ${line_total:.2f}");
    }

    can scan_electronics with Electronics entry {
        ship = 9.99 + (here.warranty_months / 12.0) * 2.0;
        line_total = here.price + ship;
        self.subtotal += here.price;
        self.shipping += ship;
        self.lines.append(
            f"  [ELECTRONICS] {here.name} ({here.warranty_months}mo warranty) - ${here.price:.2f}"
        );
        self.lines.append(f"      Shipping (insured, warranty handling): ${ship:.2f}");
        self.lines.append(f"      Line total: ${line_total:.2f}");
    }

    can scan_clothing with Clothing entry {
        ship = 5.25;
        line_total = here.price + ship;
        self.subtotal += here.price;
        self.shipping += ship;
        self.lines.append(
            f"  [CLOTHING] {here.name} (size {here.size}) - ${here.price:.2f}"
        );
        self.lines.append(f"      Shipping (soft goods): ${ship:.2f}");
        self.lines.append(f"      Line total: ${line_total:.2f}");
    }
}

with entry {
    cart = root;
    cart ++> PaperBook(name="The Pragmatic Programmer", author="Hunt & Thomas", price=29.99, weight_lb=1.4)
         ++> DigitalBook(name="Refactoring 2e", author="Martin Fowler", price=24.00, file_size_mb=12.5)
         ++> Electronics(name="USB-C Hub", price=49.99, warranty_months=24)
         ++> Clothing(name="Cotton Hoodie", price=39.50, size="L")
         ++> PaperBook(name="Designing Data-Intensive Apps", author="Martin Kleppmann", price=45.00, weight_lb=2.2);
    root spawn Checkout();
}
```

```jac
"""Edge-owned lifetime cancel-cascade demo.

Models the core P1 scenario from issue #1152: lease-bound nodes hold a lease
per open inbound awaited edge. Revocation of the last lease tears the node
down and cascades to its children. Fulfillment buys graceful reclaim at idle,
but a lease ceiling is the activity-blind backstop against never-idle zombies.
"""

# ── Node archetypes ─────────────────────────────────────────────────────────

node Run {
    has name: str = "";
    has is_terminal: bool = False;
    has revoked: bool = False;
}

node Session {
    has name: str = "";
    has is_idle: bool = True;
    has busy: bool = False;
    has lease_count: int = 0;
    has revoked: bool = False;
    has fulfilled: bool = False;
    has churn_steps: int = 0;
}

# ── Typed edges ─────────────────────────────────────────────────────────────

# Ask: parent awaits child → obligation AND lease on the child.
edge Ask {
    has opened: bool = True;
    has responded: bool = False;
}

# Tell: detached spawn → no obligation, no lease.
edge Tell {}

# ── Walker: cascade revoke from a terminal run ──────────────────────────────

walker CancelCascade {
    has torn: list[str] = [];

    # Start at root and walk down through Run nodes.
    can start with Root entry {
        visit [-->];
    }

    # At a Run: only tear down + cascade if it's terminal.
    can run_terminal with Run entry {
        if here.is_terminal and not here.revoked {
            here.revoked = True;
            self.torn.append(f"RUN::{here.name}");
            # Cascade only along lease-bearing (Ask) awaited edges.
            visit [->:Ask:->] else { disengage; }
        } else {
            # Non-terminal or already-revoked Run: stop the cascade.
            # A traversal from a live run must never tear down children.
            disengage;
        }
    }

    # At a Session: decrement lease from upstream revocation; tear down
    # only if the lease count actually hits zero from this revocation.
    can revoke_child with Session entry {
        here.lease_count = here.lease_count - 1;
        if here.lease_count <= 0 and not here.revoked {
            here.revoked = True;
            self.torn.append(f"SESSION::{here.name}(forceful)");
            # Forceful teardown also revokes the child's own outbound
            # awaited (Ask) edges — its asks cascade too.
            visit [->:Ask:->] else { disengage; }
        }
    }
}

# ── Walker: graceful reclaim vs forceful teardown ───────────────────────────

walker IdleReclaim {
    has fulfilled_names: list[str] = [];
    has forceful_names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can reclaim with Session entry {
        if here.revoked {
            # Already forcefully torn — nothing to do, walk on.
            visit [-->] else { disengage; }
            return;
        }
        if here.fulfilled and here.is_idle {
            # Fulfilled + idle → graceful archive.
            self.fulfilled_names.append(here.name);
            visit [-->] else { disengage; }
            return;
        }
        if here.fulfilled and not here.is_idle and here.churn_steps < 3 {
            # Still answering under the ceiling; bump churn and walk on.
            here.churn_steps = here.churn_steps + 1;
            visit [-->] else { disengage; }
            return;
        }
        # Never-idle past the ceiling → forceful sweep.
        self.forceful_names.append(here.name);
        visit [-->] else { disengage; }
    }
}

# ── Demonstration ──────────────────────────────────────────────────────────

with entry {
    # Build the cascade shape: a terminal Run that awaits a child Session,
    # which itself awaits a grandchild Session, plus a detached Tell spawn.
    terminal = Run(name="run-terminal", is_terminal=True);
    worker = Session(name="worker", busy=True);
    grandchild = Session(name="grandchild");
    detached = Session(name="detached");

    # open asks (lease-bearing) and one detached spawn (no lease).
    terminal +>:Ask:+> worker;
    worker +>:Ask:+> grandchild;
    terminal +>:Tell:+> detached;

    # Seed lease counts so the cascade math works out.
    worker.lease_count = 1;
    grandchild.lease_count = 1;

    root ++> terminal;

    # ── Run the cancel cascade ───────────────────────────────────────────
    cascade = CancelCascade();
    root spawn cascade;

    print("Cascade tore (revoked⇒forceful):");
    for name in cascade.torn {
        print(f"  {name}");
    }

    # ── Run the graceful/forceful sweep on a fresh idle graph ────────────
    root del --> terminal;
    del terminal;
    del worker;
    del grandchild;
    del detached;

    a = Session(name="idle-fulfilled", fulfilled=True, is_idle=True);
    b = Session(name="busy-then-idle", fulfilled=True, busy=True, is_idle=False);
    c = Session(name="runaway-zombie", is_idle=False, churn_steps=5);
    root ++> a ++> b ++> c;

    reclaimer = IdleReclaim();
    root spawn reclaimer;

    print("Graceful reclaim (fulfilled⇒graceful):");
    for n in reclaimer.fulfilled_names {
        print(f"  {n}");
    }
    print("Forceful sweep (lease-ceiling backstop):");
    for n in reclaimer.forceful_names {
        print(f"  {n}");
    }
}
