"""Hospital ward door access: nurses and doctors trigger ward responses, visitors do not. Track ward visits per person."""

node Ward {
    has name: str = "";
    has capacity: int = 0;
    has is_icu: bool = False;
}

node Person {
    has badge_id: str = "";
    has role: str = "";
    has wards_entered: int = 0;
}

walker WardEntry {
    has reports: list = [];

    can start with Root entry {
        print("Hospital shift starting — opening ward doors");
        visit [-->];
    }

    can enter_ward with Ward entry {
        ward_label = "ICU" if here.is_icu else "General";
        print(f"  Entering {here.name} ({ward_label})");
        visit [-->];
    }

    can admit_person with Person entry {
        if here.role == "visitor" {
            print(f"  Visitor {here.badge_id} ignored by ward system");
            skip;
        } else {
            here.wards_entered = here.wards_entered + 1;
            ward_type = "ICU" if here.role == "nurse" else "General";
            print(f"  {here.role.title()} {here.badge_id} admitted — visits this shift: {here.wards_entered} ({ward_type} ward)");
            self.reports.append(here);
            skip;
        }
    }
}

with entry {
    icu = Ward(name="ICU-A", capacity=8, is_icu=True);
    general = Ward(name="General-B", capacity=20, is_icu=False);

    nurse_jane = Person(badge_id="N-1024", role="nurse");
    doctor_smith = Person(badge_id="D-7788", role="doctor");
    visitor_joe = Person(badge_id="V-0001", role="visitor");
    nurse_kim = Person(badge_id="N-2099", role="nurse");

    icu ++> general;
    icu ++> nurse_jane;
    icu ++> doctor_smith;
    general ++> visitor_joe;
    general ++> nurse_kim;

    root ++> icu;
    root spawn WardEntry();
}
