```jac
"""Consistency Review Workbench: model one application going through
lifecycle states with an immutable evidence graph and an audit walker
that traverses it.

Entities (node archetypes):
  Application  - the unit of work, owned by a Lifecycle state
  Evidence     - immutable fact attached to an Application
  CheckRun     - freezes (evidence, policy release) into one auditable bundle
  Finding      - a reviewer's output (auto or human) attached to a check run

Relationships (typed edges):
  Application -[:Holds]-> Evidence     (immutable evidence graph)
  Application -[:Produces]-> CheckRun  (each run freezes a release)
  CheckRun    -[:Yields]-> Finding     (findings produced by a run)

The Auditor walker visits each node exactly once using a guard list
(walker visitation is NOT auto-deduped in jac 0.36) and reports a
summary of the application it just walked.
"""

node Application {
    has name: str = "";
    has state: str = "Submitted";
}

node Evidence {
    has kind: str = "";
    has ref: str = "";
    has valid: bool = True;
}

node CheckRun {
    has release_id: str = "";
    has frozen_at: str = "";
}

node Finding {
    has kind: str = "";
    has severity: str = "info";
    has resolved: bool = False;
}

edge Holds {
    has since: str = "v1";
}

edge Produces {
    has release_id: str = "";
}

edge Yields {
    has yielded_at: str = "";
}

walker Auditor {
    has guard: list[str] = [];
    has app_count: int = 0;
    has evidence_count: int = 0;
    has invalid_evidence_count: int = 0;
    has run_count: int = 0;
    has finding_count: int = 0;
    has unresolved_finding_count: int = 0;

    can start with Root entry {
        print("Auditor: beginning review of application graph");
        visit [-->];
    }

    can audit_app with Application entry {
        key = f"App:{here.name}";
        if key in self.guard {
            disengage;
        }
        self.guard.append(key);
        self.app_count += 1;
        print(f"[App] {here.name} state={here.state}");
        visit [-->];
    }

    can audit_evidence with Evidence entry {
        marker = "VALID" if here.valid else "INVALID";
        print(f"  evidence[{marker}] {here.kind} ref={here.ref}");
        self.evidence_count += 1;
        if not here.valid {
            self.invalid_evidence_count += 1;
        }
    }

    can audit_run with CheckRun entry {
        key = f"Run:{here.release_id}";
        if key in self.guard {
            disengage;
        }
        self.guard.append(key);
        self.run_count += 1;
        print(f"  check-run release={here.release_id} frozen={here.frozen_at}");
        visit [-->];
    }

    can audit_finding with Finding entry {
        key = f"Finding:{here.kind}:{self.finding_count}";
        if key in self.guard {
            disengage;
        }
        self.guard.append(key);
        self.finding_count += 1;
        if not here.resolved {
            self.unresolved_finding_count += 1;
        }
        print(f"    finding[{here.severity}] {here.kind} resolved={here.resolved}");
    }
}

with entry {
    app = Application(name="APP-001", state="Submitted");
    ev_a = Evidence(kind="registration_cert", ref="cert-21", valid=True);
    ev_b = Evidence(kind="income_proof", ref="inc-97", valid=True);
    ev_c = Evidence(kind="id_card", ref="id-13", valid=False);

    run1 = CheckRun(release_id="REL-2025-Q1", frozen_at="2025-03-01T10:00");
    run2 = CheckRun(release_id="REL-2025-Q2", frozen_at="2025-06-01T10:00");

    f_auto = Finding(kind="missing_page", severity="warn", resolved=False);
    f_human = Finding(kind="field_mismatch", severity="high", resolved=False);
    f_resolved = Finding(kind="ocr_drift", severity="info", resolved=True);

    root ++> app;
    app +>:Holds:+> ev_a;
    app +>:Holds:+> ev_b;
    app +>:Holds:+> ev_c;
    app +>:Produces(release_id="REL-2025-Q1"):+> run1;
    app +>:Produces(release_id="REL-2025-Q2"):+> run2;
    run1 +>:Yields:+> f_auto;
    run1 +>:Yields:+> f_resolved;
    run2 +>:Yields:+> f_human;

    print("=== Consistency Review (Auditor) ===");
    a = root spawn Auditor();
    print("");
    print("=== Audit summary ===");
    print(f"applications: {a.app_count}");
    print(f"evidence items: {a.evidence_count} (invalid: {a.invalid_evidence_count})");
    print(f"check runs: {a.run_count}");
    print(f"findings: {a.finding_count} (unresolved: {a.unresolved_finding_count})");
}
