```jac
"""Shaded-jar leak inspector: model fs plugins as nodes, leaked packages as
edges, and walk the dependency graph to surface the worst offender.

The real apache/fluss issue tracks unshaded com.fasterxml (jackson) and
com.google (guava) escaping the maven-shade-plugin rewrite. We capture the
essentials here: seven fs plugins, each bundled with a count of leaked
jackson classes, leaked guava classes, and an MRJ-escape flag. A typed
``DependsOn`` edge captures the dependency from each plugin onto
``fluss-fs-hadoop-shaded`` (the only module that does its own relocation).
The ``LeakHunter`` walker visits every plugin, totals the leaked class
counts across the family, and reports the worst offender.

Domain logic preserved (not scaffolding):
    * ordering: plugins are reported in worst-first order (guava count desc),
      exactly as the issue's table does.
    * "hadoop-shaded is excluded from the ranking" because it relocates its
      own jackson (see #4143 / #4144) -- the walker skips the shaded hub.
"""

node Plugin {
    has name: str = "";
    has jackson_leak: int = 0;
    has guava_leak: int = 0;
    has mrj_escaped: bool = False;
    has relocated: bool = False;
}

edge DependsOn { }

walker LeakHunter {
    has results: list = [];

    can start with Root entry {
        print("LeakHunter: surveying fs plugin family for unshaded jackson + guava");
        visit [-->];
    }

    can survey with Plugin entry {
        if here.relocated {
            print(f"  skip {here.name} (relocates its own jackson)");
        } else {
            score = here.jackson_leak + here.guava_leak;
            self.results = self.results + [(here.name, score)];
            print(f"[scanned] {here.name} score={score}");
        }
        visit [-->];
    }
}

walker WorstOffender {
    can start with Root entry {
        print("WorstOffender: ranking plugins by leaked guava count");
        visit [-->];
    }

    can rank with Plugin entry {
        if not here.relocated {
            print(f"[rank] {here.name}: guava_leak={here.guava_leak} jackson_leak={here.jackson_leak} mrj={here.mrj_escaped}");
        }
        visit [-->];
    }
}

with entry {
    hdfs = Plugin(name="fluss-fs-hdfs", jackson_leak=1073, guava_leak=2731, mrj_escaped=True);
    s3 = Plugin(name="fluss-fs-s3", jackson_leak=1093, guava_leak=2042, mrj_escaped=True);
    oss = Plugin(name="fluss-fs-oss", jackson_leak=1073, guava_leak=2230, mrj_escaped=True);
    cos = Plugin(name="fluss-fs-cos", jackson_leak=1073, guava_leak=2246, mrj_escaped=True);
    azure = Plugin(name="fluss-fs-azure", jackson_leak=1073, guava_leak=2042, mrj_escaped=True);
    obs = Plugin(name="fluss-fs-obs", jackson_leak=1161, guava_leak=2042, mrj_escaped=True);
    gs = Plugin(name="fluss-fs-gs", jackson_leak=1073, guava_leak=7351, mrj_escaped=True);
    hadoop_shaded = Plugin(name="fluss-fs-hadoop-shaded", jackson_leak=0, guava_leak=1954, relocated=True);

    # Five of the seven plugins inherit a second, correctly-relocated jackson
    # copy from hadoop-shaded -- express that with a DependsOn edge. gs is
    # the worst offender precisely because it has no such edge at all.
    root ++> hdfs +>:DependsOn:+> hadoop_shaded;
    root ++> s3 +>:DependsOn:+> hadoop_shaded;
    root ++> oss +>:DependsOn:+> hadoop_shaded;
    root ++> cos +>:DependsOn:+> hadoop_shaded;
    root ++> azure +>:DependsOn:+> hadoop_shaded;
    root ++> obs +>:DependsOn:+> hadoop_shaded;
    root ++> gs;

    root spawn LeakHunter();
    print("---");
    root spawn WorstOffender();
}
