    has role_scope_ok: bool = False;
    has review_ok: bool = False;
    has claim_boundary_approved: bool = False;
    has all_pass: bool = False;

    can start with Root entry {
        print(f"Auditing evidence package: {self.package_title}");
        visit [-->];
    }

    can gather_source with SourceArtifact entry {
        self.source_authorized = here.release_backed;
        visit [-->];
    }

    can gather_manifest with Manifest entry {
        self.manifest_ok = here.member_count > 0;
        visit [-->];
    }

    can gather_portfolio with PortfolioDigest entry {
        self.portfolio_ok = here.selection != "";
        visit [-->];
    }

    can gather_role with Review entry {
