        self.review_ok = here.approved;
        visit [-->];
    }

    can gather_claim with ClaimBoundary entry {
        self.claim_boundary_approved = here.approved;
        visit [-->];
    }

    can judge with EvidencePackage entry {
        self.checksum_ok = here.sha256 != "";
        self.pkg_ref = here;
        visit [-->];
    }

    can propagate with DownstreamFigure entry {
        self.all_pass = self.source_authorized
            and self.checksum_ok
            and self.manifest_ok
            and self.portfolio_ok
            and self.role_scope_ok
            and self.claim_boundary_approved;
        if self.pkg_ref is not None {
            self.pkg_ref.admitted = self.all_pass;
            if self.all_pass {
                print(f"ADMITTED: {self.pkg_ref.title} (sha256={self.pkg_ref.sha256[:12]}...)");
            } else {
                print(f"BLOCKED: {self.pkg_ref.title} — fail-closed (reason: stop rule)");
            }
        }
        here.refreshed = self.all_pass and self.claim_boundary_approved;
        status = "refreshed" if here.refreshed else "withheld";
        print(f"[{status}] downstream figure: {here.title}");
        visit [-->] else { disengage; }
    }
}

with entry {
