```jac
"""Container mount contract demo: model workspaces, worktrees, and cache
placement as a graph, then walk it with a ContainmentAuditor walker that
verifies path parity, secrets visibility, uid ownership, and cache sharing.

The scenario mirrors the loom #6898 mount contract: a host workspace root
is mounted at an identical absolute path inside a session container so that
git worktrees (which store absolute paths in `.git` worktree files and
`gitdir` back-pointers) keep functioning. A negative case mounts the same
worktree at a non-parity path and the walk must flag the broken worktree,
the hidden secrets, the wrong uid, and the per-worktree cache as contract
violations.
"""

node WorkspaceRoot {
    has host_path: str = "/home/loom/workspaces";
    has container_path: str = "/home/loom/workspaces";
    has owner_uid: int = 1000;
    has parity_ok: bool = True;
}

node Worktree {
    has name: str = "";
    has branch: str = "";
    has commit_count: int = 0;
    has reachable_from_host: bool = True;
    has absolute_paths_resolve: bool = True;
}

node SecretsDir {
    has kind: str = "";
    has mode: str = "ro";
    has baked_into_image: bool = False;
    has path: str = "";
}

node BuildCache {
    has cache_kind: str = "";
    has host_path: str = "";
    has shared_across_worktrees: bool = True;
}

edge Hosts {
    has mount_kind: str = "parity";
}

edge MountsSecret {
    has visibility: str = "ro";
}

edge ServesCache {
    has scope: str = "host-shared";
}

walker ContainmentAuditor {
    has violations: list[str] = [];
    has checks_run: int = 0;

    can start with Root entry {
        print("=== Containment audit: mount contract verification ===");
        visit [-->];
    }

    can audit_root with WorkspaceRoot entry {
        self.checks_run += 1;
        parity_label = "PARITY" if here.parity_ok else "REMAPPED";
        print(f"workspace mount [{parity_label}]: {here.host_path} -> {here.container_path} (uid {here.owner_uid})");
        if here.host_path != here.container_path {
            self.violations.append(f"path remap breaks worktree absolute paths: {here.host_path} != {here.container_path}");
        }
        if here.owner_uid != 1000 {
            self.violations.append(f"workspace uid {here.owner_uid} != image uid 1000");
        }
        visit [-->];
    }

    can audit_worktree with Worktree entry {
        self.checks_run += 1;
        status = "OK" if (here.reachable_from_host and here.absolute_paths_resolve) else "BROKEN";
        print(f"worktree {here.name} @ {here.branch}: commits={here.commit_count} status={status}");
        if not here.reachable_from_host {
            self.violations.append(f"worktree {here.name}: commits not visible to host (non-parity mount)");
        }
        if not here.absolute_paths_resolve {
            self.violations.append(f"worktree {here.name}: .git worktree links cannot resolve absolute paths");
        }
        visit [-->];
    }

    can audit_secret with SecretsDir entry {
        self.checks_run += 1;
        flag = "BAKED" if here.baked_into_image else "MOUNTED";
        print(f"secret {here.kind} [{here.mode}] at {here.path}: {flag}");
        if here.baked_into_image {
            self.violations.append(f"secret {here.kind} must not be baked into image");
        }
        visit [-->];
    }

    can audit_cache with BuildCache entry {
        self.checks_run += 1;
        share_label = "SHARED" if here.shared_across_worktrees else "PER-WORKTREE";
        print(f"cache {here.cache_kind} at {here.host_path}: {share_label}");
        if not here.shared_across_worktrees {
            self.violations.append(f"cache {here.cache_kind} must be shared across worktrees (rebuild-storm hazard)");
        }
        visit [-->];
    }

    can summarize with Root entry {
        print("--- audit summary ---");
        print(f"checks run: {self.checks_run}");
        if self.violations {
            print(f"violations: {len(self.violations)}");
            for v in self.violations {
                print(f"  - {v}");
            }
        } else {
            print("violations: none (contract holds)");
        }
    }
}

