"""Folder Projection Plan validation: model hash-bound plans, notes, taxonomies, and paths as a graph, then walk it to detect drift, collisions, and unsafe paths."""

node Source {
    has stable_id: str = "";
}

node Note(Source) {
    has title: str = "";
    has basename: str = "";
    has content_hash: str = "";
    has current_path: str = "";
    has materialized_path: str = "";
    has planned_path: str = "";
    has desired_path: str = "";
    has sid: str = "";
}

node TaxonomyNode(Source) {
    has category: str = "";
    has mapping_version: str = "";
    has sid: str = "";
}

node MappingEntry(Source) {
    has from_id: str = "";
    has to_segment: str = "";
    has version: str = "";
    has sid: str = "";
}

edge BelongsTo {
    has since: str = "";
}

edge ProjectsTo {
    has plan_version: str = "";
}

edge BoundBy {
    has input_digest: str = "";
}

walker PlanAuditor {
    has plan_version: str = "v1";
    has input_digest: str = "digest-001";
    has drift_count: int = 0;
    has collision_count: int = 0;
    has exception_count: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        print(f"Auditing plan version={self.plan_version} digest={self.input_digest}");
        visit [-->];
    }

    can traverse with TaxonomyNode | MappingEntry entry {
        node_id = here.sid;
        already = False;
        for v in self.visited {
            if v == node_id {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.visited.append(node_id);
        visit [-->];
    }

    can audit with Note entry {
        collision = False;
        if here.content_hash == "stale-hash" {
            self.drift_count += 1;
        }
        if here.planned_path == "/docs/2024//draft" {
            self.collision_count += 1;
            collision = True;
        }
        if here.basename == "README.md" {
            self.exception_count += 1;
        }
        drift_label = "DRIFT" if self.drift_count > 0 else "OK";
        collision_label = "HIT" if collision else "clear";
        print(f"  note[{here.basename}] planned={here.planned_path} drift={drift_label} collision={collision_label}");
        visit [-->];
    }
}

walker CollisionDetector {
    has seen_paths: list[str] = [];
    has collisions: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can traverse with TaxonomyNode | MappingEntry entry {
        visit [-->];
    }

    can scan with Note entry {
        if here.planned_path != "" {
            dup = False;
            for p in self.seen_paths {
                if p == here.planned_path {
                    dup = True;
                }
            }
            if dup {
                self.collisions.append(here.planned_path);
            } else {
                self.seen_paths.append(here.planned_path);
            }
        }
        visit [-->];
    }
}

walker ExceptionCounter {
    has manual_exceptions: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can traverse with TaxonomyNode | MappingEntry entry {
        visit [-->];
    }

    can count with Note entry {
        if here.basename == "README.md" {
            self.manual_exceptions += 1;
            print(f"  manual-path exception: {here.basename}");
        }
        visit [-->];
    }
}

with entry {
    tax_articles = TaxonomyNode(category="articles", mapping_version="v1", sid="tax-articles");
    tax_notes = TaxonomyNode(category="notes", mapping_version="v1", sid="tax-notes");

    map_a = MappingEntry(from_id="tax-articles", to_segment="articles", version="v1", sid="map-a");
    map_b = MappingEntry(from_id="tax-notes", to_segment="notes", version="v1", sid="map-b");

    note_draft = Note(
        title="draft",
        basename="draft.md",
        content_hash="h-001",
        current_path="/old/draft.md",
        materialized_path="/old/draft.md",
        planned_path="/docs/2024/articles/draft.md",
        desired_path="/docs/2024/articles/draft.md",
        sid="note-draft"
    );
    note_readme = Note(
        title="readme",
        basename="README.md",
        content_hash="h-002",
        current_path="/misc/README.md",
        materialized_path="/misc/README.md",
        planned_path="/docs/2024/notes/README.md",
        desired_path="/docs/2024/notes/README.md",
        sid="note-readme"
    );
    note_stale = Note(
        title="stale",
        basename="stale.md",
        content_hash="stale-hash",
        current_path="/old/stale.md",
        materialized_path="/old/stale.md",
        planned_path="/docs/2024/articles/stale.md",
        desired_path="/docs/2024/articles/stale.md",
        sid="note-stale"
    );
    note_collision = Note(
        title="dup",
        basename="dup.md",
        content_hash="h-003",
        current_path="/x/dup.md",
        materialized_path="/x/dup.md",
        planned_path="/docs/2024//draft",
        desired_path="/docs/2024/articles/dup.md",
        sid="note-dup"
    );

    root +>:BelongsTo(since="init"):+> tax_articles;
    root +>:BelongsTo(since="init"):+> tax_notes;
    tax_articles +>:BelongsTo:+> map_a;
    tax_notes +>:BelongsTo:+> map_b;

    map_a +>:ProjectsTo(plan_version="v1"):+> note_draft;
    map_a +>:ProjectsTo(plan_version="v1"):+> note_stale;
    map_a +>:ProjectsTo(plan_version="v1"):+> note_collision;
    map_b +>:ProjectsTo(plan_version="v1"):+> note_readme;

    note_draft +>:BoundBy(input_digest="digest-001"):+> note_readme;
    note_readme +>:BoundBy(input_digest="digest-001"):+> note_stale;
    note_stale +>:BoundBy(input_digest="digest-001"):+> note_collision;

    auditor = PlanAuditor(plan_version="v1", input_digest="digest-001");
    root spawn auditor;
    print(f"drift={auditor.drift_count} collisions={auditor.collision_count} exceptions={auditor.exception_count}");

    detector = CollisionDetector();
    root spawn detector;
    print(f"detected {len(detector.collisions)} planned-path collisions: {detector.collisions}");

    counter = ExceptionCounter();
    root spawn counter;
    print(f"manual-path exceptions surfaced: {counter.manual_exceptions}");
}
