"""Branch hygiene model: branches as nodes, audit a graph of merge/PR state with walkers.

Models the branch-hygiene report: each branch is a node, edges encode
merge-PR relationships, and a walker traverses the dependency graph to
classify branches into safe-to-delete / keep / review buckets.
"""

node Branch {
    has name: str = "";
    has last_commit: str = "";
    has ahead_of_main: int = 0;
    has verdict: str = "unreviewed";
}

node PullRequest {
    has pr_id: int = 0;
    has status: str = "draft";
    has category: str = "";
}

edge MergedInto {
    has merged_on: str = "";
    has via_pr: int = 0;
}

edge TrackedBy {
    has pr_id: int = 0;
}

edge SupersededBy {
    has reason: str = "";
}

walker BranchAuditor {
    has safe_to_delete: list[str] = [];
    has keep_branches: list[str] = [];
    has review_branches: list[str] = [];

    can start with Root entry {
        print("=== Branch Hygiene Audit ===");
        visit [-->] else { disengage; }
    }

    can audit with Branch entry {
        bucket = "review";
        if here.verdict == "merged" {
            bucket = "safe";
            self.safe_to_delete.append(here.name);
        } elif here.verdict == "tracked" {
            bucket = "keep";
            self.keep_branches.append(here.name);
        } else {
            self.review_branches.append(here.name);
        }
        print(f"[{bucket.upper()}] {here.name} (last commit {here.last_commit})");
    }
}

with entry {
    # Merged branches - safe to delete
    b1 = Branch(name="automated/firebase-optimization", last_commit="2026-05-03", verdict="merged");
    b2 = Branch(name="feature/beta-testing-workflow", last_commit="2026-02-10", verdict="merged");
