    b7 = Branch(name="feature/certification-system", last_commit="2026-05-09", ahead_of_main=1, verdict="orphaned");
    b8 = Branch(name="claude/session-start-hook-3Pk8d", last_commit="2026-07-01", ahead_of_main=1, verdict="orphaned");

    # Pull requests tracking optimizer branches
    pr1 = PullRequest(pr_id=26, status="draft", category="dead-code");
    pr2 = PullRequest(pr_id=31, status="draft", category="performance");
    pr3 = PullRequest(pr_id=42, status="draft", category="security");

    # Build the graph: root -> branches
    root ++> b1;
    root ++> b2;
    root ++> b3;
    root ++> b4;
    root ++> b5;
    root ++> b6;
    root ++> b7;
    root ++> b8;

    # Merged branches connect to root (representing main) via MergedInto edge
    b1 +>:MergedInto(merged_on="2026-05-09", via_pr=8):+> root;
    b2 +>:MergedInto(merged_on="2026-02-15", via_pr=0):+> root;
