```jac
"""Build-system dependency graph: model sources, outputs, and rules as nodes,
then walk the graph to discover which outputs are stale and must be rebuilt.

Each `Source` carries a timestamp (the moment it last changed). Each `Output`
also carries a timestamp (the moment it was last produced). A `BuildRule`
ties an output to its source set, and a `Build` walker traverses the
`DependsOn` edges from outputs back to sources to decide, per output,
whether its sources are newer than itself (rebuild needed / STALE) or
older (up-to-date / FRESH). The walker carries the currently-checked
output's mtime along so it can compare each visited source against it.
"""

node Source {
    has name: str = "";
    has mtime: int = 0;
}

node Output {
    has name: str = "";
    has mtime: int = 0;
}

node BuildRule {
    has label: str = "";
    has visited: bool = False;
}

edge DependsOn { has weight: int = 1; }

walker Build {
    has out_to_rebuild: list[str] = [];
    has checking: str = "";
    has current_out_mtime: int = 0;

    can start with Root entry {
        print("Build dependency check starting from root...");
        visit [-->];
    }

    can walk_outputs with Output entry {
        self.checking = here.name;
        self.current_out_mtime = here.mtime;
        print(f"checking output: {here.name} (mtime={here.mtime})");
        visit [-->];
    }

    can walk_rules with BuildRule entry {
        # Reset visited flag so this rule can be inspected freshly per walk.
        here.visited = True;
        print(f"  rule: {here.label}");
        visit [-->];
    }

    can decide with Source entry {
        # Compare source mtime against the output we are currently checking.
        src_name = here.name;
        if here.mtime > self.current_out_mtime {
            verdict = "STALE";
        } else {
            verdict = "FRESH";
        }
        print(f"    source {src_name} mtime={here.mtime} -> {verdict}");
    }
}

walker Cascade {
    # Demonstrates invalidation: starting at an output, walk back through
    # DependsOn edges and mark every reachable rule visited=False so a
    # later build sees a clean slate.
    has invalidated: list[str] = [];

    can start with Root entry {
        print("Cascade invalidation sweep starting...");
        visit [-->];
    }

    # Walk through Output nodes on the way to BuildRule children;
    # without this hop, the `invalid` handler below never fires.
    can walk_outputs with Output entry {
        visit [-->];
    }

    can invalid with BuildRule entry {
        if here.visited {
            here.visited = False;
            self.invalidated.append(here.label);
            print(f"  invalidated rule: {here.label}");
        }
        visit [-->];
    }
}

with entry {
    src1 = Source(name="main.c", mtime=100);
    src2 = Source(name="util.c", mtime=120);
    src3 = Source(name="lib.c", mtime=80);

    out1 = Output(name="app.bin", mtime=90);
    out2 = Output(name="util.o", mtime=125);

    rule1 = BuildRule(label="compile-app");
    rule2 = BuildRule(label="compile-util");

    root +>:DependsOn(weight=2):+> out1;
    out1 +>:DependsOn(weight=1):+> rule1;
    rule1 +>:DependsOn:+> src1;
    rule1 +>:DependsOn:+> src2;

    root +>:DependsOn(weight=1):+> out2;
    out2 +>:DependsOn:+> rule2;
    rule2 +>:DependsOn:+> src2;
    rule2 +>:DependsOn:+> src3;

    rule1.visited = True;
    rule2.visited = True;

    root spawn Build();
    print("--- cascade invalidation ---");
    casc = root spawn Cascade();
    print(f"invalidated rules: {casc.invalidated}");
}
