```jac
"""SFTP transfer plan walker: bounds the tree walk with depth + size caps and a cycle guard.

Models the essential scenario from SkerrySSH issue #306: a walker that descends
a tree of directories and files, but now bounded by max depth, max plan size,
and a visited path set so that self-referencing directory cycles terminate
cleanly with a typed failure instead of blowing the stack.
"""

node PlanNode {
    has path: str = "";
    has kind: str = "file";  # "file" or "dir"
}

edge Child {
    has name: str = "";
}

walker TransferWalker {
    has max_depth: int = 64;
    has max_entries: int = 10000;
    has entries: list[str] = [];
    has dirs: list[str] = [];
    has truncated: bool = False;
    has cycle_detected: bool = False;
    has failure: str = "";

    can start with Root entry {
        print("TransferWalker: planning transfer");
        visit [-->];
    }

    can descend with PlanNode entry {
        if self.failure != "" {
            disengage;
        }

        # Track visited directory paths FIRST so a directory that points back
        # to itself is detected before we recurse into it again.
        if here.kind == "dir" {
            if here.path in self.dirs {
                self.cycle_detected = True;
                self.failure = "CycleDetected";
                print(f"  cycle at {here.path}; aborting");
                disengage;
            }
            self.dirs.append(here.path);
        }

        # Depth cap: the original plan was unbounded in both axes.
        depth = here.path.count("/");
        if depth > self.max_depth {
            self.failure = "MaxDepthExceeded";
            print(f"  depth cap {self.max_depth} hit at {here.path}");
            disengage;
        }

        # Size cap: bound the total entries in the plan.
        if len(self.entries) + len(self.dirs) >= self.max_entries {
            self.truncated = True;
            self.failure = "MaxEntriesExceeded";
            print(f"  entries cap {self.max_entries} hit");
            disengage;
        }

        if here.kind == "file" {
            status = "OK" if here.path != "" else "EMPTY";
            self.entries.append(here.path);
            print(f"  [FILE {status}] {here.path}");
        } else {
            print(f"  [DIR] {here.path}/");
        }

        visit [-->];
    }
}

with entry {
    # Build a small but cyclic tree of PlanNodes connected by Child edges:
    #   root -> projects -> src -> main.py
    #                       \-> tests -> test_main.py
    #                       \-> loop (a directory whose child is itself)
    projects = PlanNode(path="projects", kind="dir");
    src = PlanNode(path="projects/src", kind="dir");
    main_py = PlanNode(path="projects/src/main.py", kind="file");
    tests = PlanNode(path="projects/tests", kind="dir");
    test_py = PlanNode(path="projects/tests/test_main.py", kind="file");

    root +>:Child(name="projects"):+> projects;
    projects +>:Child(name="src"):+> src;
    src +>:Child(name="main.py"):+> main_py;
    projects +>:Child(name="tests"):+> tests;
    tests +>:Child(name="test_main.py"):+> test_py;

    # Attach the self-referencing cycle that reproduces the bug.
    loop_dir = PlanNode(path="projects/loop", kind="dir");
    projects +>:Child(name="loop"):+> loop_dir;
    loop_dir +>:Child(name="loop"):+> loop_dir;

    print("=== unbounded-style run (caps off) would StackOverflow here ===");
    w = TransferWalker(max_depth=64, max_entries=10000);
    root spawn w;
    if w.failure != "" {
        print(f"plan failed cleanly: {w.failure} "
              f"(cycle={w.cycle_detected}, truncated={w.truncated})");
    } else {
        print(f"plan ok: {len(w.entries)} files, {len(w.dirs)} dirs");
    }

    print("");
    print("=== second run with tighter caps to show the depth cap path ===");
    w2 = TransferWalker(max_depth=2, max_entries=10000);
    root spawn w2;
    if w2.failure != "" {
        print(f"plan failed cleanly: {w2.failure}");
    } else {
        print(f"plan ok: {len(w2.entries)} files, {len(w2.dirs)} dirs");
    }
}
