        local_check="2394 pass / 0 fail; tsc clean except pre-existing onnx",
    );

    root ++> runtime;
    root ++> parser;
    root ++> brain;
    root ++> integration;

    print("=== Auditor: walk lanes, claims, blockers, handoffs ===");
    a = Auditor();
    root spawn a;
