```jac
"""OpenMS ownership-policy audit walker.

Models the essential scenario from OpenMS issue #9792: pyOpenMS bindings
have no coherent copy-vs-alias semantics. Each element accessor must be
classified as OwnedCopy, AliasView, or CachedSingleton, and the rules
(``get_*`` => owned, ``*_view`` => alias under keep-alive, singletons
detached from the registry) must be enforced by walking the binding
graph and flagging violations.
"""

node Binding {
    has name: str = "";
    has category: str = "";      # OwnedCopy | AliasView | CachedSingleton
    has returns_alias: bool = False;
    has keep_alive: bool = False;
    has follows_rule: bool = True;
}

node Param {
    has name: str = "";
    has is_singleton: bool = False;
    has detached: bool = False;
}

edge Returns { }
edge Holds { }
edge ReturnsView {
    has keep_alive: bool = True;
}

walker OwnershipAuditor {
    has violations: list = [];
    has audited: int = 0;

    can begin with Root entry {
        print(f"=== Ownership audit starting ===");
        visit [-->];
    }

    can audit_param with Param entry {
        # Singletons must be detached from any global registry, otherwise
        # callers receive an aliased reference whose lifetime they do
        # not own -- the exact use-after-free class #9794 fixed.
        if here.is_singleton and not here.detached {
            self.violations = self.violations + [
                f"[V-9] singleton '{here.name}' is still attached to the registry"
            ];
        }
        visit [-->];
    }

    can audit_binding with Binding entry {
        self.audited = self.audited + 1;
        name = here.name;
        # Rule R-1: get_* accessors must return owned copies, never aliases.
        if name.startswith("get_") and here.returns_alias {
            self.violations = self.violations + [
                f"[R-1] '{name}' is a get_* that returns an alias"
            ];
            here.follows_rule = False;
        }
        # Rule R-3: aliases must be opt-in; bare getters must not alias.
        # Only fires when R-1 did not already cover this binding (R-1 is
        # more specific for get_* accessors and supersedes R-3).
        elif here.returns_alias and not here.keep_alive and not name.endswith("_view") {
            self.violations = self.violations + [
                f"[R-3] '{name}' returns an alias without an opt-in name"
            ];
            here.follows_rule = False;
        }
        # Rule R-2: *_view accessors may alias only if paired with keep-alive.
        if name.endswith("_view") and here.returns_alias and not here.keep_alive {
            self.violations = self.violations + [
                f"[R-2] '{name}' aliases without keep-alive contract"
            ];
            here.follows_rule = False;
        }
        status = "OK" if here.follows_rule else "FAIL";
        print(f"  [{status}] {here.name} -> {here.category}");
        visit [-->];
    }

    can summarize with Root exit {
        print(f"=== Audit complete: {self.audited} bindings, "
              f"{len(self.violations)} violations ===");
        for v in self.violations {
            print(f"  {v}");
        }
    }
}

with entry {
    # --- a clean Param registry -----------------------------------------
    detached_cv = Param(name="CVTerm", is_singleton=True, detached=True);
    attached_cv = Param(name="LegacyCV", is_singleton=True, detached=False);
    root ++> detached_cv;
    root ++> attached_cv;

    # --- the binding surface (#9947 reference shape) --------------------
    good_getter = Binding(name="get_intensity", category="OwnedCopy");
    good_view = Binding(
        name="spectrum_view", category="AliasView",
        returns_alias=True, keep_alive=True
    );
    bad_getter = Binding(
        name="get_peaks_ref", category="AliasView",
        returns_alias=True, keep_alive=False
    );
    bad_unnamed_alias = Binding(
        name="fetch_meta", category="AliasView",
        returns_alias=True, keep_alive=False
    );
    bare_view_no_keepalive = Binding(
        name="mz_view", category="AliasView",
        returns_alias=True, keep_alive=False
    );

    # Param -> Binding relationship: a param "holds" its accessors.
    detached_cv +>:Holds:+> good_getter;
    detached_cv +>:Holds:+> good_view;
    attached_cv +>:Holds:+> bad_getter;
    attached_cv +>:Holds:+> bad_unnamed_alias;
    attached_cv +>:Holds:+> bare_view_no_keepalive;

    # --- spawn the auditor on the root graph ----------------------------
    root spawn OwnershipAuditor();
}
```

```jac
"""Ontology shortest-path finder.

Models the scenario from issue #176: pick a source and target entity in an
ontology graph and have a walker find the shortest path between them along
``subClassOf`` (and optionally other object properties). The walker
preserves the cycle guard that the hand-rolled ``rdflib`` + ``networkx``
script needs (and that the project author flagged as something to keep
robust) by tracking a visited set explicitly, and falls back to a clean
"no path" report when the two entities live in disconnected components.
"""

# --- Edge archetypes ----------------------------------------------------
# Every relationship in the graph carries meaning, so each is a typed edge.
# The payload is the property name so the printed path can label each hop.

edge SubClassOf {
    has property_name: str = "subClassOf";
}

edge EquivalentTo {
    has property_name: str = "equivalentClass";
}

edge RelatedTo {
    has property_name: str = "related";
}

# A polymorphic base so the union ability in ``PathFinder`` can touch
# every entity through one trigger. Mirrors the "is this a real entity?"
# check the original networkx script performs before adding nodes.

node _EntityBase {
    has name: str = "";
}

node ClassNode(_EntityBase) {
    has label: str = "";
}

node IndividualNode(_EntityBase) {
    has label: str = "";
    has of_class: str = "";
}

node SKOSNode(_EntityBase) {
    has pref_label: str = "";
}

# --- Walker -------------------------------------------------------------
# A BFS that records the trail. The issue is explicit: "Keep it robust for
# large graphs (bound the work, handle disconnected components)." So the
# walker uses an explicit visited set (jac 0.36.1 has no built-in
# dedupe-on-visit) and reports a clean failure when no path exists.
#
# The walker first locates the source node, then performs a BFS from
# there. This ensures that disconnected components attached to ``root``
# are never explored — the search is scoped to the source's component.

walker PathFinder {
    has source: str = "";
    has target: str = "";
    has max_depth: int = 32;
    has visited: list[str] = [];
    has trail: list[str] = [];
    has found: bool = False;
    has hops: int = -1;

    can start with Root entry {
        self.visited = [];
        self.trail = [];
        self.found = False;
        self.hops = -1;
        # Find the source node by name and start the BFS there.
        for child in [-->] {
            if not self.found and child.name == self.source {
                visit child;
            }
        }
    }

    can step with _EntityBase entry {
        if self.found {
            disengage;
        }
        name = here.name;
        if name in self.visited {
            # Cycle guard — hand-rolled BFS keeps an explicit seen set,
            # the walker has to do the same on jac 0.36.1.
            visit [-->];
            disengage;
        }
        self.visited = self.visited + [name];
        self.trail = self.trail + [name];

        if name == self.target {
            self.found = True;
            self.hops = len(self.trail) - 1;
            visit [-->];
            disengage;
        }

        if len(self.trail) > self.max_depth {
            # Bound the work, as the issue requested for large graphs.
            self.trail = self.trail[:-1];
            visit [-->];
            disengage;
        }

        visit [-->];
    }
}

# --- Demo graph ---------------------------------------------------------
# A tiny ontology that exercises every relationship the issue calls out.
# Demonstrates that disconnected components are handled cleanly.

with entry {
    # Helper to create a labelled entity node.
    def make_node(label: str, kind: str) -> _EntityBase {
        if kind == "class" {
            return ClassNode(name=label, label=label);
        }
        if kind == "individual" {
            return IndividualNode(name=label, label=label, of_class="");
        }
        return SKOSNode(name=label, pref_label=label);
    }

    # Build the graph. Each "+>:" line is the typed-edge form the issue
    # is essentially asking us to adopt: the relationship is part of the
    # graph, not something we reconstruct from a parent_id field.
    cat_node = make_node("Cat", "class");
    animal_node = make_node("Animal", "class");
    dog_node = make_node("Dog", "class");
    person_node = make_node("Person", "class");
    human_node = make_node("Human", "class");
    concept_node = make_node("Concept", "class");
    isolated_node = make_node("Unrelated", "class");

    root ++> cat_node
        +>:SubClassOf:+> animal_node
        +>:SubClassOf:+> dog_node
        +>:SubClassOf:+> person_node
        +>:EquivalentTo:+> human_node
        +>:RelatedTo:+> concept_node;
    root ++> isolated_node;

    # --- Case 1: a path that exists ---------------------------------
    finder = PathFinder(source="Cat", target="Person");
    root spawn finder;

    if finder.found {
        print(f"Path: {' -> '.join(finder.trail)} "
              f"({finder.hops} hops)");
    } else {
        print("no path found");
    }

    # --- Case 2: a target in a disconnected component --------------
    finder2 = PathFinder(source="Cat", target="Unrelated");
    root spawn finder2;

    if finder2.found {
        print(f"Path: {' -> '.join(finder2.trail)}");
    } else {
        print(f"no path between {finder2.source} and {finder2.target} "
              f"(disconnected components)");
    }
}
```

```jac
"""Extension install path-traversal defense model.

Demonstrates the core scenario from gemini-cli issue #29076: extension
names must be validated so that ``path.join(extensionsDir, name)``
cannot escape the extensions directory. The model uses a tree of
``Dir`` nodes connected by ``Contains`` edges and ``Extension`` request
nodes. A walker traverses from the root, locates the extensions ``Dir``
subtree, and for every ``Extension`` virtually walks the proposed path
through that subtree to verify the resolved location stays inside the
extensions root.
"""

node Dir {
    has name: str = "";
    has depth: int = 0;
}

node File {
    has name: str = "";
}

node Extension {
    has title: str = "";
    has proposed_name: str = "";
    has is_safe: bool = True;
    has reject_reason: str = "";
}

edge Contains { }

walker PathAuditor {
    has segments: list[str] = [];
    has safe: bool = True;
    has reason: str = "";
    has ext_root_depth: int = 0;
    has current_depth: int = 0;
    has found_ext_root: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can locate with Dir entry {
        if not self.found_ext_root {
            self.found_ext_root = True;
            self.ext_root_depth = here.depth;
            self.current_depth = here.depth;
        }
        visit [-->];
    }

    can audit with Extension entry {
        self.safe = True;
        self.reason = "";
        raw = here.proposed_name.replace("\\", "/");
        segs = raw.split("/");
        if segs == [] or segs == [""] {
            segs = [""];
        }
        # Simulate walking: start at ext_root_depth, process each segment
        depth = self.ext_root_depth;
        rejected = False;
        reject_msg = "";
        if segs[0] == "" {
            rejected = True;
            reject_msg = "absolute path rejected";
        } else {
            for seg in segs {
                if seg == ".." {
                    if depth == self.ext_root_depth {
                        rejected = True;
                        reject_msg = "traversal escapes extensions root";
                        break;
                    }
                    depth = depth - 1;
                } elif seg != "" {
                    depth = depth + 1;
                }
            }
        }
        self.safe = not rejected;
        self.reason = reject_msg;
        label = "ACCEPT" if self.safe else "REJECT";
        tail = f" ({self.reason})" if not self.safe else "";
        print(f"[{label}] '{here.title}' -> '{here.proposed_name}'" + tail);
        disengage;
    }

    can land with File entry {
        return;
    }
}

with entry {
    extensions_dir = Dir(name="extensions", depth=0);
    tools_dir = Dir(name="tools", depth=1);
    linters_dir = Dir(name="linters", depth=2);
    cache_dir = Dir(name="cache", depth=0);

    root ++> extensions_dir;
    extensions_dir +>:Contains:+> tools_dir;
    tools_dir +>:Contains:+> linters_dir;
    root ++> cache_dir;

    good_ext = Extension(title="safe-ext", proposed_name="tools/linters");
    traversal_ext = Extension(title="evil-ext", proposed_name="../../etc/passwd");
    absolute_ext = Extension(title="abs-ext", proposed_name="/usr/local/bin");
    sibling_ext = Extension(title="sibling-ext", proposed_name="../cache/payload");
    plain_ext = Extension(title="plain-ext", proposed_name="plain-name");
    nested_ext = Extension(title="nested-ext", proposed_name="tools/nested/deep");

    root ++> good_ext;
    root ++> traversal_ext;
    root ++> absolute_ext;
    root ++> sibling_ext;
    root ++> plain_ext;
    root ++> nested_ext;

    PathAuditor() spawn root;
}
```

```jac
"""Security: atomically reserve miner bundle root before packaging writes.

Models issue #683 — pathname-based cleanup plus recursive mkdir allows a raced
symlink/junction at the per-platform bundle leaf to redirect cp/writeFile/chmod
outside the bound miner-release root. Reservation must exclusive-create the bundle
directory, verify it is a real directory whose parent remains the bound release
root, and fail closed before any child pathname operation. External sentinel bytes
must remain untouched when the race wins.
"""

edge UnderRelease {
    has canonical: bool = True;
}

edge MaterializedAs {
    has exclusive: bool = False;
}

edge QueuedWrite {
    has pending: bool = True;
}

edge OutsideBoundary {
    has leaked: bool = False;
}

node ReleaseRoot {
    has bound_path: str = "";
    has custody_bound: bool = True;
}

node BundleSlot {
    has platform: str = "";
    has pathname: str = "";
    has phase: str = "idle";
}

node FsObject {
    has path: str = "";
    has outside_target: str = "";

    def is_directory() -> bool {
        return False;
    }

    def is_trap() -> bool {
        return False;
    }
}

node RealDir(FsObject) {
    override def is_directory() -> bool {
        return True;
    }
}

node SymlinkTrap(FsObject) {
    override def is_trap() -> bool {
        return True;
    }
}

node Sentinel {
    has label: str = "";
    has touched: bool = False;
}

node PackageWrite {
    has op: str = "";
    has rel_segment: str = "";
}

walker PathnamePackager {
    has leaked_outside: bool = False;
    has visited_slots: list[str] = [];

    can start with Root entry {
        print("VULNERABLE: pathname cleanup then recursive mkdir without bundle-root custody");
        visit [->:UnderRelease:->] else { disengage; };
    }

    can cross_release with ReleaseRoot entry {
        visit [->:UnderRelease:->] else { disengage; };
    }

    can at_slot with BundleSlot entry {
        if here.pathname in self.visited_slots {
            disengage;
        }
        self.visited_slots.append(here.pathname);
        here.phase = "cleaned";
        visit [->:MaterializedAs:->];
        visit [->:QueuedWrite:->] else { disengage; };
    }

    can follow_trap with SymlinkTrap entry {
        self.leaked_outside = True;
        print(f"VULNERABLE: followed trap to {here.outside_target}");
    }

    can blind_write with PackageWrite entry {
        print(f"VULNERABLE pathname write: {here.op} on {here.rel_segment}");
    }
}

walker BundleReserver {
    has custody_ok: bool = False;
    has reserved: bool = False;
    has fail_closed: bool = False;
    has visited_slots: list[str] = [];

    can start with Root entry {
        print("SECURE: bind miner-release root then exclusive non-recursive bundle reservation");
        visit [->:UnderRelease:->] else { disengage; };
    }

    can bind with ReleaseRoot entry {
        if here.custody_bound {
            self.custody_ok = True;
            visit [->:UnderRelease:->] else { disengage; };
        } else {
            self.fail_closed = True;
            disengage;
        }
    }

    can at_slot with BundleSlot entry {
        if here.pathname in self.visited_slots {
            disengage;
        }
        self.visited_slots.append(here.pathname);
        here.phase = "cleaned";

        if [->:MaterializedAs:->] {
            visit [->:MaterializedAs:->];
        } else {
            here +>:MaterializedAs(exclusive=True):+> (bundle_dir := RealDir(path=here.pathname));
            here.phase = "reserved";
            self.reserved = True;
            visit [->:MaterializedAs:->];
        }
        visit [->:QueuedWrite:->] else { disengage; };
    }

    can verify_fs with RealDir | SymlinkTrap entry {
        if here.is_trap() {
            self.fail_closed = True;
            print(f"FAIL CLOSED: raced bundle symlink trap {here.path} -> {here.outside_target}");
            disengage;
        }
        print(f"verified real bundle directory under bound release root: {here.path}");
    }

    can safe_write with PackageWrite entry {
        if self.fail_closed or not self.custody_ok {
            disengage;
        }
        print(f"handle-bound write: {here.op} on {here.rel_segment}");
    }
}

with entry {
    sentinel = Sentinel(label="outside-miner-release", touched=False);

    release = ReleaseRoot(bound_path="/miner-release", custody_bound=True);
    root +>:UnderRelease:+> release;
    release +>:OutsideBoundary:+> sentinel;

    raced = BundleSlot(
        platform="linux-amd64",
        pathname="/miner-release/linux-amd64"
    );
    release +>:UnderRelease:+> raced;
    trap = SymlinkTrap(
        path="/miner-release/linux-amd64",
        outside_target="/tmp/evil-sentinel"
    );
    raced +>:MaterializedAs:+> trap;
    raced +>:QueuedWrite:+> PackageWrite(op="writeFile", rel_segment="miner.json");

    naive = PathnamePackager();
    root spawn naive;
    sentinel.touched = naive.leaked_outside;
    print(f"naive raced bundle: leaked_outside={naive.leaked_outside}, sentinel.touched={sentinel.touched}");

    clean = BundleSlot(
        platform="darwin-arm64",
        pathname="/miner-release/darwin-arm64"
    );
    release +>:UnderRelease:+> clean;
    clean +>:QueuedWrite:+> PackageWrite(op="cp", rel_segment="miner-runtime/bin");

    guard = BundleReserver();
    root spawn guard;
    print(f"secure clean bundle: reserved={guard.reserved}, fail_closed={guard.fail_closed}, sentinel.touched={sentinel.touched}");
}
