```jac
"""Cloud repository audit: model audit cycles and findings as a graph and walk health checks."""

node Repository {
    has name: str = "";
    has commit: str = "";
}

node AuditCycle {
    has cycle_name: str = "";
    has status: str = "";
}

node Finding {
    has title: str = "";
    has severity: str = "";
    has category: str = "";
}

edge RunsCycle { }

edge ReportsFinding { }

walker CloudAuditor {
    has high_count: int = 0;
    has medium_count: int = 0;
    has low_count: int = 0;
    has blocked: bool = False;

    can start with Root entry {
        self.high_count = 0;
        self.medium_count = 0;
        self.low_count = 0;
        self.blocked = False;
        visit [-->];
    }

    can audit_repo with Repository entry {
        print(f"Auditing {here.name} @ {here.commit[:12]}");
        visit [->:RunsCycle:->];
    }

    can run_cycle with AuditCycle entry {
        status_label = "PASS" if here.status == "PASS" else "FINDINGS";
        print(f"  [{status_label}] cycle: {here.cycle_name}");
        visit [->:ReportsFinding:->];
    }

    can triage with Finding entry {
        if here.severity == "HIGH" {
            self.high_count += 1;
            if here.category == "tests" or here.category == "dependencies" {
                self.blocked = True;
            }
        } elif here.severity == "MEDIUM" {
            self.medium_count += 1;
        } else {
            self.low_count += 1;
        }
        print(f"    [{here.severity}] {here.title} ({here.category})");
        visit [-->];
    }

    can finish with Repository exit {
        verdict = "BLOCKED" if self.blocked else "CLEAR";
        print(
            f"Health verdict: {verdict} — "
            f"{self.high_count} HIGH, {self.medium_count} MEDIUM, "
            f"{self.low_count} LOW"
        );
    }
}

with entry {
    repo = Repository(
        name="Vegapunk",
        commit="f420b8558a0c30f92447a98daad3ced35ee6593d"
    );
    root ++> repo;

    regression = AuditCycle(cycle_name="regression", status="FINDINGS");
    quality = AuditCycle(cycle_name="quality", status="FINDINGS");
    security = AuditCycle(cycle_name="security", status="FINDINGS");
    dependencies = AuditCycle(cycle_name="dependencies", status="FINDINGS");
    performance = AuditCycle(cycle_name="performance", status="FINDINGS");

    repo +>:RunsCycle:+> regression;
    repo +>:RunsCycle:+> quality;
    repo +>:RunsCycle:+> security;
    repo +>:RunsCycle:+> dependencies;
    repo +>:RunsCycle:+> performance;

    regression +>:ReportsFinding:+> Finding(
        title="Test suite blocked by missing deps",
        severity="HIGH",
        category="tests"
    );
    regression +>:ReportsFinding:+> Finding(
        title="Corrupted secret redaction in repo_auditor",
        severity="MEDIUM",
        category="dead-code"
    );
    regression +>:ReportsFinding:+> Finding(
        title="Slack response URL validation weakness",
        severity="LOW",
        category="security"
    );

    quality +>:ReportsFinding:+> Finding(
        title="Unused imports across modules",
        severity="MEDIUM",
        category="dead-code"
    );

    security +>:ReportsFinding:+> Finding(
        title="GitHub API requests missing timeout",
        severity="MEDIUM",
        category="security"
    );

    dependencies +>:ReportsFinding:+> Finding(
        title="301 known vulnerabilities in 44 packages",
        severity="HIGH",
        category="dependencies"
    );

    performance +>:ReportsFinding:+> Finding(
        title="Redundant marketplace search on every keystroke",
        severity="MEDIUM",
        category="performance"
    );

    auditor = CloudAuditor();
