```jac
"""Bounded sitemap ingestion: index recursion, URL filtering, and cycle-safe traversal."""

node Sitemap {
    has loc: str = "";
    has depth: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node SitemapIndex(Sitemap) { }

node UrlSet(Sitemap) { }

node PageUrl {
    has loc: str = "";
    has lastmod: str = "";
    has changefreq: str = "";
    has priority: float = 0.0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Contains { }

edge Lists { }

walker SitemapReader {
    has max_depth: int = 3;
    has max_sitemaps: int = 20;
    has max_urls: int = 100;
    has include_hint: str = "/guide/";
    has exclude_hint: str = "/archive/";
    has modified_since: str = "2026-01-01";
    has visited_sitemaps: list[str] = [];
    has seen_urls: list[str] = [];
    has collected: list[str] = [];
    has sitemap_count: int = 0;
    has rejected_cycle: int = 0;
    has rejected_depth: int = 0;
    has rejected_filter: int = 0;
    has rejected_stale: int = 0;
    has rejected_dup: int = 0;

    def matches_filter(url: str) -> bool {
        if self.exclude_hint and self.exclude_hint in url {
            return False;
        }
        if self.include_hint and self.include_hint not in url {
            return False;
        }
        return True;
    }

    def is_fresh(lastmod: str) -> bool {
        if not self.modified_since or not lastmod {
            return True;
        }
        return lastmod >= self.modified_since;
    }

    def note_sitemap(loc: str) -> bool {
        for v in self.visited_sitemaps {
            if v == loc {
                self.rejected_cycle += 1;
                return False;
            }
        }
        self.visited_sitemaps.append(loc);
        if self.sitemap_count >= self.max_sitemaps {
            return False;
        }
        self.sitemap_count += 1;
        return True;
    }

    def already_seen_url(loc: str) -> bool {
        for u in self.seen_urls {
            if u == loc {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        print(f"SitemapReader bounds: depth={self.max_depth} "
              f"sitemaps={self.max_sitemaps} urls={self.max_urls}");
        visit [-->];
    }

    can crawl with SitemapIndex | UrlSet entry {
        if not self.note_sitemap(here.loc) {
            if self.rejected_cycle > 0 and self.visited_sitemaps[-1:] == [here.loc] {
                # already counted cycle
            }
            print(f"[CYCLE] skip sitemap {here.loc}");
        } elif here.depth > self.max_depth {
            self.rejected_depth += 1;
            print(f"[DEPTH] stop at {here.loc} (depth {here.depth})");
        } else {
            print(f"[SITEMAP] {here.loc} depth={here.depth}");
            visit [->:Contains:->];
            visit [->:Lists:->];
        }
    }

    can collect with PageUrl entry {
        if len(self.collected) >= self.max_urls {
            print(f"[LIMIT] max_urls={self.max_urls} reached");
        } elif self.already_seen_url(here.loc) {
            self.rejected_dup += 1;
            print(f"[DUP] {here.loc}");
        } elif not self.is_fresh(here.lastmod) {
            self.rejected_stale += 1;
            print(f"[STALE] {here.loc} lastmod={here.lastmod}");
        } elif not self.matches_filter(here.loc) {
            self.rejected_filter += 1;
            print(f"[FILTER] {here.loc}");
        } else {
            self.seen_urls.append(here.loc);
            self.collected.append(here.loc);
            meta = f"lastmod={here.lastmod} priority={here.priority}";
            print(f"[KEEP] {here.loc} ({meta})");
        }
    }

    can finish with Root exit {
        print(f"--- ingest summary ---");
        print(f"sitemaps visited: {self.sitemap_count}");
        print(f"urls kept: {len(self.collected)}");
        print(f"rejected cycle={self.rejected_cycle} "
              f"depth={self.rejected_depth} "
              f"dup={self.rejected_dup} "
              f"filter={self.rejected_filter} "
              f"stale={self.rejected_stale}");
        for (i, u) in enumerate(self.collected) {
            print(f"  {i + 1}. {u}");
        }
    }
}

with entry {
    root_index = SitemapIndex(
        loc="https://docs.example.com/sitemap_index.xml",
        depth=0,
        title="Root Index"
    );
    guide_set = UrlSet(
