"""Parser comparison run plan: compile an immutable plan population and independently verify receipt completeness across executions, observation cells, differentials, and performance rows."""

edge PlannedIn { }

edge SpawnsCell { }

node PlannedRow {
    has stable_id: str = "";
    has role: str = "required";
    has accounted: bool = False;
}

node RunPlan {
    has schema_id: str = "parser_comparison_run_plan.v1";
    has profile_digest: str = "";
    has inventory_digest: str = "";
    has plan_digest: str = "";
}

node PlannedExecution(PlannedRow) {
    has case_ref: str = "";
    has subject_ref: str = "";
    has config_ref: str = "";
}

node PlannedCell(PlannedRow) {
    has execution_id: str = "";
    has observer_id: str = "";
    has obligation_id: str = "";
}

node PlannedDifferential(PlannedRow) {
    has left_cell_id: str = "";
    has right_cell_id: str = "";
    has observer_plane: str = "";
}

node PlannedPerformance(PlannedRow) {
    has benchmark_ref: str = "";
    has lifecycle_ref: str = "";
}

walker PlanCompiler {
    has execution_count: int = 0;
    has cell_count: int = 0;
    has differential_count: int = 0;
    has performance_count: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        print("Compiling parser_comparison_run_plan.v1 before any observational work");
        visit [-->];
    }

    can compile with RunPlan entry {
        print(
            f"  policy profile={here.profile_digest} "
            f"inventory={here.inventory_digest}"
        );
        visit [-->];
    }

    can register_execution with PlannedExecution entry {
        if here.stable_id in self.visited {
            disengage;
        }
        self.visited.append(here.stable_id);
        self.execution_count += 1;
        print(
            f"  [EXEC] {here.stable_id}: {here.case_ref} x "
            f"{here.subject_ref} ({here.role})"
        );
        visit [-->];
    }

    can register_cell with PlannedCell entry {
        if here.stable_id in self.visited {
            disengage;
        }
        self.visited.append(here.stable_id);
        self.cell_count += 1;
        obligation = here.obligation_id if here.obligation_id else "none";
        print(
            f"    [CELL] {here.stable_id}: observer={here.observer_id} "
            f"obligation={obligation} ({here.role})"
        );
        visit [-->];
    }

    can register_differential with PlannedDifferential entry {
        if here.stable_id in self.visited {
            disengage;
        }
        self.visited.append(here.stable_id);
        self.differential_count += 1;
        print(
            f"  [DIFF] {here.stable_id}: {here.left_cell_id}|"
            f"{here.right_cell_id} plane={here.observer_plane} ({here.role})"
        );
        visit [-->];
    }

    can register_performance with PlannedPerformance entry {
        if here.stable_id in self.visited {
            disengage;
        }
        self.visited.append(here.stable_id);
        self.performance_count += 1;
        print(
            f"  [PERF] {here.stable_id}: bench={here.benchmark_ref} "
            f"lifecycle={here.lifecycle_ref} ({here.role})"
        );
        visit [-->];
    }
}

walker ReceiptVerifier {
    has required_total: int = 0;
    has accounted_total: int = 0;
    has missing_ids: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        print("Independent verifier: deriving completeness from planned population");
        visit [-->];
    }

    can verify_plan with RunPlan entry {
        print(
            f"  policy profile={here.profile_digest} "
            f"inventory={here.inventory_digest}"
        );
        visit [-->];
    }

    can audit_execution with PlannedExecution entry {
        if here.stable_id in self.visited {
            disengage;
        }
        self.visited.append(here.stable_id);
        if here.role == "required" {
            self.required_total += 1;
            if here.accounted {
                self.accounted_total += 1;
            } else {
                self.missing_ids.append(here.stable_id);
            }
        }
        visit [-->];
    }

    can audit_row with PlannedCell | PlannedDifferential | PlannedPerformance entry {
        if here.stable_id in self.visited {
            disengage;
        }
        self.visited.append(here.stable_id);
        if here.role == "required" {
            self.required_total += 1;
            if here.accounted {
                self.accounted_total += 1;
            } else {
                self.missing_ids.append(here.stable_id);
            }
        }
        visit [-->];
    }
}

with entry {
    plan = RunPlan(
        profile_digest="sha256:9710-profile",
        inventory_digest="sha256:9746-inventory",
        plan_digest="sha256:plan-semantic"
    );

    exec_a = PlannedExecution(
        stable_id="exec-perl-01-ts",
        case_ref="perl-case-01",
        subject_ref="ts-parser-perl",
        config_ref="cfg-exact-manifest"
    );
    exec_b = PlannedExecution(
        stable_id="exec-perl-02-native",
        case_ref="perl-case-02",
        subject_ref="native-perl",
        config_ref="cfg-exact-manifest"
    );

    cell_a = PlannedCell(
        stable_id="cell-perl-01-conformance",
        execution_id="exec-perl-01-ts",
        observer_id="obs-conformance-v3",
        obligation_id="obl-9704-reviewed"
    );
    cell_b = PlannedCell(
        stable_id="cell-perl-02-conformance",
        execution_id="exec-perl-02-native",
        observer_id="obs-conformance-v3",
        obligation_id="obl-9704-reviewed"
    );

    diff_row = PlannedDifferential(
        stable_id="diff-perl-01-pair",
        left_cell_id="cell-perl-01-conformance",
        right_cell_id="cell-perl-02-conformance",
        observer_plane="conformance-v3"
    );

    perf_row = PlannedPerformance(
        stable_id="perf-perl-01-bench",
        benchmark_ref="bench-ref-8462",
        lifecycle_ref="lifecycle-9895"
    );

    root ++> plan;
    plan +>:PlannedIn:+> exec_a;
    plan +>:PlannedIn:+> exec_b;
    plan +>:PlannedIn:+> diff_row;
    plan +>:PlannedIn:+> perf_row;
    exec_a +>:SpawnsCell:+> cell_a;
    exec_b +>:SpawnsCell:+> cell_b;

    compiler = PlanCompiler();
    root spawn compiler;

    exec_a.accounted = True;
    cell_a.accounted = True;
    perf_row.accounted = True;

    verifier = ReceiptVerifier();
    root spawn verifier;

    gap = verifier.required_total - verifier.accounted_total;
    status = "COMPLETE" if gap == 0 else "INCOMPLETE";
    print(
        f"Verifier derived {status}: required={verifier.required_total} "
        f"accounted={verifier.accounted_total} missing={verifier.missing_ids}"
    );
    print(
        f"Compiled population: exec={compiler.execution_count} "
        f"cells={compiler.cell_count} diff={compiler.differential_count} "
        f"perf={compiler.performance_count}"
    );
}
