"""Paket Linux integration recovery: walk failed suites, classify drift clusters, and flag unpinned dependency violations."""

edge InSuite { }

edge InCluster { }

edge AssertsPackage { }

node TestSuite {
    has name: str = "";
    has target: str = "";
    has failed: int = 0;
    has passed: int = 0;
}

node IntegrationTest {
    has issue_id: str = "";
    has title: str = "";
    has passed: bool = False;
}

node FailureCluster {
    has cluster_name: str = "";
    has classification: str = "";
    has remedy: str = "";
}

node PackageSpec {
    has package_name: str = "";
    has constraint_max: int = 0;
    has resolved_major: int = 0;
    has resolved_version: str = "";
}

walker RecoveryAuditor {
    has pins_needed: int = 0;
    has regressions: int = 0;

    can start with Root entry {
        print("=== Paket Linux integration suite recovery audit ===");
        visit [-->];
    }

    can audit_suite with TestSuite entry {
        print(
            f"\nSuite {here.name} [{here.target}]: "
            f"{here.failed} failed, {here.passed} passed"
        );
        if [->:InSuite:->] {
            visit [->:InSuite:->];
        }
    }

    can inspect_test with IntegrationTest entry {
        if here.passed {
            skip;
        }
        print(f"  [FAIL] #{here.issue_id} {here.title}");
        if [->:InCluster:->] {
            visit [->:InCluster:->];
        }
    }

    can classify with FailureCluster entry {
        print(f"    -> {here.cluster_name} [{here.classification}]");
        print(f"       remedy: {here.remedy}");
        if here.classification == "product_regression" {
            self.regressions += 1;
            skip;
        } elif here.classification == "unpinned_feed" {
            if [->:AssertsPackage:->] {
                visit [->:AssertsPackage:->];
            } else {
                skip;
            }
        } else {
            skip;
        }
    }

    can check_package with PackageSpec entry {
        if here.resolved_major >= here.constraint_max {
            print(
                f"       DRIFT: {here.package_name} resolved "
                f"{here.resolved_version} (major {here.resolved_major}) "
                f"violates < {here.constraint_max}"
            );
            self.pins_needed += 1;
        } else {
            print(
                f"       OK: {here.package_name} {here.resolved_version} "
                f"satisfies < {here.constraint_max}"
            );
        }
        skip;
    }
}

with entry {
    web_utilities = PackageSpec(
        package_name="Microsoft.AspNetCore.WebUtilities",
        constraint_max=9,
        resolved_major=10,
        resolved_version="10.0.11"
    );

    feed_drift = FailureCluster(
        cluster_name="Live Feeds & Dependency Resolution",
        classification="unpinned_feed",
        remedy="Pin versions where the test validates Paket, not latest NuGet"
    );
    feed_drift +>:AssertsPackage:+> web_utilities;

    mixed_groups = FailureCluster(
        cluster_name="Mixed group dependencies",
        classification="product_regression",
        remedy="Fix Paket behavior before updating fixtures (#2394, #4183)"
    );

    metadata_drift = FailureCluster(
        cluster_name="Assembly Metadata / Package Name Output",
        classification="stale_expectation",
        remedy="Make nupkg assertions SemVer-aware for CI build metadata"
    );

    fw_restriction = IntegrationTest(
        issue_id="framework-restriction",
        title="apply framework restriction force true/false NuGet v2/v3",
        passed=False
    );
    fw_restriction +>:InCluster:+> feed_drift;

    mix_deps = IntegrationTest(
        issue_id="2394",
        title="mix dependencies from multiple groups with conditions",
        passed=False
    );
    mix_deps +>:InCluster:+> mixed_groups;

    net9 = TestSuite(
        name="Linux integration",
        target="net9",
        failed=13,
        passed=203
    );
    net9 +>:InSuite:+> fw_restriction;
    net9 +>:InSuite:+> mix_deps;

    binding_redirect = IntegrationTest(
        issue_id="1783",
        title="generates binding redirect when assembly version differs in main group",
        passed=False
    );
    binding_redirect +>:InCluster:+> metadata_drift;

    fsharp_core = IntegrationTest(
        issue_id="2528",
        title="sdk-2 install should not warn with FSharp.Core",
