        failed=3,
        passed=55
    );
    net461 +>:InSuite:+> binding_redirect;
    net461 +>:InSuite:+> fsharp_core;

    root ++> net9 ++> net461;

    auditor = root spawn RecoveryAuditor();
    print(
        f"\nAudit complete: {auditor.pins_needed} pin(s) required, "
