```jac
"""Inline diff review pane — Jac demo of flow-ordered narration and read-only Q&A.

Models the essential scenario from JetBrains/ytdb-slate issue #256 natively:
- Commit holds ChangeUnits via :InCommit:
- ChangeUnits order by :DependsOn: (a DAG)
- ChangeUnits :Touches: DiffLine nodes (path/side/line_num/text)
- DiffLine anchors :AnchoredTo: Observation
- DiffLine :AboutLine: Question which :ReplyTo: Answer

Two walkers exercise the structure:
- FlowOrderer — topological order over the unit dependency DAG, cycle guarded
- ReviewReader — read-only review walk: per unit, print the line, observation,
  question, then its read-only answer
"""

# ---------------------------------------------------------------------------
# Node archetypes
# ---------------------------------------------------------------------------

node Commit {
    has sha: str,
        message: str;
}

node ChangeUnit {
    has unit_key: str,
        intent: str;
}

node DiffLine {
    has path: str,
        side: str,
        line_num: int,
        text: str;
}

node Observation {
    has body: str,
        available: bool = True;
}

node Question {
    has text: str;
}

node Answer {
    has text: str,
        read_only: bool = True;
}

# Typed edges
edge InCommit {}
edge DependsOn {}
edge Touches {}
edge AnchoredTo {}
edge AboutLine {}
edge ReplyTo {}

# ---------------------------------------------------------------------------
# Walker: FlowOrderer
# ---------------------------------------------------------------------------

walker FlowOrderer {
    has order: list = [],
        visited: list = [],
        on_stack: list = [],
        slot: int = 0,
        cyclic: bool = False;

    can start with Commit entry {
        print(f"Commit {here.sha}: deriving flow-ordered story");
        # Walk every InCommit child (in declared / insertion order)
        for unit in [->:InCommit:->] {
            self._walk_unit(unit);
        }
        if self.cyclic {
            print("[CYCLE] cyclic unit dependencies detected");
        }
        keys = [u["key"] for u in self.order];
        print(f"Story order: {keys}");
    }

    def _walk_unit(unit: ChangeUnit) {
        # Already fully emitted — skip.
        if unit in self.visited {
            return;
        }
        # Currently on the DFS path — back-edge, cycle.
        if unit in self.on_stack {
            self.cyclic = True;
            return;
        }
        self.on_stack.append(unit);
        # Visit dependencies first (DFS over outgoing DependsOn).
        for dep in [unit ->:DependsOn:->] {
            self._walk_unit(dep);
        }
        self.on_stack = [u for u in self.on_stack if u is not unit];
        self.visited.append(unit);
        self.slot += 1;
        self.order.append({"node": unit, "key": unit.unit_key, "done": True});
        print(f"[{self.slot}] {unit.unit_key} — {unit.intent}");
    }
}

# ---------------------------------------------------------------------------
# Walker: ReviewReader (read-only)
# ---------------------------------------------------------------------------

walker ReviewReader {
    can start with Commit entry {
        print(f"=== Diff review: {here.sha} ===");
        print(f"Commit message: {here.message}");
        for unit in [->:InCommit:->] {
            print(f"## {unit.unit_key} — {unit.intent}");
            for line in [unit ->:Touches:->] {
                print(f"  {line.path}:{line.side}:{line.line_num}  {line.text}");
                for obs in [line ->:AnchoredTo:->] {
                    print(f"  [obs] {obs.body}");
                }
                for q in [line ->:AboutLine:->] {
                    print(f"  [Q] {q.text}");
                    for a in [q ->:ReplyTo:->] {
                        marker = "read-only" if a.read_only else "mutating";
                        print(f"  [A] {a.text} ({marker})");
                    }
                }
            }
        }
    }
}

# ---------------------------------------------------------------------------
# Demonstration
# ---------------------------------------------------------------------------

with entry {
    # Build a small commit graph mimicking the issue's Phase 0/1/2 shape.
    commit = Commit(
        sha="abc1234",
        message="Inline diff review pane with anchored observations",
    );

    u_imports = ChangeUnit(
        unit_key="imports",
        intent="Add shiki tokenizer and parse-diff imports",
    );
    u_parser = ChangeUnit(
        unit_key="hunk-parser",
        intent="Parse hunks into anchorable diff lines",
    );
    u_pane = ChangeUnit(
        unit_key="review-pane",
        intent="Present flow-ordered units in the TUI review pane",
    );

    # Dependency DAG: pane -> parser -> imports
    u_pane +>:DependsOn:+> u_parser;
    u_parser +>:DependsOn:+> u_imports;

    # Attach to the commit (order of attachment does not determine order;
    # the FlowOrderer follows the DependsOn DAG).
    commit +>:InCommit:+> u_imports;
    commit +>:InCommit:+> u_parser;
    commit +>:InCommit:+> u_pane;

    # A diff line touched by the parser, anchored observation + Q&A thread.
    line = DiffLine(
        path="src/review.ts",
        side="new",
        line_num=42,
        text="visit forward else disengage on empty frontier",
    );
    u_parser +>:Touches:+> line;

    obs = Observation(body="Prefer explicit empty-frontier handling over hang.");
    line +>:AnchoredTo:+> obs;

    q = Question(text="Does visit dedupe on dependency cycles?");
    line +>:AboutLine:+> q;

    a = Answer(
        text="No — walkers need an explicit cycle guard.",
        read_only=True,
    );
    q +>:ReplyTo:+> a;

    # Run the flow orderer and the read-only review reader.
    print("--- FlowOrderer ---");
    _ = commit spawn FlowOrderer();

    print("");
    print("--- ReviewReader ---");
    _ = commit spawn ReviewReader();
}
