"""PGR inbox visibility: traverse reporting hierarchy and jurisdiction-filter complaints for My/All tabs."""

node Employee {
    has name: str = "";
    has roles: list[str] = [];
    has jurisdictions: list[str] = [];
}

node Complaint {
    has title: str = "";
    has status: str = "";
    has locality: str = "";
    has assignee: str = "";
    has escalated_from: list[str] = [];
}

edge Manages { }

def states_for(roles: list[str]) -> list[str] {
    allowed: list[str] = [];
    if "GRO" in roles {
        allowed.append("PENDING_L1");
    }
    if "HOD" in roles {
        allowed.append("PENDING_L2");
    }
    return allowed;
}

def in_jurisdiction(locality: str, jurisdictions: list[str]) -> bool {
    return locality in jurisdictions;
}

def queue_match(
    tab: str,
    version: int,
    status: str,
    assignee: str,
    viewer_name: str,
    my_roles: list[str],
    reportee_roles: list[str],
    has_reportees: bool,
    escalated_from: list[str]
) -> bool {
    my_states = states_for(my_roles);
    rep_states = states_for(reportee_roles);
    escalated_away = (viewer_name in escalated_from) and (assignee != viewer_name) and (assignee != "");
    if version == 1 {
        if tab == "my" {
            if escalated_away {
                return False;
            }
            return status in my_states;
        }
        if has_reportees {
            return (status in my_states) or (status in rep_states);
        }
        return status in my_states;
    }
    if tab == "my" {
        if escalated_away {
            return False;
        }
        return assignee == viewer_name;
    }
    mine_bucket = (status in my_states) and ((assignee == viewer_name) or (assignee == ""));
    if version >= 3 {
        if has_reportees {
            return mine_bucket or (status in rep_states) or escalated_away;
        }
        return mine_bucket or escalated_away;
    }
    if has_reportees {
        return mine_bucket or (status in rep_states);
    }
    return mine_bucket;
}

walker ReporteeCollector {
    has max_depth: int = 1;
    has current_depth: int = 0;
    has root_name: str = "";
    has roles: list[str] = [];

    can collect with Employee entry {
        if here.name == self.root_name {
            visit [->:Manages:->] else { disengage; };
        } else {
            for role in here.roles {
                if role not in self.roles {
                    self.roles.append(role);
                }
            }
            next_depth = self.current_depth + 1;
            if next_depth < self.max_depth {
                self.current_depth = next_depth;
                visit [->:Manages:->] else { disengage; };
                self.current_depth = self.current_depth - 1;
            }
        }
    }
}

walker InboxResolver {
    has tab: str = "my";
    has version: int = 1;
    has viewer_name: str = "";
    has viewer_roles: list[str] = [];
    has viewer_jurisdictions: list[str] = [];
    has reportee_roles: list[str] = [];
    has has_reportees: bool = False;
    has hits: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can evaluate with Complaint entry {
        if in_jurisdiction(here.locality, self.viewer_jurisdictions) {
            visible = queue_match(
                self.tab,
                self.version,
                here.status,
                here.assignee,
                self.viewer_name,
                self.viewer_roles,
                self.reportee_roles,
                self.has_reportees,
                here.escalated_from
            );
            if visible {
                self.hits.append(here.title);
            }
        }
        visit [-->];
    }
}

with entry {
    priya = Employee(name="Priya", roles=["HOD"], jurisdictions=["Ward-A", "Ward-B"]);
    ravi = Employee(name="Ravi", roles=["GRO"], jurisdictions=["Ward-A"]);
    meena = Employee(name="Meena", roles=["GRO"], jurisdictions=["Ward-B"]);

    root ++> priya;
    root ++> ravi;
    root ++> meena;
    priya +>:Manages:+> ravi;
