    root ++> Complaint(title="Streetlight out", status="PENDING_L1", locality="Ward-A", assignee="");
    root ++> Complaint(title="Garbage pile", status="PENDING_L1", locality="Ward-A", assignee="Ravi");
    root ++> Complaint(title="Sewer leak", status="PENDING_L2", locality="Ward-B", assignee="Priya");
    root ++> Complaint(title="Remote road crack", status="PENDING_L1", locality="Ward-C", assignee="");
    root ++> Complaint(title="Escalated water main", status="PENDING_L2", locality="Ward-A", assignee="Meena", escalated_from=["Priya"]);

    collector = ReporteeCollector(root_name="Priya", max_depth=1);
    priya spawn collector;
    has_reps = len(collector.roles) > 0;

    print(f"Priya reportee roles (depth 1): {collector.roles}");

    my_v1 = InboxResolver(
