    moe_a0 +>:Routes(gate_weight=0.3):+> e7;

    moe_a1 +>:Routes(gate_weight=1.0):+> e0;
    moe_a1 +>:Routes(gate_weight=0.9):+> e2;
    moe_a1 +>:Routes(gate_weight=0.8):+> e4;
    moe_a1 +>:Routes(gate_weight=0.7):+> e6;
    moe_a1 +>:Routes(gate_weight=0.6):+> e1;
    moe_a1 +>:Routes(gate_weight=0.5):+> e3;
    moe_a1 +>:Routes(gate_weight=0.4):+> e5;
    moe_a1 +>:Routes(gate_weight=0.3):+> e7;

    moe_b0 +>:Routes(gate_weight=1.0):+> e0;
    moe_b0 +>:Routes(gate_weight=0.9):+> e1;
    moe_b0 +>:Routes(gate_weight=0.8):+> e2;
    moe_b0 +>:Routes(gate_weight=0.7):+> e3;
    moe_b0 +>:Routes(gate_weight=0.6):+> e4;
    moe_b0 +>:Routes(gate_weight=0.5):+> e5;
    moe_b0 +>:Routes(gate_weight=0.4):+> e6;
    moe_b0 +>:Routes(gate_weight=0.3):+> e7;

    moe_b1 +>:Routes(gate_weight=1.0):+> e0;
    moe_b1 +>:Routes(gate_weight=0.9):+> e2;
    moe_b1 +>:Routes(gate_weight=0.8):+> e4;
    moe_b1 +>:Routes(gate_weight=0.7):+> e6;
    moe_b1 +>:Routes(gate_weight=0.6):+> e1;
    moe_b1 +>:Routes(gate_weight=0.5):+> e3;
    moe_b1 +>:Routes(gate_weight=0.4):+> e5;
    moe_b1 +>:Routes(gate_weight=0.3):+> e7;

    auditor = ResidencyAuditor();
    root spawn auditor;
    print(auditor.verdict);

    unfused = UnfusedDecode();
    root spawn unfused;
    load_ms = unfused.physical_loads * 0.6;
    wall_ms = unfused.gdn_ms + load_ms;
    tok_rate = (unfused.tokens_done * 1000.0) / wall_ms if wall_ms > 0.0 else 0.0;
    print(
        f"unfused: requests={unfused.routed_requests} "
        f"loads={unfused.physical_loads} hits={unfused.cache_hits} "
        f"syncs={unfused.host_syncs} gdn_ms={unfused.gdn_ms} "
        f"est_tok_s={tok_rate:.2f}"
    );

    fused = FusedDecode();
    root spawn fused;
    fused_load_ms = fused.physical_loads * 0.6;
    fused_wall_ms = fused.gdn_ms + fused_load_ms;
    fused_rate = (fused.tokens_done * 1000.0) / fused_wall_ms if fused_wall_ms > 0.0 else 0.0;
    print(
        f"fused: requests={fused.routed_requests} "
        f"loads={fused.physical_loads} hits={fused.cache_hits} "
        f"layer_syncs={fused.layer_syncs} gdn_ms={fused.gdn_ms} "
        f"est_tok_s={fused_rate:.2f}"
    );
}
