```jac
"""Per-session worker tree: model a Windows Job Object that owns a worker and its
descendants independently of PPID, with a walker that cascades kill across the
whole job regardless of intermediate wrappers exiting.

Nodes:
  Session    — a managed worker session that owns one Job Object.
  Worker     — a long-running process with children (the worker subtree).
  Descendant — child/grandchild of a worker (may outlive intermediates).

Edges:
  OwnsJob    — Session -> Worker (the session claims the worker subtree).
  Spawned    — Worker -> Descendant (parent/child within the subtree).

A walker ``JobInspector`` enters the job and recursively reaches every
descendant, simulating a tree-kill that survives PPID changes; a separate
walker ``SessionCloser`` proves the Job Object boundary tears down the whole
tree on session cleanup.
"""

node Session {
    has name: str = "";
    has job_active: bool = True;
}

node Worker {
    has pid: int = 0;
    has label: str = "";
    has alive: bool = True;
}

node Descendant {
    has pid: int = 0;
    has label: str = "";
    has alive: bool = True;
    has reparented: bool = False;
}

edge OwnsJob {
    has created_at: str = "";
}

edge Spawned {
    has depth: int = 0;
}

walker JobInspector {
    has visited: list = [];
    has survivors_before_close: int = 0;

    can start with Session entry {
        if not here.job_active {
            disengage;
        }
        print(f"[job] entering session '{here.name}' job_object=active");
        visit [->:OwnsJob:->];
    }

    can inspect_worker with Worker entry {
        self.visited.append(("worker", here.pid, here.label));
        print(f"[job] worker pid={here.pid} label={here.label} alive={here.alive}");
        visit [->:Spawned:->];
    }

    can inspect_descendant with Descendant entry {
        self.visited.append(("desc", here.pid, here.label, here.reparented));
        if here.reparented {
            self.survivors_before_close += 1;
            print(f"[job] descendant pid={here.pid} label={here.label} "
                  f"REPARENTED (would escape taskkill /T)");
        } else {
            print(f"[job] descendant pid={here.pid} label={here.label}");
        }
        visit [->:Spawned:->];
    }
}

walker SessionCloser {
    has kill_log: list = [];

    can start with Session entry {
        if not here.job_active {
            disengage;
        }
        here.job_active = False;
        print(f"[close] tearing down job for session '{here.name}'");
        visit [->:OwnsJob:->];
    }

    can kill_worker with Worker entry {
        here.alive = False;
        self.kill_log.append(("worker", here.pid));
        print(f"[close] KILL_ON_JOB_CLOSE -> worker pid={here.pid}");
        visit [->:Spawned:->];
    }

    can kill_descendant with Descendant entry {
        here.alive = False;
        self.kill_log.append(("desc", here.pid));
        note = " (was reparented, but job boundary catches it)" if here.reparented else "";
        print(f"[close] KILL_ON_JOB_CLOSE -> descendant pid={here.pid}{note}");
        visit [->:Spawned:->];
    }
}

with entry {
    s = Session(name="bg-dev-server");
    root +>:OwnsJob(created_at="Mon"):+> s;

    w = Worker(pid=1001, label="root.py");
    s +>:OwnsJob:+> w;

    mid = Descendant(pid=1002, label="mid.py");
    w +>:Spawned(depth=1):+> mid;

    grand = Descendant(pid=1003, label="grand.py", reparented=True);
    mid +>:Spawned(depth=2):+> grand;

    inspector = s spawn JobInspector();
    print(f"[report] survivors that would escape taskkill /T: "
          f"{inspector.survivors_before_close}");

    closer = s spawn SessionCloser();
    print(f"[report] killed_by_job_close: {len(closer.kill_log)} "
          f"(expected 3: worker + 2 descendants)");
}
