```jac
"""Talon local approver principals, flat groups, and policy-authorized decision traversal.

Models normalized principal/group membership and fail-closed approval authorization
over typed edges — admin identity never implies approver authority.
"""

node Principal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has principal_id: str = "";
    has display_name: str = "";
    has is_admin: bool = False;
}

node Group {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has group_id: str = "";
    has name: str = "";
}

node ApprovalRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has request_id: str = "";
    has status: str = "pending";
    has approval_type: str = "action_execution";
    has rejection_reason: str = "";
}

edge MemberOf { }

edge RequiresGroup {
    has binding_digest: str = "policy-v1";
}

walker DecisionAuthorizer {
    has approver_id: str = "";
    has authorized: bool = False;
    has denial_reason: str = "";
    has matched_group: str = "";
    has found_any_policy_group: bool = False;
    has found_any_member: bool = False;

    can authorize with ApprovalRequest entry {
        if here.status != "pending" {
            self.denial_reason = f"{here.request_id}: already {here.status}";
            disengage;
        }
        if self.approver_id == "" {
            self.denial_reason = "missing authenticated approver principal";
            disengage;
        }
        # Traverse to all eligible policy groups via outgoing RequiresGroup edges.
        visit [->:RequiresGroup:->];
    }

    can scan_policy_groups with Group entry {
        self.found_any_policy_group = True;
        # Traverse incoming MemberOf edges to find a matching principal.
        visit [<-:MemberOf:<-];
    }

    can verify_membership with Principal entry {
        self.found_any_member = True;
        if not self.authorized and here.principal_id == self.approver_id and here.available {
            self.authorized = True;
            self.matched_group = "via membership edge";
            disengage;
        }
    }

    can close with ApprovalRequest exit {
        if not self.authorized and self.denial_reason == "" {
            if not self.found_any_policy_group {
                self.denial_reason = (
                    f"{here.request_id}: unresolvable policy groups (fail closed)"
                );
            } else {
                self.denial_reason = (
                    f"principal {self.approver_id} not in any eligible approver group"
                );
            }
        }
    }
}

walker UnauthorizedEvidence {
    has approver_id: str = "";
    has attempt_count: int = 0;

    can record with ApprovalRequest entry {
        self.attempt_count += 1;
        prior_status = here.status;
        print(
            f"[EVIDENCE] unauthorized attempt #{self.attempt_count} by "
            f"{self.approver_id} on {here.request_id} "
            f"(state unchanged: {prior_status})"
        );
        visit [-->] else { disengage; };
    }
}

with entry {
    sec_rev = Group(group_id="grp-sec", name="security-reviewers");
    admins = Group(group_id="grp-admin", name="platform-admins");

    alice = Principal(
        principal_id="alice",
        display_name="Alice Chen",
        available=True,
    );
    bob = Principal(
        principal_id="bob",
        display_name="Bob Smith",
        available=True,
    );
    operator = Principal(
        principal_id="ops-admin",
        display_name="Ops Admin",
        available=True,
        is_admin=True,
    );

    alice +>:MemberOf:+> sec_rev;
    bob +>:MemberOf:+> sec_rev;
    operator +>:MemberOf:+> admins;

    pending = ApprovalRequest(request_id="apr-1001", approval_type="plan_review");
    root ++> pending;
    pending +>:RequiresGroup(binding_digest="org-rule-42"):+> sec_rev;

    alice_auth = pending spawn DecisionAuthorizer(approver_id="alice");
    if alice_auth.authorized {
        pending.status = "approved";
        print(f"AUTHORIZED: alice decided {pending.request_id}");
    } else {
        print(f"DENIED: {alice_auth.denial_reason}");
    }

    bob_retry = pending spawn DecisionAuthorizer(approver_id="bob");
    if bob_retry.authorized {
        pending.status = "approved";
    } else {
        print(f"DENIED: {bob_retry.denial_reason}");
    }

    action = ApprovalRequest(request_id="apr-2001", approval_type="action_execution");
    root ++> action;
    action +>:RequiresGroup:+> sec_rev;

    bob_auth = action spawn DecisionAuthorizer(approver_id="bob");
    if bob_auth.authorized {
        action.status = "approved";
        print(f"AUTHORIZED: bob decided {action.request_id}");
    } else {
        print(f"DENIED: {bob_auth.denial_reason}");
    }

    admin_auth = action spawn DecisionAuthorizer(approver_id="ops-admin");
    if not admin_auth.authorized {
        print(
            f"DENIED: ops-admin lacks approver group membership "
            f"({admin_auth.denial_reason})"
        );
        evidence = action spawn UnauthorizedEvidence(approver_id="ops-admin");
    }

    orphan = ApprovalRequest(request_id="apr-3001");
    root ++> orphan;
    orphan_auth = orphan spawn DecisionAuthorizer(approver_id="alice");
    if not orphan_auth.authorized {
        print(f"FAIL CLOSED: {orphan_auth.denial_reason}");
    }
}
