```jac
"""Project folder audit: walk a tree depth-first, flag files larger than 100 KB."""

node File {
    has title: str = "";
    has size_kb: float = 0.0;
    has available: bool = True;

    def is_oversize -> bool {
        return self.size_kb > 100.0;
    }
}

node Folder {
    has title: str = "";
    has available: bool = True;
}

edge Contains {
    has order: int = 0;
}

walker Auditor {
    can start with Root entry {
        print("Starting audit at project root");
        visit [-->];
    }

    can dive with Folder entry {
        print(f"[FOLDER] entering {here.title}");
        children = [here->:Contains:->];
        if len(children) > 0 {
            visit children;
        } else {
            print(f"[FOLDER] {here.title} is empty");
        }
        visit [-->];
    }

    can audit with File entry {
        if here.is_oversize() {
            label = "FLAG";
        } else {
            label = "ok";
        }
        print(f"[FILE] {here.title} ({here.size_kb:.1f} KB) -> {label}");
    }
}

with entry {
    docs = Folder(title="docs");
    src = Folder(title="src");
    assets = Folder(title="assets");
    root ++> docs ++> src ++> assets;

    docs +>:Contains(order=0):+> File(title="readme.md", size_kb=12.5);
    docs +>:Contains(order=1):+> File(title="changelog.md", size_kb=240.0);

    src +>:Contains(order=0):+> File(title="main.py", size_kb=45.0);
    src +>:Contains(order=1):+> File(title="engine.py", size_kb=312.5);

    assets +>:Contains(order=0):+> File(title="logo.png", size_kb=8.2);
    assets +>:Contains(order=1):+> File(title="bundle.dat", size_kb=1024.0);

    print("=== Project Audit ===");
    root spawn Auditor();
    print("=== Audit Complete ===");
}
