"""Event-page guestbook: two HTTP-spawnable walkers (sign + read) that also run standalone."""

node Guestbook {
    has name: str = "Guestbook";
    has entries: list = [];
}

walker SignGuestbook {
    has guest_name: str = "Anonymous";
    has message: str = "";

    can start with Root entry {
        visit [-->];
    }

    can sign with Guestbook entry {
        new_entry = {"guest": self.guest_name, "message": self.message};
        here.entries.append(new_entry);
        payload = {"action": "signed", "guest": self.guest_name, "message": self.message};
        report payload;
        print(f"Signed: {payload}");
    }
}

walker ReadGuestbook {
    has limit: int = 5;

    can start with Root entry {
        visit [-->];
    }

    can read with Guestbook entry {
        recent = here.entries[-self.limit:] if len(here.entries) > self.limit else list(here.entries);
        payload = {"action": "read", "count": len(recent), "entries": recent};
        report payload;
        print(f"Read: {payload}");
    }
}
