"""City tourism planner: stations link to hotels and rated attractions.

From each station, shortlist only the attractions (skip hotels) and then
only those rated 4 stars or higher, printing the final itinerary.
"""

node Station {
    has name: str = "";
}

node Hotel {
    has name: str = "";
    has nightly_rate: float = 0.0;
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

walker ItineraryPlanner {
    can start with Root entry {
        visit [-->];
    }

    can plan with Station entry {
        print(f"Station: {here.name}");
        visit [-->];
    }

    can visit_hotel with Hotel entry {
        # Skip hotels (don't print) and keep traversing so chained
        # attractions/stations downstream are still visited.
        visit [-->];
    }

    can visit_places with Attraction entry {
        if here.stars >= 4 {
            print(f"  -> {here.name} ({here.stars}★)");
        }
        # Continue traversal so subsequent attractions/stations chained
        # after this one are still visited.
        visit [-->];
    }
}

