    airport_a1 = Attraction(name="Skyline Lookout", stars=5);
    airport_a2 = Attraction(name="Airport Garden", stars=3);

    root ++> central ++> airport;

    central ++> central_h
        ++> central_a1
        ++> central_a2
        ++> central_a3;

    airport ++> airport_h
