```jac
"""Order auditor demonstrating both early-return flavors.

`skip` mirrors Python's `continue`: it ends the current ability and moves on
to the next connected node, leaving the rest of the walk intact. `disengage`
mirrors Python's `break` / early `return` from the whole walk: it stops the
walker outright, no matter how much of the chain is still ahead.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] {here.label}: fraud flagged on ${here.amount:.2f} -- stopping audit");
            disengage;
        }

        if not here.valid {
            print(f"[SKIP] {here.label}: invalid order, moving on");
            visit [-->];
            skip;
        }

        print(f"[OK]   {here.label}: cleared ${here.amount:.2f}");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="ORD-001", amount=120.50, valid=True)
        ++> Order(label="ORD-002", amount=75.00, valid=False)
        ++> Order(label="ORD-003", amount=999.99, valid=True, fraud=True)
        ++> Order(label="ORD-004", amount=42.10, valid=True);

    root spawn OrderAuditor();
}
```

