```jac
"""Task service: collect every todo into a single JSON array report.

Walks the user's todo graph, gathering each task into one accumulated list,
then emits the entire list as a single ``report`` at the end. The todo
owner is stamped on the walker so only the originating user's tasks are
visible to them.
"""

node Todo {
    has title: str = "";
    has done: bool = False;
    has owner: str = "";
}

walker TaskLister {
    has owner: str = "";
    has collected: list = [];

    can start with Root entry {
        visit [-->];
    }

    can gather with Todo entry {
        if here.owner == self.owner {
            self.collected.append({
                "title": here.title,
                "done": here.done,
                "owner": here.owner,
            });
        }
        visit [-->];
    }

    can finish with exit {
        report self.collected;
    }
}

with entry {
