```jac
"""Diamond-aware build audit.

Tasks form a DAG with shared dependencies (diamonds). The walker must
count each task exactly once even when the graph reaches it via several
paths, then report total build minutes.
"""

node Task {
    has name: str = "";
    has minutes: int = 0;
    has audited: bool = False;
}

walker BuildAuditor {
    has total_minutes: int = 0;
    has audited_names: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        already = False;
        for n in self.audited_names {
            if n == here.name {
                already = True;
            }
        }
        if not already {
            self.audited_names.append(here.name);
            here.audited = True;
            self.total_minutes = self.total_minutes + here.minutes;
            print(f"Audited {here.name} (+{here.minutes} min)");
            visit [-->];
        }
    }
}

with entry {
    # Diamond shape:
    #           build_core (10)
    #          /           \
    #   link_app (15)   link_tool (20)
    #          \           /
    #           package (25)
    # link_app and link_tool both depend on build_core;
    # package depends on both of them.
    build_core = Task(name="build_core", minutes=10);
    link_app = Task(name="link_app", minutes=15);
    link_tool = Task(name="link_tool", minutes=20);
    package = Task(name="package", minutes=25);

    root ++> build_core
        ++> link_app
        ++> link_tool
        ++> package;

    build_core ++> link_app;
    build_core ++> link_tool;
    link_app ++> package;
    link_tool ++> package;

    auditor = BuildAuditor();
    root spawn auditor;
    print(f"Total build minutes (diamond-deduped): {auditor.total_minutes}");
}
```

