"""Pipeline tracer: walk a water pipeline from the intake valve and report
the full route together with every dead-end (capped) stub encountered."""

node Valve {
    has name: str = "";
    has capped: bool = False;
}

walker Tracer {
    has route: list = [];
    has dead_ends: list = [];

    can start with Root entry {
        self.route = [];
        self.dead_ends = [];
        visit [-->] else { disengage; }
    }

    can trace with Valve entry {
        self.route.append(here.name);
        if here.capped {
            self.dead_ends.append(here.name);
            print(f"[DEAD END] {here.name} (capped)");
            disengage;
        }
        if "Stub" in here.name {
            self.dead_ends.append(here.name);
            print(f"[DEAD END] {here.name} (no outgoing pipe)");
            disengage;
        }
        print(f"flow -> {here.name}");
        visit [-->] else { disengage; }
    }
}

with entry {
    intake = Valve(name="Intake");
    junction_a = Valve(name="Junction-A");
    junction_b = Valve(name="Junction-B");
    capped_north = Valve(name="NorthStub", capped=True);
    capped_south = Valve(name="SouthStub", capped=True);
    reservoir = Valve(name="Reservoir");

    root ++> intake
        ++> junction_a
        ++> junction_b;
    junction_a ++> capped_north;
    junction_b ++> capped_south;
    junction_b ++> reservoir;

    res = root spawn Tracer();

    print("Route summary:");
    for step in res.route {
