```jac
"""Vending machine controller: model states as nodes and step through inputs with a walker."""

node State {
    has name: str = "";
}

walker Controller {
    has inputs: list = [];
    has transitions: dict = {
        "idle": {"insert_coin": "waiting"},
        "waiting": {"select_item": "vend", "insert_coin": "waiting"},
        "vend": {"select_item": "idle"},
    };
    has current: str = "idle";

    can start with Root entry {
        visit [-->];
    }

    can step with State entry {
        self.current = here.name;
        while len(self.inputs) > 0 {
            input = self.inputs.pop(0);
            prev = self.current;
            if prev in self.transitions and input in self.transitions[prev] {
                self.current = self.transitions[prev][input];
            }
            print(f"input={input}  state={prev} -> {self.current}");
        }
        print(f"final state: {self.current}");
        disengage;
    }
}

with entry {
    idle = State(name="idle");
    waiting = State(name="waiting");
    vend = State(name="vend");

    root ++> idle;
    root ++> waiting;
    root ++> vend;

    root spawn Controller(inputs=["insert_coin", "select_item", "insert_coin", "select_item"]);
}
