```jac
"""Restaurant kitchen line health-inspection walker.

Three stations (grill, fryer, cold prep) sit on a line. Two checks must
run at every station: a temperature check (flag violations above 40 C)
and a visit log (record every station entered). Both are implemented
as walker abilities triggered on the union of station types via a
shared base node.
"""

# --- Base archetype: every station shares a temperature field and a
# name. Declaring them here lets the union-trigger ability touch only
# fields common to every concrete station subtype.
node Station {
    has station_name: str = "";
    has temperature: float = 0.0;
    has violation: bool = False;
}

node Grill(Station) {}
node Fryer(Station) {}
node ColdPrep(Station) {}

walker HealthInspector {
    has visited_count: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        print("Health inspector starting kitchen walkthrough");
        visit [-->] else {
            print("No stations on the line");
            disengage;
        }
    }

    # Union trigger: fires for Grill OR Fryer OR ColdPrep because all
    # three inherit the Station fields this ability reads. Both checks
    # (temperature + log) run at the same station, and a single
    # traversal step advances to the next station exactly once.
    can inspect with Grill | Fryer | ColdPrep entry {
        # Temperature check
        if here.temperature > 40.0 {
            here.violation = True;
            violation_msg = (
                f"VIOLATION at {here.station_name}: "
                f"{here.temperature} C exceeds 40 C"
            );
            print(violation_msg);
        } else {
            print(
                f"OK at {here.station_name}: {here.temperature} C"
            );
        }

        # Visit log
        self.visited_count += 1;
        self.log.append(
            f"Visit #{self.visited_count}: {here.station_name} "
            f"({here.temperature} C)"
        );

        visit [-->];
    }
}

with entry {
    grill = Grill(station_name="Grill", temperature=85.0);
    fryer = Fryer(station_name="Fryer", temperature=180.0);
    cold_prep = ColdPrep(station_name="Cold Prep", temperature=4.0);
    root ++> grill ++> fryer ++> cold_prep;

    inspector = HealthInspector();
    root spawn inspector;

    print("--- Visit log ---");
    for log_line in inspector.log {
        print(log_line);
    }
    print(
        f"Total stations visited: {inspector.visited_count}"
    );
}
```

```jac
"""Order auditor: `skip` invalid orders yet keep walking, but halt on fraud.

Two early-return flavors live side by side:
  * invalid orders keep auditing later orders in the chain.
  * `disengage` on fraud-flagged orders stops the whole walk immediately.
"""

node Order {
    has order_id: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flagged: bool = False;
}

walker OrderAuditor {
    has audited_count: int = 0;
    has halted_on_fraud: bool = False;
    has halted_order_id: str = "";

    can start with Root entry {
        print(f"OrderAuditor beginning sweep at root");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        # Fraud halts the whole walk on the spot.
        if here.fraud_flagged {
            self.halted_on_fraud = True;
            self.halted_order_id = here.order_id;
            self.audited_count += 1;
            print(f"[HALT-FRAUD] {here.order_id} (${here.amount:.2f}) — disengaging");
            disengage;
        } elif not here.valid {
            # Invalid orders are skipped; the walk continues to the next order.
            print(f"[SKIP] {here.order_id} (${here.amount:.2f}) — invalid, continuing");
            visit [-->] else { disengage; }
        } else {
            # Healthy order: record the audit and keep walking.
            self.audited_count += 1;
            print(f"[AUDIT] {here.order_id} (${here.amount:.2f})");
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Order(order_id="A-001", amount=120.50, valid=True)
        ++> Order(order_id="A-002", amount=0.00, valid=False)
        ++> Order(order_id="A-003", amount=540.00, valid=True)
        ++> Order(order_id="A-004", amount=9999.99, valid=True, fraud_flagged=True)
        ++> Order(order_id="A-005", amount=75.25, valid=True);

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"--- summary: audited {auditor.audited_count} order(s); "
          f"halted_on_fraud={auditor.halted_on_fraud}; "
          f"halted_order_id={auditor.halted_order_id}");
}
