```jac
"""Task dashboard: walk the task graph, accumulate counters, and report a single
summary dict at Root exit. Guards division by zero for accounts with no todos."""

node Account {
    has name: str = "";
}

node Task {
    has title: str = "";
    has completed: bool = False;
    has story_points: int = 0;
}

walker Auditor {
    has account_name: str = "";
    has total: int = 0;
    has done: int = 0;
    has pending: int = 0;
    has burned: int = 0;
    has planned: int = 0;
    has `report: dict = {};
    has target_account: str = "";
    has locked: bool = False;

    can start with Root entry {
        self.target_account = "";
        self.locked = False;
        visit [-->];
