"""Guestbook walkers: SignGuest and ReadGuest.

`jac start` makes walker `has` fields the request body and the final
`report` the HTTP response, so no route handler is needed. The `with
entry` block keeps the module runnable on its own for prototyping.
"""

node GuestbookEntry {
    has author: str = "";
    has message: str = "";
    has signed_at: str = "";
}

walker SignGuest {
    has author: str = "";
    has message: str = "";
    has signed_at: str = "";

    can greet with Root entry {
        print("Guestbook ready for a new signature.");
        visit [-->];
    }

    can sign with GuestbookEntry entry {
        report {
            "author": here.author,
            "message": here.message,
            "signed_at": here.signed_at,
        };
    }
}

walker ReadGuest {
    has limit: int = 5;
    has count: int = 0;

    can greet with Root entry {
        print(f"Reading latest {self.limit} guestbook entries.");
        visit [-->];
