    can read with GuestbookEntry entry {
        if self.count < self.limit {
            report {
                "author": here.author,
                "message": here.message,
                "signed_at": here.signed_at,
            };
            self.count += 1;
        }
    }
}

with entry {
    e1 = GuestbookEntry(author="Ada", message="Loved the keynote!", signed_at="2025-04-01T10:00");
    e2 = GuestbookEntry(author="Lin", message="Great turnout this year.", signed_at="2025-04-01T10:15");
    e3 = GuestbookEntry(author="Mo", message="See you next spring.", signed_at="2025-04-01T10:30");
    root ++> e1 ++> e2 ++> e3;

    signer = SignGuest(author="Kai", message="First sign via walker.", signed_at="2025-04-01T11:00");
    root spawn signer;

