```jac
"""Online store checkout: a single walker that reacts to each product's
concrete type via union triggers and prints an itemized receipt with
subtotal, shipping, and total.

Each product kind has its own shipping/handling rule. The Checkout walker
visits the cart's products in order and accumulates line totals. A union
trigger ``can ring_up with PaperBook | DigitalBook | Electronic | Clothing entry``
lets one ability dispatch on the concrete type while keeping the receipt
assembly in one place.
"""

# ---- Product archetypes --------------------------------------------------

node Product {
    has name: str = "";
    has price: float = 0.0;

    # Shared signature so the union ability can call these on every
    # concrete product type without losing type information.
    def shipping() -> float;
    def handling() -> float;
}

node PaperBook(Product) {
    has weight_lb: float = 0.0;

    # Flat $4 shipping for paper books.
    def shipping() -> float {
        return 4.0;
    }

    def handling() -> float {
        return 0.0;
    }
}

node DigitalBook(Product) {
    # Digital delivery: no shipping, $0.99 platform fee.
    def shipping() -> float {
        return 0.0;
    }

    def handling() -> float {
        return 0.99;
    }
}

node Electronic(Product) {
    has warranty_months: int = 0;
    has fragile: bool = True;

    # $10 base + $2 per month of warranty, plus $5 if fragile.
    def shipping() -> float {
        base = 10.0 + 2.0 * float(self.warranty_months);
        fragile_fee = 5.0 if self.fragile else 0.0;
        return base + fragile_fee;
    }

    def handling() -> float {
        return 0.0;
    }
}

node Clothing(Product) {
    has size: str = "M";

    # Free shipping over $50, otherwise $6.
    def shipping() -> float {
        return 0.0 if self.price >= 50.0 else 6.0;
    }

    def handling() -> float {
        return 0.0;
    }
}

# ---- Cart / walker -------------------------------------------------------

node Cart {
    has label: str = "Cart";
}

walker Checkout {
    has subtotal: float = 0.0;
    has shipping_total: float = 0.0;
    has handling_total: float = 0.0;
    has lines: list = [];
    has remaining: int = 0;

    can start with Root entry {
        print("=== Checkout ===");
        visit [-->] else {
            self.print_receipt();
            disengage;
        };
    }

    can enter_cart with Cart entry {
        print(f"Scanning {here.label}...");
        # Prime the queue with the cart's children; the union ability must
        # NOT re-issue ``visit [-->]`` or it would prematurely stop after
        # the first product (which is a leaf with no outgoing edges).
        self.remaining = len([-->]);
        visit [-->];
    }

    # One union ability dispatches on the concrete product type. Only
    # fields/methods declared on the Product base node are read here.
    can ring_up with PaperBook | DigitalBook | Electronic | Clothing entry {
        ship = here.shipping();
        hand = here.handling();
        line_total = here.price + ship + hand;

        kind_label = here.__class__.name;
        self.lines.append({
            "kind": kind_label,
            "name": here.name,
            "price": here.price,
            "shipping": ship,
            "handling": hand,
            "line_total": line_total,
        });

        self.subtotal += here.price;
        self.shipping_total += ship;
        self.handling_total += hand;

        self.remaining -= 1;
        if self.remaining <= 0 {
            self.print_receipt();
            disengage;
        }
    }

    def print_receipt() -> None {
        grand = self.subtotal + self.shipping_total + self.handling_total;
        for line in self.lines {
            extras = "";
            if line["shipping"] > 0.0 {
                extras += f" + ship ${line['shipping']:.2f}";
            }
            if line["handling"] > 0.0 {
                extras += f" + handling ${line['handling']:.2f}";
            }
            print(
                f"  {line['kind']:<11} {line['name']:<28} "
                f"${line['price']:.2f}{extras}"
            );
        }
        print(f"  {'SUBTOTAL':<40} ${self.subtotal:.2f}");
        print(f"  {'SHIPPING':<40} ${self.shipping_total:.2f}");
        print(f"  {'HANDLING':<40} ${self.handling_total:.2f}");
        print(f"  {'TOTAL':<40} ${grand:.2f}");
    }
}

with entry {
    cart = Cart(label="Summer Cart");

    cart ++> PaperBook(name="The Pragmatic Programmer", price=29.99, weight_lb=1.2);
    cart ++> DigitalBook(name="Crafting Interpreters (eBook)", price=32.00);
    cart ++> Electronic(name="USB-C Hub", price=45.00, warranty_months=24, fragile=True);
    cart ++> Clothing(name="Wool Sweater", price=78.00, size="L");
    cart ++> Clothing(name="Cotton Tee", price=18.00, size="M");

    root ++> cart;
    root spawn Checkout();
}
```

