```jac
"""Contact tracing from patient zero through a network of exposures.

Models an outbreak spreading wave by wave (breadth-first). Each wave
prints the people being contacted in that round before advancing to
the next.
"""

node Person {
    has name: str = "";
    has infected: bool = False;
}

edge Contact {
    has weight: int = 1;
}

walker Tracer {
    has wave: int = 0;
    has pending: list = [];
    has done: bool = False;

    can trace with Root entry {
        initial = [-->];
        if len(initial) == 0 {
            print("No patient zero found.");
            disengage;
        }
        self.wave = 1;
        print(f"--- Wave {self.wave} (patient zero) ---");
        next_pending = [];
        for p in initial {
            p.infected = True;
            print(f"Contacting {p.name} (initial exposure)");
            for c in [p-->] {
                if not c.infected {
                    c.infected = True;
                    next_pending.append(c);
                }
            }
        }
        self.pending = next_pending;

        while len(self.pending) > 0 {
            self.wave += 1;
            print(f"--- Wave {self.wave} ---");
            next_pending = [];
            for person in self.pending {
                print(f"Contacting {person.name}");
                for c in [person-->] {
                    if not c.infected {
                        c.infected = True;
                        next_pending.append(c);
                    }
                }
            }
            self.pending = next_pending;
        }

        print("Outbreak fully traced.");
        disengage;
    }
}

with entry {
    p0 = Person(name="Alice", infected=True);
    p1 = Person(name="Bob");
    p2 = Person(name="Carol");
    p3 = Person(name="Dave");
    p4 = Person(name="Eve");
    p5 = Person(name="Frank");
    p6 = Person(name="Grace");

    root ++> p0;
    p0 +>:Contact(weight=1):+> p1;
    p0 +>:Contact(weight=1):+> p2;
    p1 +>:Contact(weight=2):+> p3;
    p1 +>:Contact(weight=2):+> p4;
    p2 +>:Contact(weight=2):+> p5;
    p4 +>:Contact(weight=3):+> p6;

    root spawn Tracer();
}
