"""Hiking trail: chain waypoints from trailhead to summit; a hiker counts each stop."""

node TrailStop {
    has label: str = "";
}

node Trailhead(TrailStop) {
    has label: str = "Trailhead";
}

node Waypoint(TrailStop) {
    has label: str = "Waypoint";
}

node Summit(TrailStop) {
    has label: str = "Summit";
}

walker Hiker {
    has stop_count: int = 0;

    can start with Root entry {
        print("Starting the trail");
        visit [-->];
    }

    can hike with Trailhead | Waypoint | Summit entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}: {here.label}");
        visit [-->] else {
            if self.stop_count >= 3 {
                print(f"Trail complete — passed {self.stop_count} stops.");
            }
            disengage;
        }
    }
}

with entry {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    root spawn Hiker();
}
```

```jac
"""Weather sweep: visit each weather station node, report readings, and summarize min/max."""

node Station {
    has location: str = "";
    has celsius: float = 0.0;
}

walker Sweep {
    has readings: list = [];

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        self.readings.append((here.location, here.celsius));
        print(f"[{here.location}] {here.celsius} C");
        visit [-->];
    }

    can finish with Station exit {
        if len(self.readings) > 0 {
            print("--- sweep complete ---");
            for (loc, temp) in self.readings {
                print(f"{loc}: {temp} C");
            }
            temps = [t for (_, t) in self.readings];
            lo = min(temps);
            hi = max(temps);
            print(f"min={lo} C, max={hi} C");
        } else {
            print("--- sweep complete ---");
        }
    }
}

with entry {
    s1 = Station(location="North", celsius=18.5);
    s2 = Station(location="East", celsius=22.0);
    s3 = Station(location="South", celsius=15.2);
    s4 = Station(location="West", celsius=27.8);
    root ++> s1 ++> s2 ++> s3 ++> s4;

    sweeper = Sweep();
    root spawn sweeper;
}
