```jac
"""Weather sweep: stations as nodes, a walker visits each and reports temperatures."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[tuple[str, float]] = [];
    has low: float = 0.0;
    has high: float = 0.0;
    has station_count: int = 0;

    can start with Root entry {
        print("Starting weather sweep...");
        visit [-->] else { disengage; }
    }

    can measure with WeatherStation entry {
        self.readings.append((here.location, here.celsius));
        self.station_count += 1;
        if self.station_count == 1 {
            self.low = here.celsius;
            self.high = here.celsius;
        } else {
            if here.celsius < self.low {
                self.low = here.celsius;
            }
            if here.celsius > self.high {
                self.high = here.celsius;
            }
        }
        print(f"  {here.location}: {here.celsius} C");
        visit [-->] else {
            print("\nFull readings:");
            for (loc, temp) in self.readings {
                print(f"  {loc}: {temp} C");
            }
            print(f"\nMin: {self.low} C");
            print(f"Max: {self.high} C");
            disengage;
        }
    }
}

with entry {
    root ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Airport", celsius=19.0)
        ++> WeatherStation(location="Harbor", celsius=24.8)
        ++> WeatherStation(location="Hilltop", celsius=17.2);

    sweep = WeatherSweep();
    root spawn sweep;
}
