```jac
"""Weather sweep: stations hold a location and Celsius reading; a walker reports each and continues."""

node Station {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list = [];
    has reports: list = [];
    has min_temp: float = 0.0;
    has max_temp: float = 0.0;
    has min_loc: str = "";
    has max_loc: str = "";

    can sweep with Root entry {
        if len([-->]) == 0 {
            print("No stations visited.");
            self.summarize_results();
            disengage;
        }
        visit [-->];
    }

    can read with Station entry {
        self.readings.append((here.location, here.celsius));
        report(here.celsius);
        self.reports.append(here.celsius);
        if len([-->]) == 0 {
            self.summarize_results();
            disengage;
        }
        visit [-->];
    }

    def summarize_results() {
        if len(self.readings) > 0 {
            self.min_temp = self.readings[0][1];
            self.max_temp = self.readings[0][1];
            self.min_loc = self.readings[0][0];
            self.max_loc = self.readings[0][0];
            for (loc, t) in self.readings {
                if t < self.min_temp {
                    self.min_temp = t;
                    self.min_loc = loc;
                }
                if t > self.max_temp {
                    self.max_temp = t;
                    self.max_loc = loc;
                }
            }
            print("Weather sweep readings:");
            for (loc, t) in self.readings {
                print(f"  {loc}: {t} C");
            }
            print(f"Min: {self.min_temp} C at {self.min_loc}");
            print(f"Max: {self.max_temp} C at {self.max_loc}");
        } else {
            print("No stations visited.");
        }
    }
}

with entry {
    root ++> Station(location="Mt. Hood", celsius=4.5)
        ++> Station(location="Portland", celsius=12.0)
        ++> Station(location="Bend", celsius=18.3)
        ++> Station(location="Eugene", celsius=15.7)
        ++> Station(location="Astoria", celsius=9.2);
    root spawn WeatherSweep();
}
