```jac
"""Weather sweep: stations hold a city and a Celsius reading; a walker traverses the chain and reports each reading."""

node Station {
    has city: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[tuple[str, float]] = [];
    has lo: float = 0.0;
    has hi: float = 0.0;
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        if here in self.visited {
            visit [-->];
            return;
        }
        self.visited.append(here);
        self.readings.append((here.city, here.celsius));
        n = len(self.readings);
        if n == 1 {
            self.lo = here.celsius;
            self.hi = here.celsius;
        } else {
            if here.celsius < self.lo { self.lo = here.celsius; }
            if here.celsius > self.hi { self.hi = here.celsius; }
        }
        print(f"{here.city}: {here.celsius} C");
        visit [-->];
    }
}

with entry {
    root ++> Station(city="Portland", celsius=12.5)
        ++> Station(city="Seattle", celsius=14.1)
        ++> Station(city="Boise", celsius=9.8)
        ++> Station(city="Spokane", celsius=7.3);

    sweeper = WeatherSweep();
    root spawn sweeper;

    print("--- sweep report ---");
    for (city, temp) in sweeper.readings {
        print(f"{city}: {temp} C");
    }
    print(f"min = {sweeper.lo} C");
    print(f"max = {sweeper.hi} C");
}
