```jac
"""Quiz grader walker with strictly typed integer reports."""

node Quiz {
    has title: str = "";
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has last_score: int = 0;
    has report_count: int = 0;
    has score_total: int = 0;
    has collected: list[int] = [];

    can start with Root entry {
        print("Grader entering the quiz hall");
        if [-->] {
            visit [-->];
        } else {
            self.summarize_once();
            disengage;
        }
    }

    can grade with Quiz entry {
        print(f"Grading {here.student} on '{here.title}': {here.score}");
        self.collected.append(here.score);
        self.last_score = here.score;
        self.score_total = self.score_total + here.score;
        self.report_count = self.report_count + 1;
        report here.score;
        if [-->] {
            visit [-->];
        } else {
            self.summarize_once();
            disengage;
        }
    }

    def summarize_once {
        avg = self.score_total // self.report_count if self.report_count > 0 else 0;
        print(f"Collected scores: {self.collected}");
        print(f"Class average: {avg}");
    }
}

with entry {
    root ++> Quiz(title="Algebra I", student="Alice", score=88)
        ++> Quiz(title="Algebra I", student="Bob", score=74)
        ++> Quiz(title="World History", student="Cara", score=91)
        ++> Quiz(title="Biology", student="Dan", score=67);
    root spawn Grader();
}
