```jac
"""Weather sweep: stations report their readings as a walker visits them, then aggregate min/max."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker Sweep {
    has readings: list[float] = [];

    can start with Root entry {
        print("Weather sweep starting");
        visit [-->];
    }

    can read with Station entry {
        self.readings.append(here.celsius);
        print(f"[{here.location}] {here.name}: {here.celsius}C");
        visit [-->];
    }

    can finish with Station entry {
        # No further stations to visit; print summary if any readings exist.
        if len(self.readings) > 0 {
            min_r = self.readings[0];
            max_r = self.readings[0];
            for r in self.readings {
                lo = r if r < min_r else min_r;
                hi = r if r > max_r else max_r;
                min_r = lo;
                max_r = hi;
            }
            print("All readings:");
            for (i, r) in enumerate(self.readings) {
                print(f"  station {i}: {r}C");
            }
            print(f"min: {min_r}C, max: {max_r}C");
        }
    }
}

with entry {
    (root ++> Station(name="North", location="Ridge", celsius=12.5)
         ++> Station(name="East", location="Valley", celsius=18.0)
         ++> Station(name="South", location="Coast", celsius=21.3)
         ++> Station(name="West", location="Plateau", celsius=9.8));

