"""Toll plaza G-4: walk the lane and tally revenue by vehicle type."""

node Vehicle {
    has kind: str = "";
    has tons: float = 0.0;
}

walker Collector {
    has rate_car: float = 2.50;
    has rate_truck_base: float = 2.50;
    has rate_truck_per_ton: float = 0.50;
    has rate_bike: float = 1.00;
    has total: float = 0.0;
    has count: int = 0;
    has lane: list = [];

    can start with Root entry {
        print("Gate G-4 opening...");
        self.lane = [-->];
        if self.lane {
            visit self.lane;
        } else {
            print(
                f"Gate G-4 closed. {self.count} vehicles, total revenue ${self.total:.2f}"
            );
            disengage;
        }
    }

    can charge with Vehicle entry {
        owed = self.rate_bike;
        if here.kind == "car" {
            owed = self.rate_car;
        } elif here.kind == "truck" {
            owed = self.rate_truck_base + (here.tons * self.rate_truck_per_ton);
        }
        label = "bike" if here.kind == "motorcycle" else here.kind;
        print(
            f"{label}: paid ${owed:.2f}"
            + (f" ({here.tons}t)" if here.kind == "truck" else "")
        );
        self.total = self.total + owed;
        self.count = self.count + 1;
        visit [-->] else {
            print(
                f"Gate G-4 closed. {self.count} vehicles, total revenue ${self.total:.2f}"
            );
            disengage;
        }
    }
}

with entry {
    root ++> Vehicle(kind="car")
        ++> Vehicle(kind="truck", tons=3.0)
        ++> Vehicle(kind="motorcycle")
        ++> Vehicle(kind="car")
        ++> Vehicle(kind="truck", tons=1.5);
