"""Order auditor: walk a chain of orders, skip invalid ones but halt on fraud."""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has flagged_fraud: bool = False;
}

walker OrderAuditor {
    has total: float = 0.0;

    can start with Root entry {
        print("Audit start: reviewing order chain");
        visit [-->];
    }

    can review with Order entry {
        if here.flagged_fraud {
            print(f"!! FRAUD HALT on '{here.label}' (amount={here.amount:.2f}) — stopping audit");
            disengage;
            return;
        }

        if not here.valid {
            print(f"-- SKIP invalid order '{here.label}' — continuing audit");
            visit [-->];
            return;
        }

        self.total = self.total + here.amount;
        print(f"++ APPROVED '{here.label}' amount={here.amount:.2f} running_total={self.total:.2f}");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="ORD-1001", amount=120.50)
        ++> Order(label="ORD-1002", amount=75.00, valid=False)
        ++> Order(label="ORD-1003", amount=240.75)
        ++> Order(label="ORD-1004", amount=60.00, flagged_fraud=True)
        ++> Order(label="ORD-1005", amount=99.99);
    root spawn OrderAuditor();
}
