```jac
"""Contact tracing from patient zero, wave by wave through a contact network."""

node Person {
    has name: str = "";
    has infected: bool = False;
    has wave: int = -1;
}

edge Contact {
    has day: int = 0;
}

walker WaveRunner {
    can start with Root entry {
        print("--- Contact trace (wave by wave) ---");

        # Patient zero is the root's direct neighbor (wave 0).
        wave: int = 0;
        current_frontier: list = [];
        for n in [root -->] {
            n.wave = wave;
            n.infected = True;
            print(f"Wave {wave}: {n.name} exposed");
            current_frontier = current_frontier + [n];
        }
        wave = wave + 1;

        # BFS: every wave finishes before the next begins.
        while len(current_frontier) > 0 {
            next_frontier: list = [];
            for person in current_frontier {
                for n in [person -->] {
                    if n.wave >= 0 {
                        continue;
                    }
                    n.wave = wave;
                    n.infected = True;
                    print(f"Wave {wave}: {n.name} exposed");
                    next_frontier = next_frontier + [n];
                }
            }
            current_frontier = next_frontier;
            wave = wave + 1;
        }
    }
}

with entry {
    p0 = Person(name="Patient Zero");
    p1 = Person(name="Alice");
    p2 = Person(name="Bob");
    p3 = Person(name="Carol");
    p4 = Person(name="Dave");
    p5 = Person(name="Eve");
    p6 = Person(name="Frank");

    root +>:Contact(day=1):+> p0;
    p0 +>:Contact(day=1):+> p1;
    p0 +>:Contact(day=1):+> p2;
    p1 +>:Contact(day=2):+> p3;
    p1 +>:Contact(day=2):+> p4;
    p2 +>:Contact(day=2):+> p5;
    p2 +>:Contact(day=2):+> p6;
    p3 +>:Contact(day=3):+> p5;

    WaveRunner() spawn root;
}
