```jac
"""Reports access policy.

Published reports are world-readable; unpublished ones fall back to
per-instance grants. The archetype hook returns a READ level when
published and ``None`` otherwise. A ``Publish`` walker flips the flag
and drops the now-redundant grant edge.
"""

node Reader {
    has name: str = "";
}

node Report {
    has title: str = "";
    has published: bool = False;

    # Archetype hook: world-readable when published, else defer to grants.
    def access_level() -> str | None {
        if self.published {
            return "READ";
        }
        return None;
    }
}

edge Grant { has level: str = "READ"; }

walker Publish {
    can start with Root entry {
        visit [-->];
    }

    can flip with Report entry {
        here.published = True;
        # Drop the now-redundant grant edge(s) attached to this report.
        # Snapshot first to avoid mutating during iteration, then
        # delete by re-querying with `del`.
        grants = [here ->:Grant:->];
        for g in grants {
            del [here ->:Grant:-> g];
        }
        report_level = here.access_level();
        print(f"Published '{here.title}' -> access level: {report_level}");
    }
}

with entry {
    draft = Report(title="Q4 Forecast");
    root ++> draft;

    # Owner pre-shares the draft with a single reader.
    reader = Reader(name="Alice");
    draft +>:Grant(level="READ"):+> reader;

    root spawn Publish();

    # After publishing the hook returns READ for everyone; the
    # pre-publish grant is now redundant and has been removed.
    print(f"final access level: {draft.access_level()}");
}
```

