```jac
"""Anonymous reading-club poll: tap a book title, get tallies back.

Three public walkers cooperate on a single counter node:
  - PollSetup seeds the ballot options from root.
  - Vote bumps the counter for whichever option the caller names.
  - TallyReport walks the counter node and prints current tallies.
A small local simulation runs the same flow so the file works without a server.
"""

node Counter {
    has title: str = "";
    has votes: int = 0;
}

walker PollSetup {
    has ballot: list[str] = [];

    can start with Root entry {
        # Clear any pre-existing counters so the ballot defines the slate.
        for existing in [root -->] {
            del existing;
        }
        for option in self.ballot {
            c = Counter(title=option);
            here ++> c;
        }
    }
}

walker Vote {
    has pick: str = "";

    can start with Root entry {
        visit [-->];
    }

    can cast with Counter entry {
        if here.title == self.pick {
            here.votes += 1;
            print(f"vote recorded for {here.title} (now {here.votes})");
            disengage;
        }
        visit [-->];
    }
}

walker TallyReport {
    can start with Root entry {
        visit [-->];
    }

    can count with Counter entry {
        print(f"{here.title}: {here.votes}");
        visit [-->];
    }
}

with entry {
    # Seed the ballot.
    options = ["Dune", "Neuromancer", "Circe", "Piranesi"];
    root spawn PollSetup(ballot=options);

    # Simulate a few anonymous clicks locally.
    clicks = ["Dune", "Circe", "Dune", "Piranesi", "Neuromancer", "Dune", "Circe"];
    for pick in clicks {
        root spawn Vote(pick=pick);
    }

    # Report the final tallies.
    print("--- final tallies ---");
    root spawn TallyReport();
}
