```jac
"""Water pipeline tracer.

Models an intake valve, junction valves, and capped stub valves connected
by pipes. A tracer walker starts at the intake, follows the pipes, notes
each capped dead end gracefully, and at the end reports the full route
and how many dead ends it hit.
"""

node Valve {
    has name: str = "";
    has kind: str = "junction";
}

edge Pipe {
    has label: str = "";
}

walker Tracer {
    has route: list[str] = [];
    has dead_ends: int = 0;
    has seen: set[str] = set();
    has backtracking: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can enter with Valve entry {
        was_backtracking = self.backtracking;
        self.backtracking = False;

        if here.name in self.seen {
            print(f"cycle detected at {here.name}, stopping traversal");
            disengage;
        }
        self.seen.add(here.name);
        self.route.append(here.name);

        if here.kind == "stub" {
            self.dead_ends += 1;
            print(f"dead end at capped stub {here.name}");
            self.backtracking = True;
            visit [<--];
            return;
        }

        # Continue forward to outgoing pipes.
        visit [-->] else {
            # Only count as dead end if we weren't just backtracking here,
            # and only if this valve itself has no outgoing pipes.
            if not was_backtracking {
                self.dead_ends += 1;
                print(f"dead end at {here.name} (no outgoing pipe)");
            }
            self.backtracking = True;
            visit [<--];
            return;
        }
    }
}

with entry {
    intake = Valve(name="Intake", kind="intake");
    valve_a = Valve(name="Junction-A", kind="junction");
    valve_b = Valve(name="Junction-B", kind="junction");
    stub_c = Valve(name="Stub-C", kind="stub");
    stub_d = Valve(name="Stub-D", kind="stub");

    root ++> intake
        +>:Pipe(label="p1"):+> valve_a
        +>:Pipe(label="p2"):+> valve_b
        +>:Pipe(label="p3"):+> stub_c;

    intake +>:Pipe(label="p4"):+> stub_d;

    tracer = Tracer();
    root spawn tracer;

    print(f"route: {' -> '.join(tracer.route)}");
    print(f"dead ends hit: {tracer.dead_ends}");
}
```

```jac
"""Factory monitoring: one patrol routine inspects both temperature and smoke sensors.

The walker's `inspect` ability fires for either sensor type via a union
trigger. Temperature sensors alert above 75 C, smoke sensors above 50 ppm.
Readings are printed as nominal or alert, and an alert summary is
reported at the end of the patrol.
"""

node Zone {
    has name: str = "";
}

node TempSensor {
    has label: str = "";
    has celsius: float = 0.0;
}

node SmokeSensor {
    has label: str = "";
    has ppm: float = 0.0;
}

walker Patrol {
    has alert_count: int = 0;
    has alert_labels: list[str] = [];

    can start with Root entry {
        print("Starting factory patrol...");
        visit [-->];
    }

    can sweep with Zone entry {
        print(f"Entering zone: {here.name}");
        visit [-->];
    }

    # Union trigger: fires for either sensor kind.
    can inspect with TempSensor | SmokeSensor entry {
        if isinstance(here, TempSensor) {
            kind = "temperature";
            reading = here.celsius;
            unit = "C";
            threshold = 75.0;
            triggered = here.celsius > threshold;
        } else {
            kind = "smoke";
            reading = here.ppm;
            unit = "ppm";
            threshold = 50.0;
            triggered = here.ppm > threshold;
        }

        if triggered {
            print(f"[ALERT] {kind} sensor '{here.label}' = {reading} {unit} (>{threshold})");
            self.alert_count += 1;
            self.alert_labels.append(here.label);
        } else {
            print(f"[nominal] {kind} sensor '{here.label}' = {reading} {unit}");
        }

        # Continue the patrol traversal so deeper nodes are reached.
        visit [-->];
    }

    # Exit ability so the summary runs AFTER traversal completes, not at spawn time.
    can summarize with Root exit {
        print(f"--- Patrol summary: {self.alert_count} alert(s) ---");
        for label in self.alert_labels {
            print(f"  - {label}");
        }
        report {
            "alerts": self.alert_count,
            "labels": self.alert_labels,
        };
    }
}

with entry {
    zone_a = Zone(name="Assembly");
    zone_b = Zone(name="Packaging");

    root ++> zone_a
        ++> TempSensor(label="T-A1", celsius=68.0)
        ++> TempSensor(label="T-A2", celsius=91.5)
        ++> SmokeSensor(label="S-A1", ppm=12.0);

    root ++> zone_b
        ++> TempSensor(label="T-B1", celsius=74.5)
        ++> SmokeSensor(label="S-B1", ppm=63.0)
        ++> SmokeSensor(label="S-B2", ppm=20.0);

    patrol = Patrol();
    root spawn patrol;
}
```

```jac
"""Professional networking tool: shortest introduction chain between two people.

Models people as nodes and direct professional connections as typed
``Knows`` edges. A ``Connector`` walker performs a breadth-first search
along those edges, tracking a parent map so the chain can be reconstructed
from start person to target person once the target is discovered.
"""

node Person {
    has name: str = "";
    has role: str = "";
}

edge Knows {
    has strength: int = 1;
}

walker Connector {
    has target: str = "";
    has found: bool = False;
    has parents: dict[str, str] = {};

    can start with Root entry {
        if [-->] {
            visit [-->];
        } else {
            disengage;
        }
    }

    can search with Person entry {
        if self.found {
            disengage;
        }
        next_nodes = [->:Knows:->];
        for n in next_nodes {
            if n.name not in self.parents {
                self.parents[n.name] = here.name;
                if n.name == self.target {
                    self.found = True;
                    # reconstruct chain
                    chain = [self.target];
                    cur = self.target;
                    while cur in self.parents and self.parents[cur] != "" {
                        p = self.parents[cur];
                        chain = [p] + chain;
                        cur = p;
                    }
                    print("Introduction chain: " + " -> ".join(chain));
                    disengage;
                }
            }
        }
        if self.found {
            disengage;
        }
        if next_nodes {
            visit next_nodes;
        } else {
            disengage;
        }
    }
}

with entry {
    alice = Person(name="Alice", role="Engineer");
    bob = Person(name="Bob", role="Designer");
    carol = Person(name="Carol", role="PM");
    dave = Person(name="Dave", role="Founder");
    eve = Person(name="Eve", role="Investor");
    frank = Person(name="Frank", role="Recruiter");

    alice +>:Knows:+> bob;
    bob +>:Knows:+> carol;
    carol +>:Knows:+> dave;
    dave +>:Knows:+> eve;
    alice +>:Knows:+> frank;
    frank +>:Knows:+> eve;

    root ++> alice;

    connector = Connector(target="Eve");
    connector spawn alice;
}
```

