```jac
"""Quiz grader walker with strictly typed integer reports.

Demonstrates a walker whose accumulator is typed as ``int`` so any attempt
to stash a string score would fail at compile time. Quiz nodes carry a
student name and a numeric score; the walker collects every score and the
demo prints the per-student breakdown plus the class average.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    # Strictly typed accumulator — only integers may land here.
    has total: int = 0;
    has count: int = 0;
    has scores: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        print(f"{here.student}: {here.score}");
        self.scores.append(here.score);
        self.total = self.total + here.score;
        self.count = self.count + 1;
        visit [-->];
    }

    can summarize with Root exit {
        average: int = 0;
        if self.count > 0 {
            average = self.total // self.count;
        }
        print(f"Collected scores: {self.scores}");
        print(f"Class average: {average} over {self.count} quizzes");
        report {"total": self.total, "count": self.count, "average": average, "scores": self.scores};
    }
}

with entry {
