```jac
"""Blast radius vs verification reach: model the merge-dep-prs gap.

Entities:
  - Artifact: something a PR can change (reusable workflow, composite
    action, published package, config preset).
  - Consumer: a repo or workspace package that executes / depends on
    an artifact at runtime.
  - CIRun: the evidence a green check actually produced -- what jobs
    fired and which artifacts they exercised.

Relationships (typed edges carry the meaning):
  - ConsumedBy: Consumer -> Artifact, payload via which surface.
  - Reaches: CIRun -> Artifact, payload selecting how (full vs
    affected-only vs path-filtered).

Walker:
  - ReachAuditor walks from root, follows outgoing edges to reach
    artifacts, then inspects incoming edges (ConsumedBy for blast
    radius, Reaches for verification reach). Emits per-artifact
    verdict: SAFE, UNREACHED, or PARTIAL.
"""

node Artifact {
    has name: str = "";
    has kind: str = "";
    has consumed_by_repos: int = 0;
}

node Consumer {
    has repo: str = "";
    has surface: str = "";
}

node CIRun {
    has job: str = "";
    has selection: str = "";
}

edge ConsumedBy {
    has via: str = "";
}

edge Reaches {
    has coverage: str = "";
}

walker ReachAuditor {
    has verdicts: list = [];
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Artifact entry {
        if here.name in self.visited {
            visit [-->];
            return;
        }
        self.visited.append(here.name);

        # Enumerate blast radius: incoming ConsumedBy edges
        # (Consumer -> Artifact).
        radius = len([<-:ConsumedBy:<-]);

        # Enumerate verification reach: incoming Reaches edges
        # (CIRun -> Artifact).
        runs = [<-:Reaches:<-];
        covered = 0;
        partial = False;
        no_reach = False;
        has_any_run = False;
        for run in runs {
            has_any_run = True;
            if run.selection == "none" {
                no_reach = True;
                covered = 0;
                partial = False;
                break;
            }
            if run.selection == "full" {
                covered = radius;
            }
            elif run.selection == "affected"
                    or run.selection == "path_filter" {
                covered += 1;
                partial = True;
            }
        }

        verdict = "SAFE";
        if no_reach and radius > 0 {
            verdict = "UNREACHED";
        }
        elif partial and covered < radius {
            verdict = "PARTIAL";
        }

        record = {
            "artifact": here.name,
            "kind": here.kind,
            "radius": radius,
            "covered": covered,
            "verdict": verdict,
        };
        self.verdicts.append(record);
        print(f"[{verdict}] {here.name} ({here.kind}): "
              f"radius={radius} covered={covered}");

        visit [-->];
    }
}

with entry {
    release_wf = Artifact(
        name="pnpm-release-changeset.yml",
        kind="workflow",
        consumed_by_repos=30,
    );

    cyberuni = Consumer(repo="cyberuni/universal-plugin", surface="workflow_call");
    acme = Consumer(repo="acme/widgets", surface="workflow_call");
    globex = Consumer(repo="globex/site", surface="workflow_call");

    full_run = CIRun(job="ci/full", selection="full");
    affected_run = CIRun(job="ci/affected", selection="affected");
    no_tests = CIRun(job="ci/none", selection="none");

    cyberuni +>:ConsumedBy(via="workflow_call"):+> release_wf;
    acme +>:ConsumedBy(via="workflow_call"):+> release_wf;
    globex +>:ConsumedBy(via="workflow_call"):+> release_wf;

    full_run +>:Reaches(coverage="all"):+> release_wf;
    affected_run +>:Reaches(coverage="subset"):+> release_wf;
    no_tests +>:Reaches(coverage="none"):+> release_wf;

    leaf = Artifact(name="leaf-util", kind="package", consumed_by_repos=0);
    leaf_ci = CIRun(job="ci/leaf", selection="full");
    leaf_ci +>:Reaches(coverage="all"):+> leaf;

    root ++> release_wf ++> cyberuni;
    root ++> full_run;
    root ++> affected_run;
    root ++> no_tests;
    root ++> leaf ++> leaf_ci;

    auditor = ReachAuditor();
    root spawn auditor;

    print("");
    print("verdicts:");
    for v in auditor.verdicts {
        print(f"  {v}");
    }
}
