```jac
"""Click dispatch with re-entrancy guard.

Models the HTML click() in-progress flag as a walker over a graph of
elements. Without the guard, a self-referential or mutually recursive
click chain recurses until a depth limit fires; with the guard, each
element dispatches exactly once per click wave and the chain terminates.
"""

node Element {
    has label: str = "";
    has dispatch_count: int = 0;
    has click_in_progress: bool = False;
}

# The "click()" walker: visits an element, guards re-entry, fires the
# synthetic event, and follows outgoing dispatch edges. The guard
# mirrors HTML's "click in progress" flag: an element whose flag is
# already set returns immediately, so a handler that triggers another
# click on itself (or on a mutually recursive element) is dropped.
# On a clean dispatch the flag is set; when traversal finishes (or is
# blocked by the guard on a neighbour) the flag is cleared so the
# element can fire again on the next wave.
walker ClickWave {
    has wave_id: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can fire with Element entry {
        if here.click_in_progress {
            disengage;
        }
        here.click_in_progress = True;
        here.dispatch_count += 1;
        print(f"wave {self.wave_id}: dispatched {here.label} "
              f"(count={here.dispatch_count})");

        # Follow outgoing dispatch edges. The walker visits the next
        # Element on this same ability's type; the guard on re-entry
        # drops self/mutual recursion. Dead-end branches end the wave
        # and clear the flag so the next external click works.
        visit [-->] else {
            here.click_in_progress = False;
            disengage;
        }
    }
}

with entry {
    # Build the click graph:
    #   A <-> B   (mutual recursion: A clicks B clicks A)
    #   C -> D -> E   (clean three-step chain)
    a = Element(label="A");
    b = Element(label="B");
    c = Element(label="C");
    d = Element(label="D");
    e = Element(label="E");

    root ++> a;
    a ++> b;
    b ++> a;
    root ++> c;
    c ++> d;
    d ++> e;

    # Three sequential clicks on C: each is its own wave with a fresh
    # walker, so the in-progress flag resets between invocations and
    # every click actually dispatches (table row "three sequential clicks").
    for wave_id in [1, 2, 3] {
        c.click_in_progress = False;
        d.click_in_progress = False;
        e.click_in_progress = False;
        root spawn ClickWave(wave_id=wave_id);
    }

    # One click on A: triggers A -> B -> A mutual recursion. With the
    # guard, A dispatches once, B dispatches once, the re-entry into A
    # is dropped (table row "mutual recursion, A clicks B clicks A").
    a.click_in_progress = False;
    b.click_in_progress = False;
    root spawn ClickWave(wave_id=4);

    print(f"A dispatched {a.dispatch_count} time(s)");
    print(f"B dispatched {b.dispatch_count} time(s)");
    print(f"C dispatched {c.dispatch_count} time(s)");
    print(f"D dispatched {d.dispatch_count} time(s)");
    print(f"E dispatched {e.dispatch_count} time(s)");
}
