```jac
"""Framework audit A2: trace identity & authorization across persistence boundaries.

Models the audit's core scenario — a User (with a credential + role), a Document
(owned by a user, with an access policy), and a Repository façade that mediates
writes — connected by typed edges that encode the very invariants the issue
asks us to verify. An `Auditor` walker traverses the graph and reports whether
identity, ownership, and policy round-trip through every boundary.
"""

node User {
    has username: str = "";
    has credential: str = "";
    has role: str = "reader";
    has active: bool = True;
}

node Document {
    has title: str = "";
    has body: str = "";
    has access_policy: str = "owner_only";
}

node Repository {
    has name: str = "";
    has engine: str = "";
    has reachable: bool = True;
}

node PolicyDecision {
    has decision: str = "";
    has reason: str = "";
}

edge Owns {
    has granted_at: str = "";
}

edge Authorizes {
    has via: str = "";
}

edge PersistsTo {
    has commit: str = "";
}

edge Caches {
    has invalidated: bool = True;
}

walker Auditor {
    has visited: list[str] = [];
    has findings: list[str] = [];

    def seen(nname: str) -> bool {
        for v in self.visited {
            if v == nname { return True; }
        }
        return False;
    }

    def record(nname: str) -> bool {
        if self.seen(nname) {
            return False;
        }
        self.visited.append(nname);
        return True;
    }

    can start with Root entry {
        print(f"Auditor beginning framework audit A2 walk");
        visit [-->] else { disengage; }
    }

    can inspect_user with User entry {
        if not self.record(here.username) {
            visit [-->];
            return;
        }
        label = "ACTIVE" if here.active else "REVOKED";
        role_check = "ADMIN" if here.role == "admin" else "NON-ADMIN";
        finding = f"[identity] user={here.username} cred=*** role={here.role} -> {label}/{role_check}";
        self.findings.append(finding);
        visit [-->];
    }

    can inspect_document with Document entry {
        if not self.record(here.title) {
            visit [-->];
            return;
        }
        decision = "OPEN" if here.access_policy == "public_read" else "RESTRICTED";
        finding = f"[entity] doc={here.title} policy={here.access_policy} -> {decision}";
        self.findings.append(finding);
        visit [-->];
    }

    can inspect_repository with Repository entry {
        if not self.record(here.name) {
            visit [-->];
            return;
        }
        reach = "REACHABLE" if here.reachable else "UNREACHABLE";
        finding = f"[persistence] repo={here.name} engine={here.engine} -> {reach}";
        self.findings.append(finding);
        visit [-->];
    }

    can inspect_policy with PolicyDecision entry {
        if not self.record(f"policy:{here.decision}") {
            visit [-->];
            return;
        }
        finding = f"[authorization] {here.decision} because {here.reason}";
        self.findings.append(finding);
        visit [-->];
    }
}

with entry {
    # --- build the audit graph ---
    alice = User(username="alice", credential="sha256:aaaa", role="admin", active=True);
    bob = User(username="bob", credential="sha256:bbbb", role="editor", active=True);
    revoked = User(username="carol", credential="sha256:cccc", role="reader", active=False);

    public_doc = Document(title="readme.md", body="...", access_policy="public_read");
    private_doc = Document(title="strategy.md", body="...", access_policy="owner_only");

    primary_db = Repository(name="primary_db", engine="postgres", reachable=True);
    legacy_db = Repository(name="legacy_db", engine="mysql", reachable=False);
    cache = Repository(name="search_cache", engine="redis", reachable=True);

    p_open = PolicyDecision(decision="ALLOW", reason="public_read policy");
    p_deny = PolicyDecision(decision="DENY", reason="owner_only policy + non-owner");

    # --- wire typed edges encoding the audit invariants ---
    root +>:Owns(granted_at="2026-01-15"):+> alice;
    root +>:Owns(granted_at="2026-01-15"):+> bob;
    root +>:Owns(granted_at="2026-01-15"):+> revoked;

    alice +>:Owns(granted_at="2026-02-01"):+> public_doc;
    alice +>:Owns(granted_at="2026-02-01"):+> private_doc;
    bob +>:Owns(granted_at="2026-02-10"):+> public_doc;

    public_doc +>:Authorizes(via="policy_engine"):+> p_open;
    private_doc +>:Authorizes(via="policy_engine"):+> p_deny;

    public_doc +>:PersistsTo(commit="a1b2c3"):+> primary_db;
    private_doc +>:PersistsTo(commit="d4e5f6"):+> primary_db;
    primary_db +>:PersistsTo(commit="mirror"):+> legacy_db;
    public_doc +>:Caches(invalidated=True):+> cache;

    # --- spawn the auditor on root ---
    auditor = Auditor();
    root spawn auditor;

    print("---- audit findings ----");
    for f in auditor.findings {
        print(f);
    }
    print(f"---- audit visited {len(auditor.visited)} nodes; "
          f"{len(auditor.findings)} findings recorded ----");
}
