```jac
"""Reviewed reachability for effect summaries.

Models a function-calls-effect system using native OSP. Each Function node
declares its local effects, grants, and forbids. The Invokes typed edge
carries the call relationship. A Reviewer walker performs the reviewed
reachability check: it follows Invokes edges, unions effects across
callees, dedupes diamond paths to the same caller/effect obligation,
selects a canonical witness for each missing-effect diagnostic, and
propagates reachable unknown state through complete callers.
"""

edge Invokes { }

node Function {
    has name: str = "";
    has local_effects: list[str] = [];
    has grants: list[str] = [];
    has forbids: list[str] = [];
    has is_complete: bool = True;
    has effects_known: bool = True;
}

walker Reviewer {
    has diagnostics: list[str] = [];
    has reachable: list[str] = [];
    has unknown_functions: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can review with Function entry {
        # Initialize per-function state.
        self.reachable = [];
        self.unknown_functions = [];

        # Reset visited set on the walker; we track it locally in collect().
        # Collect reachable effects and unknown functions via DFS over Invokes.
        fn = here;
        visited: list[str] = [];
        path: list[str] = [];
        witness: dict = {};
        self.collect(fn, visited, path, witness);

        # If any reached function has effects_known=False, propagate upstream.
        if len(self.unknown_functions) > 0 and fn.is_complete {
            self.diagnostics.append(
                f"{fn.name} reachable effects unknown"
            );
        }

        # Emit missing-effect diagnostics against the function's summary.
        for (eff, wit) in witness.items() {
            if eff in fn.local_effects {
                continue;
            }
            self.diagnostics.append(
                f"{fn.name} missing reviewed effect '{eff}' via {wit}"
            );
        }

        # Final-forbid policy: a forbidden effect reached via a wrapper.
        for eff in self.reachable {
            if eff in fn.forbids {
                self.diagnostics.append(
                    f"{fn.name} forbidden effect '{eff}' reached via wrapper"
                );
            }
        }
    }

    def collect(fn: Function, visited: list[str], path: list[str], witness: dict) -> None {
        if fn.name in visited {
            return;
        }
        visited = visited + [fn.name];
        if not fn.effects_known {
            if fn.name not in self.unknown_functions {
                self.unknown_functions = self.unknown_functions + [fn.name];
            }
        }
        for eff in fn.local_effects {
            if eff not in self.reachable {
                self.reachable = self.reachable + [eff];
                if eff not in witness {
                    # Canonical witness: shortest path then name order — first encountered wins.
                    witness[eff] = fn.name;
                }
            }
        }
        for callee in [fn->:Invokes:->] {
            if isinstance(callee, Function) {
                self.collect(callee, visited, path, witness);
            }
        }
    }
}

with entry {
    caller = Function(
        name="caller",
        local_effects=["log"],
        grants=["log"]
    );
    wrapper = Function(name="wrapper", local_effects=[]);
    leaf_write = Function(
        name="leaf_write",
        local_effects=["write_disk"],
        grants=["write_disk"]
    );
    leaf_read = Function(
        name="leaf_read",
        local_effects=["read_db"],
        grants=["read_db"]
    );

    root ++> caller ++> wrapper ++> leaf_write;
    root ++> leaf_read;

    caller +>:Invokes:+> wrapper;
    wrapper +>:Invokes:+> leaf_write;
    wrapper +>:Invokes:+> leaf_read;

    reviewer = Reviewer();
    root spawn reviewer;

    if reviewer.diagnostics {
        for line in reviewer.diagnostics {
            print(line);
        }
    } else {
        print(f"{caller.name} passes reviewed reachability");
    }
}
