```jac
"""Large-payload streaming fast path eligibility walker.

Models AIProxer's request pipeline: a request enters through a frontend, is
admitted by a router, and is dispatched to a backend. Each consumer in the
chain declares whether it needs a canonical (fully materialized) request body
or whether it is compatible with a streamed body. A walker traverses the
consumer chain, collects their capability declarations, and derives a single
eligibility decision: whether the fast path may stream the payload upstream
or whether the canonical materialized path must be used instead.
"""

enum RequestBodyMode {
    MATERIALIZE_CANONICAL,
    STREAM_COMPATIBLE,
    STREAM_WITH_BOUNDED_REWRITE,
}

node Consumer {
    has name: str = "";
    has needs_canonical: bool = True;
    has needs_whole_body: bool = True;
    has supports_streaming_ingress: bool = False;
    has supports_streaming_rewrite: bool = False;
    has supports_opaque_payload: bool = False;
    has active: bool = True;
}

node Frontend {
    has name: str = "";
}

node Router {
    has name: str = "";
}

node Backend {
    has name: str = "";
}

node Upstream {
    has name: str = "";
    has large_payload: bool = False;
}

edge FrontendLink {}
edge RouterLink {}
edge ConsumerLink {}
edge BackendLink {}
edge UpstreamLink {}

walker Eligibility {
    has mode: RequestBodyMode = RequestBodyMode.STREAM_COMPATIBLE;
    has consumers_visited: int = 0;
    has canonical_required_by: list[str] = [];

    can start with Root entry {
        self.mode = RequestBodyMode.STREAM_COMPATIBLE;
        self.consumers_visited = 0;
        self.canonical_required_by = [];
        print("Request entering AIProxer pipeline");
        visit [-->];
    }

    can survey_frontends with Frontend entry {
        print(f"Frontend: {here.name}");
        visit [-->];
    }

    can survey_routers with Router entry {
        print(f"Router: {here.name}");
        visit [-->];
    }

    can inspect_consumers with Consumer entry {
        if not here.active {
            print(f"  Consumer {here.name} inactive - skipped");
            visit [-->];
            return;
        }
        self.consumers_visited += 1;
        if here.needs_canonical or here.needs_whole_body {
            reason = here.name;
            self.canonical_required_by.append(reason);
            self.mode = RequestBodyMode.MATERIALIZE_CANONICAL;
            print(f"  Consumer {here.name} forces canonical materialization");
        } elif here.supports_streaming_rewrite {
            if self.mode != RequestBodyMode.MATERIALIZE_CANONICAL {
                self.mode = RequestBodyMode.STREAM_WITH_BOUNDED_REWRITE;
            }
            print(f"  Consumer {here.name} supports bounded streaming rewrite");
        } elif here.supports_streaming_ingress or here.supports_opaque_payload {
            if self.mode == RequestBodyMode.STREAM_WITH_BOUNDED_REWRITE {
                # already upgraded, keep it
            } else {
                self.mode = RequestBodyMode.STREAM_COMPATIBLE;
            }
            print(f"  Consumer {here.name} is stream-compatible");
        } else {
            self.canonical_required_by.append(here.name);
            self.mode = RequestBodyMode.MATERIALIZE_CANONICAL;
            print(f"  Consumer {here.name} defaults to canonical (no streaming contract declared)");
        }
        visit [-->];
    }

    can survey_backends with Backend entry {
        print(f"Backend: {here.name}");
        visit [-->];
    }

    can survey_upstreams with Upstream entry {
        if self.mode == RequestBodyMode.MATERIALIZE_CANONICAL {
            print(f"Upstream {here.name}: full canonical path will be used");
        } elif self.mode == RequestBodyMode.STREAM_WITH_BOUNDED_REWRITE {
            if here.large_payload {
                print(f"Upstream {here.name} confirmed large-payload with bounded rewrite");
            } else {
                print(f"Upstream {here.name}: bounded rewrite path will be used");
            }
        } elif self.mode == RequestBodyMode.STREAM_COMPATIBLE {
            if here.large_payload {
                print(f"Upstream {here.name} confirmed large-payload stream");
            } else {
                print(f"Upstream {here.name}: stream-compatible path will be used");
            }
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    openai = Frontend(name="openai-frontend");
    auth = Consumer(name="auth-middleware", needs_canonical=False, needs_whole_body=False, supports_streaming_ingress=True);
    route = Consumer(name="route-lookup", needs_canonical=False, needs_whole_body=False, supports_streaming_ingress=True);
    qos = Consumer(name="qos-quota", needs_canonical=False, needs_whole_body=False, supports_streaming_ingress=True);
    acct = Consumer(name="body-byte-accounting", needs_canonical=False, needs_whole_body=False, supports_streaming_ingress=True);
    dlp = Consumer(name="dlp-scanner", needs_canonical=True, needs_whole_body=True, supports_streaming_ingress=False, supports_opaque_payload=False);
    guard = Consumer(name="guardrails", needs_canonical=False, needs_whole_body=False, supports_streaming_rewrite=True);
    cache = Consumer(name="semantic-response-cache", needs_canonical=True, needs_whole_body=True);

    router = Router(name="model-router");
    backend = Backend(name="openai-backend");
    upstream = Upstream(name="upstream-openai", large_payload=True);

    root +>:FrontendLink:+> openai;
    openai +>:ConsumerLink:+> auth;
    openai +>:ConsumerLink:+> route;
    openai +>:ConsumerLink:+> qos;
    openai +>:ConsumerLink:+> acct;
    openai +>:ConsumerLink:+> dlp;
    openai +>:ConsumerLink:+> guard;
    openai +>:ConsumerLink:+> cache;
    openai +>:RouterLink:+> router;
    router +>:BackendLink:+> backend;
    backend +>:UpstreamLink:+> upstream;

    print("=== Scenario A: DLP forces canonical path (active in chain) ===");
    Eligibility() spawn root;
    print();

    print("=== Scenario B: DLP inactive, all consumers stream-friendly ===");
    dlp.active = False;
    cache.active = False;
    guard.active = False;
    Eligibility() spawn root;
    print();

    print("=== Scenario C: guardrails active but rewriting stays bounded ===");
    dlp.active = True;
    cache.active = False;
    guard.active = True;
    Eligibility() spawn root;
}
