```jac
"""TypeSpec patch-model transformation: walk a resource model and turn
every Lifecycle.Update property into an optional one, recursively through
nested model properties.

Models the core scenario from issue #11774 — recursion over a properties
bag with a per-property visibility decision and an in-place optionality
rewrite. The recursion is expressed as a walker over typed containment
edges, and the cycle guard is explicit (jac walkers do not dedupe on
their own)."""

# A resource model — holds a typed bag of properties reachable via edges.
node Model {
    has title: str = "";
}

# A property node. Holds the visibility decision and the optional flag
# the walker will rewrite. Points at either a NestedModel or a PropertyLeaf.
node Property {
    has name: str = "";
    has visibility: str = "";
    has optional: bool = False;
}

# A nested model reachable from a property (sub-model container).
node NestedModel {
    has type_name: str = "";
}

# A scalar leaf reachable from a property.
node PropertyLeaf {
    has type_name: str = "";
}

# Typed edges — every referenced type is declared at module level.
edge HasProperty { }
edge HasNested { }
edge IsLeaf { }

# The walker that performs the recursive OptionalProperties transformation.
walker PatchTransformer {
    has visited_ids: list = [];
    has flipped: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    # Land on a Model: sweep its properties, then descend into nested ones.
    can descend with Model entry {
        nid = here;
        if nid in self.visited_ids {
            disengage;
        }
        self.visited_ids.append(nid);

        print(f"model: {here.title}");

        for prop in [here ->:HasProperty:->] {
            label = prop.name;
            new_optional = (prop.visibility == "Update");
            was_optional = prop.optional;
            prop.optional = new_optional;
            if new_optional and not was_optional {
                self.flipped += 1;
                print(f"  [flip] {label} -> optional (visibility={prop.visibility})");
            } else {
                print(f"  [keep] {label} optional={prop.optional} (visibility={prop.visibility})");
            }

            # First report any leaf references for this property.
            for leaf in [prop ->:IsLeaf:->] {
                print(f"  [leaf] {label}: {leaf.type_name}");
            }
            # Then descend into nested sub-models via the bridge property.
            for nested in [prop ->:HasNested:->] {
                print(f"  nested: {nested.type_name}");
                # The NestedModel is just a label/anchor — the actual
                # properties live on a sibling Model connected through
                # the global graph. We surface the nested name above
                # and let the walker continue traversing the graph via
                # forward edges so the matching Model gets visited.
            }
        }

        # Continue walking the graph so nested Models are visited.
        visit [-->] else { disengage; }
    }

    # If we land on a NestedModel directly, log it and continue.
    can descend_nested with NestedModel entry {
        print(f"  nested: {here.type_name}");
        visit [-->] else { disengage; }
    }
}

with entry {
    # Build a tiny resource model with nested sub-models, matching the
    # "properties bag with required nested fields" scenario from the issue.

    resource = Model(title="VirtualMachine");
    inner = Model(title="VirtualMachineProperties");
    inner2 = Model(title="OSDisk");

    # Wire top-level resource properties (mix of leaves and a nested ref).
    resource +>:HasProperty:+> Property(name="name", visibility="Update");
    resource +>:HasProperty:+> Property(name="location", visibility="Create");
    resource +>:HasProperty:+> Property(name="identity", visibility="Read");

    nested_prop = Property(name="properties", visibility="Update");
    resource +>:HasProperty:+> nested_prop;
    nested_prop +>:HasNested:+> NestedModel(type_name="VirtualMachineProperties");

    # Properties on the nested VirtualMachineProperties model.
    inner +>:HasProperty:+> Property(name="size", visibility="Update");
    inner +>:HasProperty:+> Property(name="image", visibility="Create");
    inner +>:HasProperty:+> Property(name="osDisk", visibility="Update");

    ip_nested_prop = Property(name="osDisk", visibility="Update");
    inner +>:HasProperty:+> ip_nested_prop;
    ip_nested_prop +>:HasNested:+> NestedModel(type_name="OSDisk");

    # Properties on the deeper OSDisk model.
    inner2 +>:HasProperty:+> Property(name="size", visibility="Update");
    inner2 +>:HasProperty:+> Property(name="caching", visibility="Read");

    # A few scalar leaves attached directly to properties for richness.
    np_name = Property(name="displayName", visibility="Update");
    nested_prop +>:HasProperty:+> np_name;
    np_name +>:IsLeaf:+> PropertyLeaf(type_name="string");

    # Connect everything under root so the walker can traverse forward.
    root ++> resource ++> inner ++> inner2;

    # Spawn the walker.
    walker_inst = PatchTransformer();
    root spawn walker_inst;

    print(f"\ntotal properties flipped to optional: {walker_inst.flipped}");
    print("visited nodes (cycle-guarded):");
    for n in walker_inst.visited_ids {
        print(f"  - {n.title}");
    }
}
