```jac
"""Pipeline triage: grill-then-ready workflow.

Models the core scenario of #1072 — a Decisions frontier is proposed
by an Implementer walker, then a Reviewer walker accepts or challenges
each unsettled node. Only operator-required authority classes stay
unresolved; everything else takes its recommended default. The
demonstration walks the graph, classifies nodes by authority class,
and reports the final frontier.
"""

# --- Core entity archetypes ----------------------------------------------

node Decision {
    has question: str = "";
    has recommendation: str = "";
    has authority_class: str = "auto";
    has resolution: str = "unresolved";
    has challenge_reason: str = "";
    has fingerprint: str = "";
}

node Issue {
    has title: str = "";
    has body: str = "";
    has stage: str = "raw";
}

node Fact {
    has key: str = "";
    has value: str = "";
    has trusted: bool = True;
}

# --- Relationships as typed edges ----------------------------------------

edge Cites { }
edge Proposes { }

# --- Walker: Implementer proposes a Decision frontier --------------------

walker Implementer {
    has model_name: str = "planner-v1";
    has effort: int = 3;

    can start with Root entry {
        print(f"[implementer] model={self.model_name} effort={self.effort}");
        visit [-->];
    }

    can propose with Issue entry {
        print(f"[implementer] grilling: {here.title}");
        visit [->:Proposes:->];
    }

    can emit with Decision entry {
        here.fingerprint = f"{here.question}|{here.recommendation}";
        print(f"  proposes[{here.authority_class}] {here.question} -> {here.recommendation}");
        visit [->:Cites:->];
    }

    can cite with Fact entry {
        visit [->:Proposes:->];
    }
}

# --- Walker: Reviewer accepts or challenges each unsettled node ----------

walker Reviewer {
    can start with Root entry {
        print("[reviewer] reviewing Decisions frontier");
        visit [-->];
    }

    can audit with Issue entry {
        visit [->:Proposes:->];
    }

    can rule with Decision entry {
        verdict_class = here.authority_class;
        if here.authority_class == "scope" or here.authority_class == "security" or here.authority_class == "merge" or here.authority_class == "attestation" {
            here.resolution = "challenged";
            here.challenge_reason = f"requires operator authority (class={here.authority_class})";
            print(f"  reviewer[{verdict_class}] -> challenge: {here.challenge_reason}");
        } else {
            here.resolution = "default";
            here.challenge_reason = "eligible for recommended default";
            print(f"  reviewer[{verdict_class}] -> default (eligible for recommended default)");
        }
    }
}

# --- Walker: Operator settles only the authority-class challenges --------

walker Operator {
    can start with Root entry {
        print("[operator] settling authority-class challenges");
        visit [-->];
    }

    can clear with Issue entry {
        visit [->:Proposes:->];
    }

    can settle with Decision entry {
        if here.resolution == "challenged" {
            here.resolution = "accepted";
            here.challenge_reason = "";
            print(f"  operator -> accepted: {here.question}");
        }
    }
}

# --- Walker: Auditor verifies the frontier -------------------------------

walker TriageAuditor {
    can start with Root entry {
        print("[auditor] verifying Decisions frontier");
        visit [-->];
    }

    can check with Issue entry {
        visit [->:Proposes:->];
    }

    can tally with Decision entry {
        if here.resolution == "unresolved" {
            print(f"  UNRESOLVED: {here.question}");
        }
    }
}

# --- Demo wiring ---------------------------------------------------------

with entry {
    issue = Issue(title="Promote service v2", body="initial body");

    d_auto = Decision(
        question="default log level?",
        recommendation="INFO",
        authority_class="auto"
    );
    d_scope = Decision(
        question="which endpoints are in scope?",
        recommendation="/v2/* only",
        authority_class="scope"
    );
    d_merge = Decision(
        question="merge strategy?",
        recommendation="squash",
        authority_class="merge"
    );

    f1 = Fact(key="service.owner", value="platform-team");
    f2 = Fact(key="service.repo", value="agent-pipeline");

    root ++> issue;
    issue +>:Cites:+> f1;
    issue +>:Cites:+> f2;

    issue +>:Proposes:+> d_auto;
    issue +>:Proposes:+> d_scope;
    issue +>:Proposes:+> d_merge;

    root spawn Implementer();

    root spawn Reviewer();

    root spawn Operator();

    root spawn TriageAuditor();

    all_resolved = d_auto.resolution != "unresolved"
                   and d_scope.resolution != "unresolved"
                   and d_merge.resolution != "unresolved";
    issue.stage = "ready" if all_resolved else "rejected";
    print(f"\nfinal stage: {issue.stage}");
}
```

