"""Retrieval-ADR decision walk: a walker compares Hybrid vs Corrective RAG
patterns over a small corpus, respecting the Loop Contract's verifier /
budget / stop_reason discipline from issue #335."""

node Corpus {
    has name: str = "";
}

node Chunk {
    has text: str = "";
    has source: str = "";
    has relevance: float = 0.0;
}

node Query {
    has text: str = "";
    has budget: int = 0;
}

node Verifier {
    has name: str = "";
    has threshold: float = 0.0;
}

edge HybridEdge { }
edge CorrectiveEdge { has confidence: float = 0.0; }
edge Verifies { }

walker RetrievalAuditor {
    has pattern: str = "Hybrid";
    has selected: list[str] = [];
    has stop_reason: str = "";
    has cost: int = 0;
    has latency: int = 0;
    has query_budget: int = 3;

    can start with Root entry {
        print(f"ADR audit: pattern = {self.pattern}");
        visit [-->];
    }

    can pick_corpus with Corpus entry {
        print(f"corpus selected: {here.name}");
        visit [-->];
    }

    can audit with Query entry {
        self.cost = 0;
        self.latency = 0;
        if self.pattern == "Hybrid" {
            visit [->:HybridEdge:->];
        } elif self.pattern == "Corrective" {
            visit [->:CorrectiveEdge:->];
        } else {
            self.stop_reason = "unsupported_pattern";
            disengage;
        }
        visit [->:Verifies:->];
    }

    can rank with Chunk entry {
        self.cost += 1;
        self.latency += 2;
        if here.relevance >= 0.5 {
            self.selected.append(here.text);
        }
        if self.cost >= self.query_budget {
            self.stop_reason = "budget_exhausted";
            disengage;
        }
    }

    can gate with Verifier entry {
        if here.threshold > 0.9 {
            self.stop_reason = "verifier_rejected";
            disengage;
        }
        print(f"verifier {here.name} passed (threshold={here.threshold})");
        self.stop_reason = "verifier_passed";
    }
}

with entry {
    docs = Corpus(name="docs+code");
    root ++> docs;

    q = Query(text="how does retrieval stop?", budget=3);
    docs ++> q;

    c1 = Chunk(text="verifier-driven stop", source="doc", relevance=0.8);
    c2 = Chunk(text="search until confident", source="doc", relevance=0.2);
    c3 = Chunk(text="budget exhausted mid-walk", source="code", relevance=0.6);

    q +>:HybridEdge:+> c1;
    q +>:HybridEdge:+> c2;
    q +>:HybridEdge:+> c3;

    v = Verifier(name="CERBERUS", threshold=0.85);
    q +>:Verifies:+> v;

    auditor = RetrievalAuditor(pattern="Hybrid", query_budget=2);
    root spawn auditor;
    print(f"Hybrid  selected={auditor.selected}  stop_reason={auditor.stop_reason}"
          f"  cost={auditor.cost}  latency={auditor.latency}");

    cr_c1 = Chunk(text="corrected chunk A", source="doc", relevance=0.7);
    cr_c2 = Chunk(text="corrected chunk B", source="code", relevance=0.9);
    cr_c3 = Chunk(text="low-confidence filler", source="code", relevance=0.1);

    q2 = Query(text="compare patterns", budget=5);
    docs ++> q2;
    q2 +>:CorrectiveEdge(confidence=0.9):+> cr_c1;
    q2 +>:CorrectiveEdge(confidence=0.95):+> cr_c2;
    q2 +>:CorrectiveEdge(confidence=0.3):+> cr_c3;

    auditor2 = RetrievalAuditor(pattern="Corrective", query_budget=2);
    root spawn auditor2;
    print(f"CRAG   selected={auditor2.selected}  stop_reason={auditor2.stop_reason}"
          f"  cost={auditor2.cost}  latency={auditor2.latency}");

    print("ADR stance: Hybrid candidate, Corrective strongest CERBERUS alignment,"
          " GraphRAG/Agentic/Multimodal deferred until corpus+query+eval evidence.");
}
