type Seq = { _brand: "Seq" };

// `Branch` to connect Branch<A,B>
type Branch<L1 extends Seq, L2 extends Seq, R1 extends Seq, R2 extends Seq> = Seq & {
  type: "Branch";
  left1: L1;
  left2: L2;
  right1: R1;
  right2: R2;
};

// `A` and `B` are the basic elements of the sequence.
type A = Seq & { type: "A" };
type B = Seq & { type: "B" };
type C = Seq & { type: "C" };
type D = Seq & { type: "D" };

// Recursively rewrite the entire sequence tree.
type Rewrite<T extends Seq> = T extends A
  ? Branch<A, B, C, D>
  : T extends B
  ? Branch<B, C, D, A>
	: T extends C
	? Branch<C, D, A, B>
	: T extends D
	? Branch<D, A, B, C>
  : T extends Branch<infer L1 extends Seq, infer L2 extends Seq, infer R1 extends Seq, infer R2 extends Seq>
  ? Branch<Rewrite<L1>, Rewrite<L2>, Rewrite<R1>, Rewrite<R2>>
  : never;

// `Nat` and `Succ`/`Zero` are used for type-level counting.
// Represents numbers at the type level.
type Nat = { _brand: "nat" };
type Zero = Nat & { type: "Zero" };
type Succ<N extends Nat> = Nat & { type: "Succ"; pred: N };

// Apply rewrite rules N times using recursive conditional types
// TypeScript has recursion depth limits, so large N values will fail
type ApplyRewrite<S extends Seq, N extends Nat> = N extends Zero
  ? S // Base case: 0 iterations returns original
  : N extends Succ<infer P extends Nat> // Recursive case: N = Succ(P)
  ? ApplyRewrite<Rewrite<S>, P> // Apply one rewrite, then recurse with P
  : never;

// Define a more complex type union calculation
type SeqUnion<T extends Seq> = T extends A
  ? StringProperty
  : T extends B
  ? NumericProperty
	: T extends C
	? `${NumericProperty}${StringProperty}`
	: T extends D
	? `${StringProperty}${NumericProperty}`
  : T extends Branch<infer L1 extends Seq, infer L2 extends Seq, infer R1 extends Seq, infer R2 extends Seq> 
  ? `${SeqUnion<L1>}${SeqUnion<R1>}` | `${SeqUnion<L2>}${SeqUnion<R2>}`
  : never;

// trigger the compile-time evaluation.
type InitialState = A;

// Note: the following is harmful. Set iteration count to N=40.
// Complex binary tree
// Result: Compilation bomb! Compilation leads to OOM, takes a very long time, and causes a Denial of Service.
type N40 = Succ<Succ<Succ<Succ<Succ<Succ<Succ<Succ<Succ<Succ<
          Succ<Succ<Succ<Succ<Succ<Succ<Succ<Succ<Succ<Succ

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Recursive type rewrite bomb — modeled as a walker over a Seq tree.

Models the TypeScript OOM scenario: a Branch node holds four Seq children
and is recursively rewritten. The walker performs the "ApplyRewrite"
traversal, tracking which Seq nodes it has already visited (the source's
cycle/depth guard) so it terminates like the TS recursion limit.
"""

node Seq {
    has label: str = "";
}

node Atom(Seq) {
    has kind: str = "";
}

node Branch(Seq) {
    has left1: object = None;
    has left2: object = None;
    has right1: object = None;
    has right2: object = None;
}

edge Child { }
edge RewrittenTo { has generation: int = 0; }

walker ApplyRewrite {
    has max_generations: int = 0;
    has visited: list[str] = [];

    can begin with Root entry {
        # If the root has outgoing edges, follow them; otherwise the
        # demo graph has nothing to traverse from here.
        visit [-->] else { disengage; }
    }

    # Single union trigger for Seq nodes (Atom OR Branch). Only reads
    # `label`, which both share via the Seq base. The depth/cycle guard
    # terminates before the rewrite can blow up.
    can inspect with Atom | Branch entry {
        if self.max_generations <= 0 {
            print("depth budget exhausted — halting (matches TS recursion limit)");
            disengage;
        }
        if here.label in self.visited {
            print(f"already rewrote {here.label}, stopping cycle");
            disengage;
        }
        self.visited.append(here.label);
        self.max_generations -= 1;
        print(f"visiting {here.label}");
        visit [-->];
    }

    # Atom-specific ability: produce a fresh Branch quad and link it via
    # a typed RewrittenTo edge (the rewrite cascade is observable in the
    # graph as a real relationship, not a string note).
    can rewrite with Atom entry {
        quad = Branch(
            label=f"{here.label}.branch"
        );
        c1 = Atom(kind="A", label=f"{here.label}.L1");
        c2 = Atom(kind="B", label=f"{here.label}.L2");
        c3 = Atom(kind="C", label=f"{here.label}.R1");
        c4 = Atom(kind="D", label=f"{here.label}.R2");
        quad +>:Child:+> c1;
        quad +>:Child:+> c2;
        quad +>:Child:+> c3;
        quad +>:Child:+> c4;
        here +>:RewrittenTo(generation=self.max_generations):+> quad;
        visit [->:RewrittenTo:->];
    }

    # Branch-specific ability: descend into children over typed Child edges.
    can descend with Branch entry {
        visit [->:Child:->];
    }
}

# NOTE: the `with entry` block is the human-facing demo. The test harness
# deletes it before running, so the shared `root` stays clean.
with entry {
    # Seed: a single Atom A.
    seed = Atom(kind="A", label="A0");

    # Build a Branch with four atoms, connected by typed Child edges.
    b = Branch(label="B0");
    a1 = Atom(kind="A", label="B0.L1");
    a2 = Atom(kind="B", label="B0.L2");
    a3 = Atom(kind="C", label="B0.R1");
    a4 = Atom(kind="D", label="B0.R2");
    b +>:Child:+> a1;
    b +>:Child:+> a2;
    b +>:Child:+> a3;
    b +>:Child:+> a4;

    # Hook the branch into the seed via a Child edge.
    seed +>:Child:+> b;

    root ++> seed;

    # Budget of 8 mirrors the TS recursion limit behaviour: large enough
    # to observe the cascade, small enough to terminate deterministically.
    root spawn ApplyRewrite(max_generations=8);
}
