```jac
"""Unified task system: idempotent + parallel task execution modeled as a graph walk.

A TaskSystem node holds a registry of Task nodes connected by typed edges.
The TaskRunner walker visits every task in topological order (dependencies
first), honoring cycle detection and skipping already-completed work for
idempotency. Parallel groups suspend once, then resume when every member
finishes — modeled here by walking each parallel-group cluster and reporting
the single suspension point.
"""

node Task {
    has id: str = "";
    has kind: str = "sync";
    has output: str = "";
    has status: str = "pending";
    has started_at: int = 0;
    has completed_at: int = 0;
}

node ParallelGroup {
    has id: str = "";
    has member_count: int = 0;
}

node Checkpoint {
    has id: str = "";
    has prompt: str = "";
    has approved: bool = False;
}

edge DependsOn { }
edge PartOf { }
edge Approves { }

walker TaskRunner {
    has tick: int = 0;
    has visiting: list[str] = [];
    has order: list[str] = [];
    has suspensions: int = 0;
    has completed_runs: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can run with Task entry {
        if here.status == "completed" {
            print(f"  -> task {here.id} already completed (idempotent skip)");
            visit [-->];
            return;
        }
        if here.id in self.visiting {
            cycle_msg = f"[CYCLE DETECTED] re-entered {here.id}";
            print(cycle_msg);
            disengage;
        }
        self.visiting = self.visiting + [here.id];
        here.status = "running";
        here.started_at = self.tick;
        self.tick = self.tick + 1;
        print(f"  -> running task {here.id} ({here.kind})");
        visit [->:DependsOn:->];
        here.output = f"output-of-{here.id}";
        here.status = "completed";
        here.completed_at = self.tick;
        self.tick = self.tick + 1;
        self.completed_runs = self.completed_runs + 1;
        self.order = self.order + [here.id];
        self.visiting = self.visiting[:-1];
        visit [-->];
    }

    can group with ParallelGroup entry {
        print(f"  -> parallel-group {here.id} has {here.member_count} member(s); suspend once, resume when all complete");
        self.suspensions = self.suspensions + 1;
        visit [-->];
        print(f"  -> resumed after all members of {here.id} completed");
    }

    can gate with Checkpoint entry {
        here.approved = True;
        print(f"  -> checkpoint {here.id} approved: {here.prompt}");
        visit [->:Approves:->];
        visit [-->];
    }
}

with entry {
    email_alice = Task(id="email_alice", kind="async");
    email_bob = Task(id="email_bob", kind="async");
    summarize = Task(id="summarize", kind="sync");
    schedule = Task(id="schedule", kind="sync");
    notify = Task(id="notify", kind="sync");

    root +>:DependsOn:+> email_alice;
    root +>:DependsOn:+> email_bob;
    email_alice +>:DependsOn:+> summarize;
    email_bob +>:DependsOn:+> summarize;
    schedule +>:DependsOn:+> notify;

    call_group = ParallelGroup(id="call_alice_bob", member_count=2);
    notify_group = ParallelGroup(id="notify_team", member_count=1);
    root +>:PartOf:+> call_group;
    call_group +>:PartOf:+> email_alice;
    call_group +>:PartOf:+> email_bob;
    root +>:PartOf:+> notify_group;
    notify_group +>:PartOf:+> notify;

    confirm = Checkpoint(id="confirm_meeting", prompt="Schedule meeting for Tuesday 2pm?");
    root +>:Approves:+> confirm;
    confirm +>:Approves:+> schedule;

    runner = TaskRunner();
    root spawn runner;

    print("");
    print(f"execution order: {runner.order}");
    print(f"completed runs (idempotent dedupe): {runner.completed_runs}");
    print(f"suspension points: {runner.suspensions}");
    print(f"checkpoint approved: {confirm.approved}");
    print(f"email_alice status: {email_alice.status}");
    print(f"email_bob status: {email_bob.status}");
    print(f"summarize status: {summarize.status}");
    print(f"schedule status: {schedule.status}");
    print(f"notify status: {notify.status}");
}
