```jac
"""escalation-stale observability: model unobserved scheduled workflow reds, consumer doctor drift, and the missing notification path."""

node WorkflowRun {
    has commit_sha: str = "";
    has run_time: str = "";
    has conclusion: str = "success";
}

node EscalationAudit {
    has job_name: str = "escalation-audit";
}

node ConsumerCheck {
    has step_name: str = "";
    has passed: bool = True;
}

node Violation {
    has consumer_id: str = "";
    has detail: str = "";
}

node EscalationWorkflow {
    has workflow_name: str = "escalation-stale";
    has required_check: bool = False;
    has notification_enabled: bool = False;
}

node ProtectedBranch {
    has branch_name: str = "main";
}

edge Chronological { }
edge Executes { }
edge Reports { }
edge NotRequired { }

walker RunHistorian {
    has consecutive_failures: int = 0;
    has first_red_sha: str = "";
    has last_green_sha: str = "";

    can start with Root entry {
        print("escalation-stale: auditing scheduled run history on main");
        visit [-->];
    }

    can scan with WorkflowRun entry {
        if here.conclusion == "failure" {
            self.consecutive_failures += 1;
            if self.first_red_sha == "" {
                self.first_red_sha = here.commit_sha;
            }
            week_label = f"week {self.consecutive_failures} unobserved red";
            print(f"[FAIL] {here.run_time} head={here.commit_sha} ({week_label})");
        } else {
            self.last_green_sha = here.commit_sha;
            print(f"[ OK ] {here.run_time} head={here.commit_sha}");
        }
        visit [->:Chronological:->] else {
            print(
                f"streak summary: {self.consecutive_failures} consecutive failure(s) "
                f"after last green {self.last_green_sha}"
            );
            if self.first_red_sha != "" {
                print(
                    f"baseline drift window: {self.last_green_sha} (green) "
                    f"-> {self.first_red_sha} (first red)"
                );
            }
            disengage;
        };
    }
}

walker ConsumerDoctor {
    can start with Root entry {
        print("HELIX consumer doctor: scanning consumer adoption surfaces");
        visit [-->];
    }

    can audit with EscalationAudit entry {
        print(f"job: {here.job_name}");
        visit [->:Executes:->] else { disengage; };
    }

    can inspect with ConsumerCheck entry {
        mark = "OK" if here.passed else "X";
        print(f"  [{mark}] {here.step_name}");
        if here.passed {
            visit [->:Executes:->] else { disengage; };
        } else {
            visit [->:Reports:->] else { disengage; };
        }
    }

    can cite with Violation entry {
        print(f"    doctor: {here.consumer_id} - violation {here.detail}");
    }
}

walker ObservabilityGuard {
    has gap_found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with ProtectedBranch entry {
        print(f"branch protection probe: {here.branch_name}");
        visit [->:NotRequired:->] else { disengage; };
    }

    can assess with EscalationWorkflow entry {
        if not here.required_check and not here.notification_enabled {
            self.gap_found = True;
            print(
                f"OBSERVABILITY GAP: {here.workflow_name} is not required "
                f"and has no notification path"
            );
            print("  harness-check stays green; weekly scheduled reds go unseen");
            print(
                "REMEDIATION: auto-file Issue on failure OR "
                f"trigger {here.workflow_name} on push to main"
            );
        }
        disengage;
    }
}

with entry {
    run_green = WorkflowRun(
        commit_sha="b828fcf6",
        run_time="2026-07-06T03:51",
        conclusion="success"
    );
    run_red1 = WorkflowRun(
        commit_sha="f3bdee41",
        run_time="2026-07-13T03:20",
        conclusion="failure"
    );
    run_red2 = WorkflowRun(
        commit_sha="7bc77da4",
        run_time="2026-07-20T03:28",
        conclusion="failure"
    );
    run_red3 = WorkflowRun(
        commit_sha="ce501063",
        run_time="2026-07-27T03:29",
        conclusion="failure"
    );
    root ++> run_green +>:Chronological:+> run_red1 +>:Chronological:+> run_red2
        +>:Chronological:+> run_red3;

    audit = EscalationAudit(job_name="escalation-audit");
    status = ConsumerCheck(step_name="HELIX status and continuation", passed=True);
    packet = ConsumerCheck(step_name="HELIX completion decision packet", passed=True);
    bundle = ConsumerCheck(step_name="HELIX completion review bundle", passed=True);
    doctor = ConsumerCheck(step_name="HELIX consumer doctor", passed=False);
    root ++> audit;
    audit +>:Executes:+> status +>:Executes:+> packet +>:Executes:+> bundle
        +>:Executes:+> doctor;

    doctor +>:Reports:+> Violation(
        consumer_id="consumer-claude-adapter",
        detail="Claude hooks JSON/schema baseline incomplete"
    );
    doctor +>:Reports:+> Violation(
        consumer_id="consumer-codex-adapter",
        detail="Codex hooks/config JSON/schema baseline incomplete"
    );
    doctor +>:Reports:+> Violation(
        consumer_id="consumer-claude-surface",
        detail="invalidAgents=.claude/agents/be-api.md,.claude/agents/be-logic.md,..."
    );
    doctor +>:Reports:+> Violation(
        consumer_id="consumer-team-run-surface",
        detail="path=.helix/teams/default-hybrid.yaml schema=false messages=schema-invalid"
    );
    doctor +>:Reports:+> Violation(
        consumer_id="consumer-vscode-tasks",
        detail="missing_or_wrong=HELIX: status,HELIX: doctor,..."
    );
    doctor +>:Reports:+> Violation(
        consumer_id="consumer-escalation-workflow",
        detail="unexpectedTriggers=workflow_dispatch tokenWrite=false"
    );

    main_branch = ProtectedBranch(branch_name="main");
    escalation_wf = EscalationWorkflow(
        workflow_name="escalation-stale",
        required_check=False,
        notification_enabled=False
    );
    root ++> main_branch;
    main_branch +>:NotRequired:+> escalation_wf;

    root spawn RunHistorian();
    root spawn ConsumerDoctor();
    root spawn ObservabilityGuard();
}
