```jac
"""Submodule dependency cleanup: model a parent project, vendored submodules,
helpers and provenance notes, then walk the graph to confirm legacy names only
appear where legally required and the bad helper is purged before pinning
the submodule."""

node Submodule {
    has name: str = "";
    has upstream_repo: str = "";
    has carries_legacy_helper: bool = True;
    has pin_advanced: bool = False;
}

node HelperFile {
    has path: str = "";
    has framework_name: str = "";
    has still_referenced_by_parent: bool = False;
}

node ProvenanceNote {
    has path: str = "";
    has requires_legacy_text: bool = False;
}

node ParentProject {
    has name: str = "";
}

edge DependsOn { }
edge Contains { }
edge References { }

walker DependencyAuditor {
    has seen: list = [];
    has bad_findings: int = 0;
    has clean: bool = True;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can audit_parent with ParentProject entry {
        visit [->:DependsOn:->];
    }

    can audit with Submodule entry {
        self.seen.append(here);
        visit [->:Contains:->];
    }

    can audit_helper with HelperFile entry {
        self.seen.append(here);
        if here.still_referenced_by_parent {
            self.bad_findings += 1;
            self.clean = False;
            print(f"  [FINDING] {here.path} still references "
                  f"{here.framework_name}");
        } else {
            print(f"  [ok] {here.path} is dead, safe to delete upstream");
        }
        visit [-->];
    }

    can audit_provenance with ProvenanceNote entry {
        self.seen.append(here);
        if here.requires_legacy_text {
            print(f"  [ok] {here.path} keeps legacy attribution by license");
        } else {
            print(f"  [ok] {here.path} carries no legacy text");
        }
        visit [-->];
    }
}

walker SubmodulePinAdvancer {
    has advanced: bool = False;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can advance_parent with ParentProject entry {
        visit [->:DependsOn:->];
    }

    can advance with Submodule entry {
        if here.carries_legacy_helper {
            print(f"  [BLOCKED] cannot pin {here.name}: legacy helper "
                  f"still present upstream");
            disengage;
        }
        here.pin_advanced = True;
        self.advanced = True;
        print(f"  [PINNED] {here.name} -> reviewed revision "
              f"({here.upstream_repo})");
        visit [-->];
    }
}

with entry {
    parent = ParentProject(name="dusk-studio");
    fizz = Submodule(name="dusk-fizz", upstream_repo="dusk-audio/dusk-fizz",
                     carries_legacy_helper=True);
    rect = Submodule(name="Rectify", upstream_repo="dusk-audio/Rectify",
                     carries_legacy_helper=False, pin_advanced=False);

    legacy_helper = HelperFile(path="external/sfizz/legacy/da_fizz_helper.cpp",
                               framework_name="DAF",
                               still_referenced_by_parent=False);
    license_note = ProvenanceNote(path="external/sfizz/THIRD_PARTY.txt",
                                  requires_legacy_text=True);
    rectify_helper = HelperFile(path="external/rectify/bounds_fix.cpp",
                                framework_name="Rectify",
                                still_referenced_by_parent=True);

    parent +>:DependsOn:+> fizz;
    parent +>:DependsOn:+> rect;
    fizz +>:Contains:+> legacy_helper;
    fizz +>:Contains:+> license_note;
    rect +>:Contains:+> rectify_helper;
    parent +>:References:+> rectify_helper;

    print("=== Audit pass (recursive working-tree scan) ===");
    auditor = DependencyAuditor();
    parent spawn auditor;
    print(f"  bad_findings={auditor.bad_findings} clean={auditor.clean}");

    print("=== Pin advance attempt ===");
    advancer = SubmodulePinAdvancer();
    parent spawn advancer;
    print(f"  advanced={advancer.advanced} "
          f"fizz.pin_advanced={fizz.pin_advanced} "
          f"rect.pin_advanced={rect.pin_advanced}");
}
