```jac
"""Bounded RFC 5280 certificate path construction and validation demo.

Models peer-supplied intermediates plus explicit trust anchors, walks issuer
chains with cycle/depth/budget guards, and validates policy at an injected UTC
instant. V1 reports revocation-not-checked and performs no network fetch.
"""

node Certificate {
    has subject: str = "";
    has issuer: str = "";
    has not_before: int = 0;
    has not_after: int = 0;
    has is_ca: bool = False;
    has path_len: int = 0;
    has unlimited_path_len: bool = True;
    has server_auth: bool = False;
    has sig_valid: bool = True;
}

node TrustAnchor {
    has subject: str = "";
    has label: str = "";
}

node ValidationPolicy {
    has validation_time: int = 0;
    has max_depth: int = 8;
    has search_budget: int = 32;
    has clock_available: bool = True;
}

edge Issues { }
edge IssuedBy { }
edge Anchors { }

walker PathConstructor {
    has budget: int = 16;
    has target_subject: str = "";
    has seen: list[str] = [];
    has path: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can build with Certificate entry {
        if here.subject in self.seen {
            print("FAIL: cycle or duplicate certificate in path");
            disengage;
        }
        self.seen.append(here.subject);
        self.path.append(here.subject);
        if here.subject == self.target_subject {
            print(f"built candidate path: {self.path}");
            disengage;
        }
        self.budget -= 1;
        if self.budget <= 0 {
            print("FAIL: construction budget exhausted");
            disengage;
        }
        visit [->:Issues:->] else { disengage; }
    }
}

walker CertPathValidator {
    has validation_time: int = 0;
    has max_depth: int = 8;
    has budget: int = 32;
    has trust_subjects: list[str] = [];
    has seen: list[str] = [];
    has depth: int = 0;
    has valid: bool = False;
    has status: str = "";

    def check_time(cert: Certificate) -> bool {
        return (
            self.validation_time >= cert.not_before
            and self.validation_time <= cert.not_after
        );
    }

    def finish_chain(top: Certificate) {
        if top.issuer in self.trust_subjects {
            self.valid = True;
            self.status = "valid";
            print(
                f"PASS: chain anchors at trusted '{top.issuer}' "
                f"(revocation-not-checked)"
            );
        } else {
            self.status = "untrusted-root";
            print(f"FAIL: untrusted issuer '{top.issuer}'");
        }
    }

    def process_cert(cert: Certificate, is_leaf: bool) -> bool {
        if self.budget <= 0 {
            self.status = "budget-exhausted";
            print("FAIL: validation search budget exhausted");
            return False;
        }
        self.budget -= 1;

        if cert.subject in self.seen {
            self.status = "cycle-or-duplicate";
            print(f"FAIL: duplicate certificate '{cert.subject}'");
            return False;
        }
        self.seen.append(cert.subject);
        self.depth += 1;

        if self.depth > self.max_depth {
            self.status = "excessive-depth";
            print("FAIL: excessive path depth");
            return False;
        }

        if not self.check_time(cert) {
            self.status = "validity";
            print(
                f"FAIL: '{cert.subject}' outside validity at "
                f"t={self.validation_time}"
            );
            return False;
        }

        if not cert.sig_valid {
            self.status = "signature";
            print(f"FAIL: bad signature on '{cert.subject}'");
            return False;
        }

        if is_leaf {
            if not cert.server_auth {
                self.status = "policy";
                print("FAIL: leaf missing TLS serverAuth EKU");
                return False;
            }
            if cert.is_ca {
                self.status = "policy";
                print("FAIL: TLS leaf must not be a CA");
                return False;
            }
        } else {
            if not cert.is_ca {
                self.status = "policy";
                print(f"FAIL: '{cert.subject}' is not a CA");
                return False;
            }
            remaining = self.depth - 1;
            if not cert.unlimited_path_len and cert.path_len < remaining {
                self.status = "policy";
                print(f"FAIL: pathLen violated on '{cert.subject}'");
                return False;
            }
        }
        return True;
    }

    can validate with Certificate entry {
        is_leaf = self.depth == 0;
        if not self.process_cert(here, is_leaf=is_leaf) {
            disengage;
        }
        visit [->:IssuedBy:->] else {
            self.finish_chain(here);
            disengage;
        }
    }
}

with entry {
    policy = ValidationPolicy(
        validation_time=2000,
        max_depth=8,
        search_budget=32,
        clock_available=True
    );
    ta = TrustAnchor(subject="Root CA", label="corp-root");
    root_cert = Certificate(
        subject="Root CA",
        issuer="Root CA",
        is_ca=True,
        not_before=1000,
        not_after=3000,
        sig_valid=True
    );
    inter = Certificate(
        subject="Intermediate CA",
        issuer="Root CA",
        is_ca=True,
        not_before=1000,
        not_after=3000,
        sig_valid=True
    );
    leaf = Certificate(
        subject="server.example",
        issuer="Intermediate CA",
        server_auth=True,
        is_ca=False,
        not_before=1000,
        not_after=3000,
        sig_valid=True
    );

    inter +>:Issues:+> leaf;
    leaf +>:IssuedBy:+> inter;
    inter +>:IssuedBy:+> root_cert;
    ta +>:Anchors:+> root_cert;

    root ++> policy ++> ta;
    root ++> inter;
    root ++> leaf;
    root ++> root_cert;

    if not policy.clock_available {
        print("FAIL: wall clock unavailable - fail closed");
    } else {
        print("--- bounded path construction ---");
        inter spawn PathConstructor(
            budget=16,
            target_subject="server.example"
        );

        print("--- RFC 5280 path validation ---");
        leaf spawn CertPathValidator(
            validation_time=policy.validation_time,
            max_depth=policy.max_depth,
            budget=policy.search_budget,
            trust_subjects=["Root CA"]
        );
    }
}
