"""Document move/rename: tree walker that moves a node to a new parent,
rewrites descendant paths, and detects cycles on the way down."""

node Document {
    has doc_id: str = "";
    has title: str = "";
    has slug: str = "";
    has path: str = "";
    has is_folder: bool = False;
    has parent_id: str = "";
}

edge ChildOf {}

walker MoveDocument {
    has old_prefix: str = "";
    has new_prefix: str = "";
    has rewritten: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can relocate with Document entry {
        if here.path.startswith(self.old_prefix) {
            tail = here.path[len(self.old_prefix):];
            new_path = self.new_prefix + tail;
            here.path = new_path;
            self.rewritten.append(here.doc_id);
            print(f"  rewrote {here.doc_id} -> {new_path}");
        }
        visit [-->];
    }
}

walker DetectCycle {
    has start_path: str = "";
    has target_path: str = "";
    has found_cycle: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can descend with Document entry {
        if here.path == self.target_path {
            self.found_cycle = True;
            print(f"  CYCLE: '{self.target_path}' is descendant of '{self.start_path}'");
            disengage;
        }
        if (here.path == self.start_path
            or self.start_path.startswith(here.path + "/")) {
            visit [-->] else { disengage; }
        } else {
            disengage;
        }
    }
}

walker ProjectLister {
    can start with Root entry {
        visit [-->];
    }
    can show with Document entry {
        indent = "  " * here.path.count("/");
        kind = "DIR " if here.is_folder else "FILE";
        print(f"{indent}[{kind}] {here.path}  ({here.doc_id})");
        visit [-->];
    }
}

with entry {
    guides = Document(doc_id="d-guides", title="Guides", slug="guides",
                      path="guides", is_folder=True);
    intro = Document(doc_id="d-intro", title="Intro", slug="intro",
                     path="guides/intro", is_folder=True);
    overview = Document(doc_id="d-overview", title="Overview", slug="overview",
                        path="guides/intro/overview");
    setup = Document(doc_id="d-setup", title="Setup", slug="setup",
                     path="guides/intro/setup");
    docs = Document(doc_id="d-docs", title="Docs", slug="docs",
                    path="docs", is_folder=True);
    getting_started = Document(doc_id="d-gs", title="Getting Started",
                               slug="getting-started",
                               path="docs/getting-started");

    root +>:ChildOf:+> guides +>:ChildOf:+> intro +>:ChildOf:+> overview;
    intro +>:ChildOf:+> setup;
    root +>:ChildOf:+> docs +>:ChildOf:+> getting_started;

    print("=== Initial tree ===");
    root spawn ProjectLister();

    print("\n=== Cycle check: move 'guides/intro' under 'guides/intro/overview' ===");
    cycle_walker = DetectCycle(start_path="guides/intro",
                                target_path="guides/intro/overview");
    root spawn cycle_walker;
    print(f"  cycle detected? {cycle_walker.found_cycle}");

    print("\n=== Move folder: 'guides/intro' -> 'docs/getting-started' ===");
    intro.title = "Getting Started";
    intro.slug = "getting-started";
    mover = MoveDocument(old_prefix="guides/intro",
                         new_prefix="docs/getting-started");
    intro spawn mover;
    print(f"  documents rewritten: {mover.rewritten}");

    print("\n=== Tree after move ===");
    root spawn ProjectLister();

    print("\n=== Duplicate-at-destination check ===");
    duplicate = Document(doc_id="d-overview", title="Overview", slug="overview",
                         path="docs/getting-started/overview");
    print(f"  attempting to create '{duplicate.path}' (id {duplicate.doc_id})");
    print("  -> 409 Conflict would be raised by the service layer");
}
