```jac
"""Phase-loop repair lineaging: model the recursion + trusted-closeout clobber scenario.

A repair child must not recursively launch another repair. We model the
runtime as nodes (Phase, Repair, Closeout) connected by typed edges, and
a walker that follows a repair lineage, recording depth. Depth > 1 means
the runtime should reconcile (emit a closeout) rather than dispatch
another repair.
"""

node Phase {
    has name: str = "";
    has status: str = "awaiting_phase_closeout";
    has verification: str = "passed";
    has blocker: str = "";
}

node Repair {
    has label: str = "";
    has depth: int = 0;
    has interrupted: bool = False;
}

node Closeout {
    has summary: str = "";
    has terminal: str = "passed";
    has trusted: bool = True;
}

edge Spawns {
    has reason: str = "";
}

edge Reconciles {
    has mode: str = "closeout";
}

walker LineageAuditor {
    has max_repair_depth: int = 1;
    has saw_trusted: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with Phase entry {
        if here.verification == "passed" and here.status == "awaiting_phase_closeout" {
            self.saw_trusted = True;
            print(f"[trusted] phase={here.name} status={here.status} verification={here.verification}");
        } else {
            print(f"[diverged] phase={here.name} status={here.status} verification={here.verification} blocker={here.blocker}");
        }
        visit [-->] else { disengage; }
    }

    can follow with Repair entry {
        verdict = "ALLOW" if here.depth <= self.max_repair_depth else "REJECT";
        print(f"repair[{here.label}] depth={here.depth} interrupted={here.interrupted} -> {verdict} (nested dispatch would clobber trusted closeout)");
        visit [-->] else { disengage; }
    }

    can reconcile with Closeout entry {
        print(f"[closeout] terminal={here.terminal} trusted={here.trusted} summary={here.summary}");
    }
}

with entry {
    found = Phase(name="FOUND", status="awaiting_phase_closeout", verification="passed");
    outer_repair = Repair(label="outer", depth=1, interrupted=False);
    inner_repair = Repair(label="inner-nested", depth=2, interrupted=False);
    trusted_closeout = Closeout(summary="27 staged paths, 4 IF gates, valid browser evidence", terminal="passed", trusted=True);

    found +>:Spawns(reason="closeout-mode push"):+> outer_repair;
    outer_repair +>:Spawns(reason="re-invoked phase-loop resume"):+> inner_repair;
    inner_repair +>:Reconciles(mode="closeout"):+> trusted_closeout;

    demo_root = root;
    demo_root ++> found;
    demo_root spawn LineageAuditor(max_repair_depth=1);
}
