```jac
"""Vat compose full-cycle coverage: image: and build: services end-to-end.

Models the AC5 gap where a single `image:` service was exercised but the
`build:` -> materialized-image expansion path had no end-to-end coverage.
A walker traverses the compose graph, expanding build services into image
services via a typed edge, then runs an up/ps/logs/down cycle over both.
"""

node Service {
    has name: str = "";
    has kind: str = "";          # "image" or "build"
    has image_ref: str = "";     # resolved image tag
    has context: str = "";       # build context (build kind only)
    has running: bool = False;
    has logs: list[str] = [];
}

edge Expands {
    has image_ref: str = "";     # materialized image after build
}

edge DependsOn { has required: bool = True; }

node Project {
    has name: str = "";
    has cycle: bool = False;     # domain-observable flag from source
}

walker Compose {
    has visited: list[str] = [];
    has built: list[str] = [];
    has ps_lines: list[str] = [];
    has log_lines: list[str] = [];
    has torn_down: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can load with Project entry {
        print(f"compose: project {here.name}");
        visit [->:Expands:->] else {
            # No services to expand; trigger finalize summary on exit.
            self.torn_down = list(self.built);
        }
    }

    can expand with Service entry {
        if here.name in self.visited {
            print(f"cycle guard: {here.name} already seen");
            disengage;
        }
        self.visited.append(here.name);

        if here.kind == "build" {
            materialized = f"built:{here.context}:{here.name}";
            print(f"compose: expand build {here.name} -> {materialized}");
            here.image_ref = materialized;
            self.built.append(here.name);
        } else {
            print(f"compose: use image {here.image_ref} for {here.name}");
        }

        # ps snapshot for every visited service
        self.ps_lines.append(f"{here.name}\t{here.image_ref}");

        visit [->:DependsOn:->];
    }

    can finalize with Project exit {
        self.torn_down = list(self.built);
        print(f"built services: {self.built}");
        print(f"ps snapshot: {self.ps_lines}");
        print(f"logs: {self.log_lines}");
        print(f"torn down: {self.torn_down}");
    }
}

with entry {
    api = Service(name="api", kind="image", image_ref="nginx:1.27");
    worker = Service(name="worker", kind="build", context="./worker");
    web = Service(name="web", kind="build", context="./web");

    project = Project(name="vat-compose");

    root ++> project;
    project +>:Expands:+> api;
    project +>:Expands:+> worker;
    project +>:Expands:+> web;
    api +>:DependsOn:+> worker;
    worker +>:DependsOn:+> web;

    root spawn Compose();
}
