```jac
"""Restart-warm canonical fact persistence lifecycle."""

node ProjectModel {
    has name: str = "";
    has generation: int = 0;
    has adopted_from_warm: bool = False;
    has invalidated: bool = False;
}

node FactShard {
    has family: str = "";
    has producer: str = "";
    has stable_identity: str = "";
    has generation: int = 0;
    has stale: bool = False;
}

node SnapshotStore {
    has backend: str = "directory";
    has namespace: str = "default";
    has persisted_count: int = 0;
    has corrupt: bool = False;
}

node ProjectFactArtifact {
    has family: str = "";
    has identity: str = "";
    has generation: int = 0;
    has compatible: bool = True;
}

edge OwnsShard {}
edge StoredIn {}
edge AdoptedFrom {}

walker WarmLifecycle {
    has visited: list[str] = [];
    has checkpoint_budget: int = 8;
    has admitted: int = 0;
    has rejected: int = 0;
    has adopted: int = 0;
    has cold_recomputed: int = 0;

    def seen(n: object) -> bool {
        key = str(jid(n));
        for v in self.visited {
            if v == key {
                return True;
            }
        }
        return False;
    }

    def mark(n: object) -> None {
        self.visited.append(str(jid(n)));
    }

    can start with Root entry {
        print("=== restart-warm canonical fact lifecycle ===");
        print(f"checkpoint budget: {self.checkpoint_budget}");
        visit [-->];
    }

    can admit with ProjectModel entry {
        if not self.seen(here) {
            self.mark(here);
            print(f"[admit] ProjectModel '{here.name}' gen={here.generation} "
                  f"invalidated={here.invalidated}");
            visit [-->];
        }
    }

    can validate with FactShard entry {
        if not self.seen(here) {
            self.mark(here);
            if here.stale {
                self.rejected += 1;
                print(f"  [reject] stale shard family={here.family} "
                      f"producer={here.producer}");
            } else {
                self.admitted += 1;
                print(f"  [admit ] shard family={here.family} "
                      f"gen={here.generation}");
            }
            visit [-->];
        }
    }

    can checkpoint with SnapshotStore entry {
        if not self.seen(here) {
            self.mark(here);
            if here.corrupt {
                self.rejected += 1;
                print(f"  [reject] store '{here.backend}' corrupt -> cold path");
            } else {
                room = self.checkpoint_budget - here.persisted_count;
                if room <= 0 {
                    self.rejected += 1;
                    print(f"  [reject] store '{here.backend}' over budget");
                } else {
                    print(f"  [persist] store='{here.backend}' ns='{here.namespace}' "
                          f"capacity={room}");
                }
            }
            visit [-->];
        }
    }

    can adopt with ProjectFactArtifact entry {
        if not self.seen(here) {
            self.mark(here);
            if here.compatible and not here.family == "" {
                self.adopted += 1;
                print(f"  [adopt ] artifact family={here.family} "
                      f"gen={here.generation} (warm)");
            } else {
                self.cold_recomputed += 1;
                print(f"  [cold  ] artifact family={here.family} "
                      f"incompatible -> recompute");
            }
            visit [-->];
        }
    }
}

walker CascadeInvalidate {
    has invalidations: int = 0;
    has visited: list[str] = [];

    def seen(n: object) -> bool {
        key = str(jid(n));
        for v in self.visited {
            if v == key {
                return True;
            }
        }
        return False;
    }

    def mark(n: object) -> None {
        self.visited.append(str(jid(n)));
    }

    can start with Root entry {
        print("--- cascade invalidate: open editor text outranks cache ---");
        visit [-->];
    }

    can invalidate with ProjectModel entry {
        if not self.seen(here) {
            self.mark(here);
            here.invalidated = True;
            self.invalidations += 1;
            print(f"  [invalidate] project '{here.name}' gen={here.generation}");
            visit [-->];
        }
    }

    can cascade with FactShard entry {
        if not self.seen(here) {
            self.mark(here);
            here.stale = True;
            self.invalidations += 1;
            print(f"  [cascade] shard family={here.family} now stale");
            visit [-->];
        }
    }
}

with entry {
    proj = ProjectModel(name="perl-lsp-swarm", generation=7);
    s1 = FactShard(family="symbol_index", producer="scanner",
                   stable_identity="symidx-v3", generation=7);
    s2 = FactShard(family="outline", producer="parser",
                   stable_identity="outline-v1", generation=6, stale=True);
    s3 = FactShard(family="diagnostics", producer="typecheck",
                   stable_identity="diag-v2", generation=7);

    store = SnapshotStore(backend="directory", namespace="proj-7",
                          persisted_count=2);

    a1 = ProjectFactArtifact(family="symbol_index", identity="symidx-v3",
                             generation=7, compatible=True);
    a2 = ProjectFactArtifact(family="outline", identity="outline-v1",
                             generation=5, compatible=False);

    proj +>:OwnsShard:+> s1;
    proj +>:OwnsShard:+> s2;
    proj +>:OwnsShard:+> s3;
    s1 +>:StoredIn:+> store;
    s2 +>:StoredIn:+> store;
    s3 +>:StoredIn:+> store;
    store +>:AdoptedFrom:+> a1;
    store +>:AdoptedFrom:+> a2;

    root ++> proj ++> store ++> a1 ++> a2;

    warm = WarmLifecycle();
    root spawn warm;
    print(f"\nsummary: admitted={warm.admitted} rejected={warm.rejected} "
          f"adopted={warm.adopted} cold_recomputed={warm.cold_recomputed}");
    print(f"project adopted_from_warm={proj.adopted_from_warm}");

    cascade = CascadeInvalidate();
    root spawn cascade;
    print(f"\ninvalidations propagated={cascade.invalidations}");
    print(f"project invalidated={proj.invalidated}, s1.stale={s1.stale}");
}
