```jac
"""Matrix crypto-store persistence: stop helpers that start final persist but don't await it.

Models the two defect axes from the issue:
  A) crypto state is only persisted on a 60s timer (no event-driven flush)
  B) shared-client stop helpers call client.stop() but return void, so the
     in-flight final-persist promise can outlive the caller.

The walks demonstrate:
  - Defect B: a `Shutdown` walker fires each synchronous stop helper and
    leaves the crypto-store's final_persist_pending flag raised.
  - Audit: `AuditPersistence` traverses the graph via the
    BotInstance -> SharedClient -> CryptoStore -> OlmSession typed chain
    and reports which stores still have an unresolved final-persist
    promise (dirty) vs. stores whose helper correctly awaited (clean).
  - Defect A: `TimerFlush` shows olm sessions negotiated inside a 60s
    window are only flushed when the timer ticks.
"""

# ---------- Base node for shared identity semantics ----------

node Persistent {
    has account_id: str = "";
}

# ---------- Entity archetypes ----------

node CryptoStore(Persistent) {
    has mark_clean_shutdown: bool = False;
    has last_flush_at: int = 0;
    has final_persist_pending: bool = False;
}

node BotInstance {
    has bot_name: str = "";
    has restart_count: int = 0;
}

node SharedClient {
    has helper_name: str = "";
    has stop_kind: str = "sync";
}

node OlmSession {
    has sender_key: str = "";
    has established_at: int = 0;
    has on_disk: bool = False;
    has owner_account_id: str = "";
}

# ---------- Typed edges (relationships carry meaning) ----------

edge Owns {}
edge StoppedBy {}
edge HoldsSession {}

# ---------- Walker: BUG B — synchronous stop helpers ----------

walker Shutdown {
    has tick: int = 0;

    can start with Root entry {
        print(f"[Shutdown] process exit requested at tick={self.tick}");
        visit [-->];
    }

    can fan_out with BotInstance entry {
        print(f"[Shutdown]   bot {here.bot_name} (restarts={here.restart_count}) "
              f"calling synchronous stop helpers");
        visit [-->];
    }

    can run_helper with SharedClient entry {
        # Synchronous helper calls client.stop() and returns void.
        visit [->:StoppedBy:->];
    }

    # Union trigger: any crypto store reached via a StoppedBy edge gets
    # its final_persist_pending flag raised but never awaited.
    can leave_pending with CryptoStore entry {
        here.final_persist_pending = True;
        here.mark_clean_shutdown = False;
        kind = here.last_flush_at;
        print(f"[Shutdown]     {here.account_id}: stop() returned; "
              f"final persist NOT awaited (kind='{kind}')");
    }
}

# ---------- Walker: audit pass — who still has an unresolved persist? ----------
#
# Only follows typed edges in the stop/persist chain
# (BotInstance --Owns--> SharedClient --StoppedBy--> CryptoStore
#  --HoldsSession--> OlmSession) so each store is visited exactly once.

walker AuditPersistence {
    has visited: list[str] = [];
    has dirty: list[str] = [];

    can start with Root entry {
        print(f"[Audit] walking the graph to find unresolved final persists");
        visit [-->];
    }

    can descend with BotInstance entry {
        visit [-->];
    }

    can audit_store with CryptoStore entry {
        self.visited.append(here.account_id);
        if here.final_persist_pending {
            self.dirty.append(here.account_id);
        }
        visit [->:HoldsSession:->];
    }

    can audit_session with OlmSession entry {
        self.visited.append(f"olm:{here.sender_key}");
    }
}

# ---------- Walker: A — demonstrate the timer-only flush ----------

walker TimerFlush {
    has tick: int = 0;
    has interval_ms: int = 60_000;

    can start with Root entry {
        print(f"[TimerFlush] persist interval = {self.interval_ms}ms "
              f"(no event-driven flush registered — defect A)");
        visit [-->];
    }

    can tick_over with BotInstance entry {
        visit [-->];
    }

    can maybe_flush_store with CryptoStore entry {
        here.last_flush_at = self.tick;
        visit [-->];
    }

    can maybe_flush with OlmSession entry {
        flushed = (self.tick % 60 == 0);
        here.on_disk = flushed;
        if not flushed {
            print(f"[TimerFlush] tick={self.tick}: olm session "
                  f"{here.sender_key} still in memory (waiting for next 60s tick)");
        } else {
            print(f"[TimerFlush] tick={self.tick}: olm session "
                  f"{here.sender_key} flushed to disk");
        }
    }
}

# ---------- Demo wiring ----------

with entry {
    alice_store = CryptoStore(account_id="@alice:example.org");
    bob_store   = CryptoStore(account_id="@bob:example.org");

    alice_olm = OlmSession(sender_key="ed25519:ALICEKEY",
                           established_at=42,
                           owner_account_id="@alice:example.org");
    bob_olm   = OlmSession(sender_key="ed25519:BOBKEY",
                           established_at=99,
                           owner_account_id="@bob:example.org");

    alice_sync_helper  = SharedClient(helper_name="stopSharedClient",          stop_kind="sync");
    alice_async_helper = SharedClient(helper_name="releaseSharedClientInstance", stop_kind="async");
    bob_sync_helper    = SharedClient(helper_name="stopSharedClientForAccount",  stop_kind="sync");

    alice_bot = BotInstance(bot_name="alice-bot", restart_count=3);
    bob_bot   = BotInstance(bot_name="bob-bot",   restart_count=1);

    alice_bot +>:Owns:+> alice_sync_helper;
    alice_bot +>:Owns:+> alice_async_helper;
    alice_bot +>:Owns:+> alice_store;

    bob_bot +>:Owns:+> bob_sync_helper;
    bob_bot +>:Owns:+> bob_store;

    alice_sync_helper  +>:StoppedBy:+> alice_store;
    alice_async_helper +>:StoppedBy:+> alice_store;
    bob_sync_helper    +>:StoppedBy:+> bob_store;

    alice_store +>:HoldsSession:+> alice_olm;
    bob_store   +>:HoldsSession:+> bob_olm;

    root ++> alice_bot ++> bob_bot;

    print("=== Defect B: synchronous stop helpers ===");
    Shutdown() spawn root;

    print("=== Audit pass ===");
    auditor = AuditPersistence();
    auditor spawn root;
    print(f"[Audit] visited = {auditor.visited}");
    print(f"[Audit] stores with unresolved final persist = {auditor.dirty}");

    print("=== Defect A: timer-only flush ===");
    TimerFlush(tick=1)  spawn root;
    TimerFlush(tick=60) spawn root;
}
```

```jac
"""Qt tree source: pre/post insert and delete notifications.

Models the essential scenario from beeware/toga issue #4202: when a Qt tree
source mutates, we need pre-change events so the view can rebind QModelIndex
references before they go stale. We model the tree, a source that tracks it,
and walkers that traverse the tree reporting invalidation points in the
correct order (pre-delete before removal, post-delete after).
"""

# --- Node archetypes ---------------------------------------------------------

node HasRow {
    has row: int = 0;
    has label: str = "";
    has deleted: bool = False;
}

node TreeSource(HasRow) {
    has name: str = "";
}

node TreeNode(HasRow) {
    has title: str = "";
}

# --- Typed edges -------------------------------------------------------------

edge Parent {
    has row: int = 0;
}

# --- The walker --------------------------------------------------------------

walker SourceAuditor {
    has source_name: str = "";
    has visited: list[str] = [];
    has pre_delete_emitted: int = 0;
    has post_delete_emitted: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit_source with TreeSource entry {
        print("[source] beginning structural audit");
        self.source_name = here.name;
        # Seed visited with the source's own label so it is not revisited.
        if here.label not in self.visited {
            self.visited.append(here.label);
        }
        visit [->:Parent:->];
    }

    # A union ability handles both kinds of nodes the walker may encounter.
    # The body only touches fields declared on the shared HasRow base
    # (row, label, deleted).
    can audit_node with TreeNode | TreeSource entry {
        key = here.label;
        if key in self.visited {
            visit [->:Parent:->];
            return;
        }
        self.visited.append(key);

        if here.deleted {
            self.pre_delete_emitted += 1;
            print(f"  [pre-delete] {key}#{here.row} (source={self.source_name})");
            self.post_delete_emitted += 1;
            print(f"  [post-delete] {key}#{here.row}");
        } else {
            print(f"  [audit] {key}#{here.row}");
        }
        visit [->:Parent:->];
    }
}

# --- Cascade invalidator -----------------------------------------------------

walker CascadeInvalidator {
    has target_label: str = "";
    has marked: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can find_source with TreeSource entry {
        print(f"[cascade] source {here.name} looking for {self.target_label}");
        visit [->:Parent:->];
    }

    can mark_phase with TreeNode | TreeSource entry {
        key = here.label;
        if key in self.visited {
            visit [->:Parent:->];
            return;
        }
        self.visited.append(key);

        if key != self.target_label and not here.deleted {
            self.marked.append(key);
            here.deleted = True;
            print(f"  [mark] {key}#{here.row} -> pending invalidation");
        }
        visit [->:Parent:->];
    }
}

# --- Demo wiring -------------------------------------------------------------

with entry {
    source = TreeSource(name="DocsTree", label="DocsTree", row=0);
    root ++> source;

    docs = TreeNode(title="docs", label="docs", row=0);
    src = TreeNode(title="src", label="src", row=1);
    source +>:Parent(row=0):+> docs;
    source +>:Parent(row=1):+> src;

    overview = TreeNode(title="overview.txt", label="overview.txt", row=0);
    changelog = TreeNode(title="changelog.txt", label="changelog.txt", row=1);
    docs +>:Parent(row=0):+> overview;
    docs +>:Parent(row=1):+> changelog;

    main_py = TreeNode(title="main.py", label="main.py", row=0);
    util_py = TreeNode(title="util.py", label="util.py", row=1);
    src +>:Parent(row=0):+> main_py;
    src +>:Parent(row=1):+> util_py;

    print("=== audit pass: nothing pending ===");
    auditor = SourceAuditor();
    source spawn auditor;
    print(f"audit summary: pre_delete={auditor.pre_delete_emitted} "
          f"post_delete={auditor.post_delete_emitted}");

    print("\n=== cascade invalidate: src ===");
    invalidator = CascadeInvalidator(target_label="src");
    src spawn invalidator;
    print(f"cascade marked: {invalidator.marked}");

    print("\n=== audit pass: src subtree flagged ===");
    auditor2 = SourceAuditor();
    source spawn auditor2;
    print(f"audit summary: pre_delete={auditor2.pre_delete_emitted} "
          f"post_delete={auditor2.post_delete_emitted}");
}
```

```jac
"""x402-doctor: conformance walker over a protected resource graph.

Models the essential scenario from x402-foundation/x402 issue #3104:
a protected resource advertises a Bazaar discovery record, and the
doctor walker traverses the (Resource -> Bazaar record -> declared
crawler request) chain to verify that the live v2 challenge, the
indexed declaration, and the extension responses all agree.
"""

node Resource {
    has title: str = "";
    has url: str = "";
    has live_challenge_digest: str = "";
    has challenge_valid: bool = False;
    has crawler_request_status: int = 0;
}

node BazaarRecord {
    has resource_id: str = "";
    has declared_digest: str = "";
    has declared_input_url: str = "";
    has examples_valid: bool = False;
    has schema_valid: bool = False;
}

node ExtensionResponse {
    has extension_name: str = "";
    has visible: bool = False;
    has response_status: int = 0;
}

node Finding {
    has severity: str = "info";
    has code: str = "";
    has message: str = "";
}

edge Declares { }
edge CrawlsTo { }
edge ReportsExtension { }
edge Emits { }

walker Doctor {
    has findings: list = [];

    can start with Root entry {
        visit [->:Declares:->] else {
            disengage;
        }
    }

    can audit_resource with Resource entry {
        if not here.challenge_valid {
            f = Finding(severity="error", code="CHALLENGE_INVALID",
                    message=f"resource {here.title} did not return a valid v2 PAYMENT-REQUIRED challenge");
            self.findings.append(f);
            print(f"[{f.severity}] {f.code}: {f.message}");
        }
        if here.crawler_request_status != 402 {
            f = Finding(severity="error", code="CRAWLER_NOT_402",
                    message=f"declared crawler request returned {here.crawler_request_status} instead of 402 for {here.title}");
            self.findings.append(f);
            print(f"[{f.severity}] {f.code}: {f.message}");
        }
        visit [here->:Declares:->];
    }

    can audit_record with BazaarRecord entry {
        if not here.examples_valid {
            f = Finding(severity="error", code="BAZAAR_EXAMPLES_INVALID",
                    message=f"Bazaar record for {here.resource_id} has invalid examples");
            self.findings.append(f);
            print(f"[{f.severity}] {f.code}: {f.message}");
        }
        if not here.schema_valid {
            f = Finding(severity="error", code="BAZAAR_SCHEMA_INVALID",
                    message=f"Bazaar record for {here.resource_id} fails JSON Schema");
            self.findings.append(f);
            print(f"[{f.severity}] {f.code}: {f.message}");
        }
        visit [here->:CrawlsTo:->];
    }

    can check_extensions with ExtensionResponse entry {
        if here.extension_name == "bazaar" and not here.visible {
            f = Finding(severity="warning", code="EXTENSION_RESPONSES_HIDDEN",
                    message=f"EXTENSION-RESPONSES not observable for {here.extension_name}");
            self.findings.append(f);
            print(f"[{f.severity}] {f.code}: {f.message}");
        }
        visit [-->];
    }
}

walker DigestCompare {
    has live_digest: str = "";
    has indexed_digest: str = "";
    has matches: bool = False;

    can start with Root entry {
        visit [->:Declares:->] else {
            disengage;
        }
    }

    can compare with Resource entry {
        self.live_digest = here.live_challenge_digest;
        visit [here->:Declares:->] else {
            disengage;
        }
    }

    can decide with BazaarRecord entry {
        self.indexed_digest = here.declared_digest;
        self.matches = self.live_digest == self.indexed_digest;
    }
}

with entry {
    # Build a small graph: root -> resource -> bazaar record -> crawler target,
    # plus an extension response attached to the resource.
    api = Resource(
        title="Paid Articles API",
        url="https://api.example.com/articles",
        live_challenge_digest="sha256:live-abc123",
        challenge_valid=True,
        crawler_request_status=402
    );
    record = BazaarRecord(
        resource_id="articles-v1",
        declared_digest="sha256:live-abc123",
        declared_input_url="https://crawler.example.com/scan",
        examples_valid=True,
        schema_valid=True
    );
    crawler = ExtensionResponse(
        extension_name="bazaar",
        visible=True,
        response_status=402
    );

    root +>:Declares:+> api;
    api +>:Declares:+> record;
    record +>:CrawlsTo:+> crawler;
    api +>:ReportsExtension:+> crawler;

    # Second, broken resource to show findings emit.
    broken = Resource(
        title="Legacy Endpoint",
        url="https://api.example.com/legacy",
        live_challenge_digest="sha256:deadbeef",
        challenge_valid=False,
        crawler_request_status=400
    );
    broken_record = BazaarRecord(
        resource_id="legacy-v0",
        declared_digest="sha256:cafebabe",
        declared_input_url="https://crawler.example.com/legacy",
        examples_valid=False,
        schema_valid=True
    );
    root +>:Declares:+> broken;
    broken +>:Declares:+> broken_record;

    # Run the conformance walker.
    doctor = Doctor();
    root spawn doctor;

    print("--- Doctor findings ---");
    for f in doctor.findings {
        print(f"[{f.severity}] {f.code}: {f.message}");
    }

    # Run the digest comparison walker on the healthy resource.
    cmp = DigestCompare();
    root spawn cmp;
    print(f"--- Digest compare: live={cmp.live_digest} indexed={cmp.indexed_digest} matches={cmp.matches} ---");
}
```

```jac
"""Velero storage-full deadlock model.

The bug report describes a circular dependency in Velero when the object
store runs out of space: a backup cannot finalize (PutObject fails with
HTTP 507), a delete request cannot finalize either (PutObject for the
status also fails), and repository maintenance cannot write its lock.
Result: nothing can transition to a terminal state, so nothing frees
space, so storage stays full forever.

This demo lifts that scenario into idiomatic Jac: backups, their
DataUploads, DeleteBackupRequests and RepoMaintenance jobs are node
archetypes; the dependency relationships are typed edges; a walker
walks the dependency chain so we can see which writes are blocked by
which upstream failures, exposing the circular dependency the issue
describes.
"""

node Auditable {
    has name: str = "";
    has phase: str = "New";
    has terminal: bool = False;
    has write_attempts: int = 0;

    def _kind() -> str {
        return "Auditable";
    }

    def _blocked_phase() -> str {
        return "Blocked";
    }
}

node Backup(Auditable) {
    has store_free_mb: int = 0;

    override def _kind() -> str {
        return "Backup";
    }

    override def _blocked_phase() -> str {
        return "FinalizingPartiallyFailed";
    }
}

node DataUpload(Auditable) {
    override def _kind() -> str {
        return "DataUpload";
    }

    override def _blocked_phase() -> str {
        return "Failed";
    }
}

node DeleteRequest(Auditable) {
    has frees_mb: int = 0;

    override def _kind() -> str {
        return "DeleteBackupRequest";
    }

    override def _blocked_phase() -> str {
        return "InProgress";
    }
}

node RepoMaintenance(Auditable) {
    override def _kind() -> str {
        return "RepoMaintenance";
    }

    override def _blocked_phase() -> str {
        return "Failed";
    }
}

edge NeedsFinalizeWrite { }
edge OwnsUpload { }
edge TargetsBackup { }
edge MaintainsRepo { }

walker StorageAuditor {
    has store_full: bool = True;
    has retry_limit: int = 3;
    has deadlocked: list[str] = [];

    can start with Root entry {
        print(f"store_full={self.store_full} retry_limit={self.retry_limit}");
        visit [-->] else { disengage; }
    }

    can probe with Auditable entry {
        here.write_attempts = here.write_attempts + 1;

        if self.store_full {
            here.terminal = False;
            blocked = here._blocked_phase();
            here.phase = blocked;
            self.deadlocked.append(here.name);
            print(
                f"BLOCKED {here.name} ({here._kind()}): cannot PUT "
                f"finalize/status blob -> HTTP 507 storage full"
            );
        } else {
            here.terminal = True;
            here.phase = "Completed";
            print(f"OK    {here.name} ({here._kind()}): finalized cleanly");
        }

        visit [-->] else { disengage; }
    }
}

walker DeleteCascade {
    can start with Root entry {
        print("\n--- delete-cascade walk ---");
        visit [-->] else { disengage; }
    }

    can audit_delete with DeleteRequest entry {
        print(
            f"DeleteRequest {here.name} phase={here.phase} "
            f"frees_mb={here.frees_mb}"
        );
        visit [->:TargetsBackup:->] else { disengage; }
    }

    can audit_backup with Backup entry {
        print(f"  -> Backup {here.name} phase={here.phase}");
        visit [->:OwnsUpload:->] else { disengage; }
    }

    can audit_upload with DataUpload entry {
        print(f"     -> DataUpload {here.name} phase={here.phase}");
        visit [-->];
    }
}

with entry {
    b1 = Backup(name="backup1", phase="Completed", terminal=True, store_free_mb=541);
    b2 = Backup(name="backup2", phase="Completed", terminal=True, store_free_mb=541);
    b3 = Backup(name="backup3", phase="Completed", terminal=True, store_free_mb=541);
    b4 = Backup(name="backup4", phase="Completed", terminal=True, store_free_mb=541);
    b5 = Backup(name="backup5", phase="FinalizingPartiallyFailed", terminal=False, store_free_mb=541);

    b1_u1 = DataUpload(name="b1-u1", phase="Completed", terminal=True);
    b1_u2 = DataUpload(name="b1-u2", phase="Completed", terminal=True);
    b2_u1 = DataUpload(name="b2-u1", phase="Completed", terminal=True);
    b3_u1 = DataUpload(name="b3-u1", phase="Completed", terminal=True);
    b4_u1 = DataUpload(name="b4-u1", phase="Completed", terminal=True);
    b5_u1 = DataUpload(name="b5-u1", phase="Failed", terminal=True);
    b5_u2 = DataUpload(name="b5-u2", phase="Failed", terminal=True);

    del4 = DeleteRequest(name="del-backup4", phase="InProgress", terminal=False, frees_mb=12000);

    maint = RepoMaintenance(name="kopia-maintenance", phase="Failed", terminal=False);

    root ++> b1 ++> b2 ++> b3 ++> b4 ++> b5;
    b1 +>:OwnsUpload:+> b1_u1;
    b1 +>:OwnsUpload:+> b1_u2;
    b2 +>:OwnsUpload:+> b2_u1;
    b3 +>:OwnsUpload:+> b3_u1;
    b4 +>:OwnsUpload:+> b4_u1;
    b5 +>:OwnsUpload:+> b5_u1;
    b5 +>:OwnsUpload:+> b5_u2;

    b1 +>:NeedsFinalizeWrite:+> b5;
    b2 +>:NeedsFinalizeWrite:+> b5;
    b3 +>:NeedsFinalizeWrite:+> b5;

    del4 +>:TargetsBackup:+> b4;

    root +>:MaintainsRepo:+> maint;

    print("=== StorageAuditor with store_full=True (the deadlock) ===");
    auditor = StorageAuditor(store_full=True, retry_limit=10);
    root spawn auditor;
    joined = ", ".join(auditor.deadlocked);
    print(f"\ndeadlocked entities: {joined}");

    print("\n=== StorageAuditor with store_full=False (storage freed) ===");
    root spawn StorageAuditor(store_full=False, retry_limit=10);

    print("\n=== DeleteCascade: what a delete would need to clean up ===");
    root spawn DeleteCascade();
}
