```jac
"""Incremental notebook updates: cell-by-cell reconciliation demo.

Models the essential scenario from the issue: a notebook is a sequence of
cells with stable ids, the server and client each compute per-cell hashes,
and a reconciler walker walks the diff between the two cell-id lists to
find the longest common subsequence (LCS). Cells in the LCS stay in place;
the rest are inserted, moved, or deleted. A cycle/visit guard prevents
infinite traversal if cells ever reference one another.
"""

node Cell {
    has cell_id: str = "";
    has source: str = "";
    has hash: str = "";
    has index: int = 0;
    has dirty: bool = False;

    def label() -> str {
        return f"#{self.index} {self.cell_id} ({self.hash})";
    }
}

# The notebook holds an ordered chain of cells via a typed Edge edge.
edge Edge { }

# A reconciler walker carries the server's proposed cell-id list and
# walks the client's current cells along the typed Edge chain. It
# computes an in-place LCS reconcile pass and reports the operations
# that would have been issued against the shared YNotebook.
walker Reconciler {
    has server_ids: list[str] = [];
    has ops: list[str] = [];
    has visited: set[str] = set();

    def is_visited(cid: str) -> bool {
        return cid in self.visited;
    }

    def mark_visited(cid: str) -> None {
        self.visited.add(cid);
    }

    def lcs_len(a: list[str], b: list[str]) -> int {
        n = len(a);
        m = len(b);
        # Build an (n+1) x (m+1) DP table in row-major order.
        dp: list[list[int]] = [];
        i = 0;
        while i <= n {
            row: list[int] = [];
            j = 0;
            while j <= m {
                row.append(0);
                j = j + 1;
            }
            dp.append(row);
            i = i + 1;
        }
        i = 1;
        while i <= n {
            j = 1;
            while j <= m {
                if a[i - 1] == b[j - 1] {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    left = dp[i - 1][j];
                    up = dp[i][j - 1];
                    dp[i][j] = left if left >= up else up;
                }
                j = j + 1;
            }
            i = i + 1;
        }
        return dp[n][m];
    }

    can start with Root entry {
        print(f"server proposed order: {self.server_ids}");
        visit [-->];
    }

    can sweep with Cell entry {
        cid = here.cell_id;
        if self.is_visited(cid) {
            # Cycle / revisit guard: skip, do not recurse further.
            disengage;
        }
        self.mark_visited(cid);

        server_idx = -1;
        k = 0;
        while k < len(self.server_ids) {
            if self.server_ids[k] == cid {
                server_idx = k;
            }
            k = k + 1;
        }

        if server_idx == -1 {
            op = f"DELETE {here.label()}";
            self.ops.append(op);
        } else {
            self.ops.append(f"KEEP   {here.label()} at server pos {server_idx}");
        }

        visit [-->];
    }

    can summarize with Root entry {
        client_ids: list[str] = [];
        i = 0;
        while i < len(self.server_ids) {
            cid = self.server_ids[i];
            if cid in self.visited {
                client_ids.append(cid);
            }
            i = i + 1;
        }
        lcs_size = self.lcs_len(client_ids, self.server_ids);

        print("operations:");
        i = 0;
        while i < len(self.ops) {
            print(f"  {self.ops[i]}");
            i = i + 1;
        }
        print(
            f"LCS length = {lcs_size}; "
            f"client kept {len(client_ids)}/{len(self.server_ids)} cells in place"
        );
    }
}

with entry {
    # Build a small notebook: 4 cells in the client's current order.
    c1 = Cell(cell_id="cell-A", source="x = 1", hash="h1", index=0);
    c2 = Cell(cell_id="cell-B", source="x = 2", hash="h2", index=1);
    c3 = Cell(cell_id="cell-C", source="x = 3", hash="h3", index=2);
    c4 = Cell(cell_id="cell-D", source="x = 4", hash="h4", index=3);

    # Client chain: A -> B -> C -> D
    c1 +>:Edge:+> c2 +>:Edge:+> c3 +>:Edge:+> c4;

    # Server proposes: B, C, D, E  (A deleted, E inserted, B/C/D kept)
    server_proposal: list[str] = ["cell-B", "cell-C", "cell-D", "cell-E"];

    r = Reconciler(server_ids=server_proposal);
    root spawn r;
}
```

```jac
"""Maven transitive dependency resolution — model the repository-pollution scenario.

In Maven, a project's pom.xml can pull in a transitive dependency whose own
parent-pom (or BOM) declares additional repositories. When the resolver walks
the dependency tree it inherits those remote repositories and tries to fetch
artifacts from URLs the user never approved. This demo lifts that hand-rolled
machinery into native Jac: project/dependency/repository nodes connected by
typed edges (DependsOn, Inherits, DeclaredIn), and a walker that traverses
the tree and reports which repositories end up "in scope" at every node.

Cycle policy is preserved: a parent-pom can point back to an ancestor
(boot-dependencies -> spring-boot-parent -> boot-dependencies). Without an
explicit guard the walker would loop forever, exactly as the issue describes
the build falling into remote repos it never asked for.
"""

# --- Entity archetypes -------------------------------------------------------

node Project {
    has name: str = "";
    has version: str = "";
}

node Dependency {
    has group: str = "";
    has artifact: str = "";
    has version: str = "";
    has classifier: str = "";
}

node Repository {
    has id: str = "";
    has url: str = "";
    has releases_enabled: bool = True;
    has snapshots_enabled: bool = True;
}

# --- Relationship archetypes -------------------------------------------------

edge DependsOn {
    has scope: str = "compile";
}

edge Inherits { }

edge DeclaredIn { }

# --- The walker --------------------------------------------------------------

walker RepoResolver {
    has visited_ids: list[str] = [];
    has scoped_repos: list[str] = [];
    has verbose: bool = True;

    can start with Root entry {
        if self.verbose {
            print("Resolving repositories across the dependency tree...");
        }
        visit [-->] else {
            disengage;
        }
    }

    can resolve with Project entry {
        proj_key = here.name + ":" + here.version;
        if proj_key in self.visited_ids {
            if self.verbose {
                print(f"[cycle-guard] skip {proj_key} (already visited)");
            }
            disengage;
        }
        self.visited_ids.append(proj_key);

        # Collect repositories declared DIRECTLY on this project.
        for repo in [here->:DeclaredIn:->] {
            label = f"{repo.id} ({repo.url})";
            if label not in self.scoped_repos {
                self.scoped_repos.append(label);
                if self.verbose {
                    print(f"  + repo [self] {label} on {proj_key}");
                }
            }
        }

        # Inherit repositories from the parent-pom (if any).
        for parent in [here->:Inherits:->] {
            for repo in [parent->:DeclaredIn:->] {
                label = f"{repo.id} ({repo.url})";
                if label not in self.scoped_repos {
                    self.scoped_repos.append(label);
                    if self.verbose {
                        print(f"  + repo [inherited] {label} on {proj_key} (via {parent.name}:{parent.version})");
                    }
                }
            }
        }

        # Walk transitive dependencies AND parent-pom inheritance.
        visit [->:DependsOn:->];
        visit [->:Inherits:->];
    }

    can resolve_dep with Dependency entry {
        # A dependency's pom declares its own parent-pom via Inherits.
        # We need to walk those to surface repositories inherited from
        # ancestor poms (e.g. spring-boot-dependencies BOM).
        visit [->:Inherits:->];
    }
}

walker RepoAuditor {
    has user_approved: list[str] = [];

    can start with Root entry {
        print("Auditing resolved repos against user-approved set...");
        visit [-->] else {
            disengage;
        }
    }

    can audit with Project entry {
        # Directly declared repos on this project.
        for repo in [here->:DeclaredIn:->] {
            label = f"{repo.id} ({repo.url})";
            if label not in self.user_approved {
                print(f"  [POLLUTED] {here.name}:{here.version} dragged in unapproved repo {label}");
            }
        }
        # Inherited repos via parent-poms.
        for parent in [here->:Inherits:->] {
            for repo in [parent->:DeclaredIn:->] {
                label = f"{repo.id} ({repo.url})";
                if label not in self.user_approved {
                    print(f"  [POLLUTED] {here.name}:{here.version} dragged in unapproved repo {label} (via {parent.name}:{parent.version})");
                }
            }
        }
        visit [->:DependsOn:->];
    }

    can audit_dep with Dependency entry {
        # Hop to the dependency's parent-pom so its repos get audited too.
        visit [->:Inherits:->];
    }
}

# --- Demonstration graph -----------------------------------------------------

with entry {
    app = Project(name="demo-backend", version="1.0.0-SNAPSHOT");
    user_repo = Repository(
        id="central",
        url="https://artifacts.example.com/repository/maven/",
        releases_enabled=True,
        snapshots_enabled=True,
    );

    starter = Dependency(group="org.springframework.boot",
                        artifact="spring-boot-starter-web",
                        version="2.0.0.RELEASE",
                        classifier="compile");

    parent_pom = Project(name="org.springframework.boot:spring-boot-parent",
                         version="2.0.0.RELEASE");

    bom = Project(name="org.springframework.boot:spring-boot-dependencies",
                  version="2.0.0.RELEASE");

    spring_milestone = Repository(id="spring-milestone",
                                  url="https://repo.spring.io/milestone",
                                  releases_enabled=True,
                                  snapshots_enabled=True);
    bintray_milestones = Repository(id="rabbitmq-maven-milestones",
                                    url="https://dl.bintray.com/rabbitmq/maven-milestones",
                                    releases_enabled=True,
                                    snapshots_enabled=True);

    root ++> app;

    app +>:DependsOn(scope="compile"):+> starter;
    starter +>:Inherits:+> parent_pom;
    parent_pom +>:Inherits:+> bom;

    bom +>:DeclaredIn:+> spring_milestone;
    bom +>:DeclaredIn:+> bintray_milestones;

    app +>:DeclaredIn:+> user_repo;

    resolver = RepoResolver();
    app spawn resolver;

    print("\nFinal repository scope seen by the resolver:");
    for r in resolver.scoped_repos {
        print(f"  - {r}");
    }

    print("\nRunning RepoAuditor with user_approved = [central only]...");
    approved_label = f"{user_repo.id} ({user_repo.url})";
    auditor = RepoAuditor(user_approved=[approved_label]);
    app spawn auditor;
}
```

```jac
"""Asset graph: trace relationships, update attributes, suggest next workflow step.

Models the atlassian-assets scenario where objects live in a graph of
schema types connected by typed relationships (composition, dependency,
reference). A walker traverses the graph, traces relationships, performs
attribute updates, and emits a context-specific workflow suggestion.
"""

# ---- Edge archetypes -------------------------------------------------------

edge Composition {
    has quantity: int = 1;
}

edge Dependency {
    has required: bool = True;
}

# ---- Node archetypes -------------------------------------------------------

node AssetObject {
    has name: str = "";
    has object_type: str = "";
    has attributes: dict = {};
    has available: bool = True;
}

node SchemaType {
    has type_name: str = "";
}

node WorkflowContext {
    has step: str = "";
}

# ---- Walker: traverse relationships, update, suggest ------------------------

walker AssetMaintainer {
    has pending_update: dict = {};
    has visited: list = [];
    has ver_log: list = [];

    can start with Root entry {
        print("AssetMaintainer: scanning object graph from root");
        visit [-->];
    }

    can plan with WorkflowContext entry {
        print(f"Workflow step loaded: {here.step}");
        visit [-->];
    }

    can index with SchemaType entry {
        print(f"SchemaType seen: {here.type_name}");
        visit [-->];
    }

    can inspect with AssetObject entry {
        first_visit = here.name not in self.visited;
        if first_visit {
            self.visited.append(here.name);
        }
        log_line = f"visited {here.object_type} '{here.name}'";
        if first_visit {
            self.ver_log.append(log_line);
        }
        print(log_line);

        # Apply pending attribute update if one was queued.
        if self.pending_update and here.available {
            for (k, v) in self.pending_update.items() {
                here.attributes[k] = v;
            }
            print(f"  updated attributes -> {here.attributes}");

            # Invalidate downstream dependents (even if previously visited,
            # we still want to log the invalidation line per dependent edge).
            for dep in [->:Dependency:->] {
                dep_name = dep.name;
                dep_log = f"  -> dep {dep.object_type} '{dep_name}'";
                self.ver_log.append(dep_log);
                print(dep_log);
            }
            return;
        }

        # Compose-children first (cascade), then dependencies.
        for child in [->:Composition:->] {
            visit [->:Composition:->];
            break;
        }
        for child in [->:Dependency:->] {
            visit [->:Dependency:->];
            break;
        }
    }

    can record_dependency with AssetObject entry {
        first_visit = here.name not in self.visited;
        if first_visit {
            self.visited.append(here.name);
            log_line = f"  -> dep {here.object_type} '{here.name}'";
            self.ver_log.append(log_line);
            print(log_line);
        }
        visit [->:Dependency:->];
    }

    can finalize with Root exit {
        # Context-specific suggestion derived from trace.
        total = len(self.ver_log);
        updated_label = "updated" if self.pending_update else "read-only";
        suggestion = (
            "schedule dependency impact review"
            if self.pending_update
            else "open relationship explorer"
        );
        print(
            f"Trace complete: {total} nodes ({updated_label}). "
            f"Suggested next step: {suggestion}"
        );
    }
}

# ---- Demo graph ------------------------------------------------------------

with entry {
    # Schemas.
    server_schema = SchemaType(type_name="Server");
    app_schema = SchemaType(type_name="Application");
    root ++> server_schema ++> app_schema;

    # Server composed of hardware, depending on a license.
    web_server = AssetObject(
        name="web-01",
        object_type="Server",
        attributes={"hostname": "web-01", "rack": "R3"},
        available=True,
    );
    nic = AssetObject(
        name="nic-eth0",
        object_type="NIC",
        attributes={"mac": "aa:bb:cc:dd:ee:ff"},
        available=True,
    );
    license = AssetObject(
        name="license-acme",
        object_type="License",
        attributes={"key": "ACME-2026"},
        available=True,
    );

    root ++> web_server;
    web_server +>:Composition(quantity=1):+> nic;
    web_server +>:Dependency(required=True):+> license;

    # A second server shares the same license -> cross-reference.
    db_server = AssetObject(
        name="db-01",
        object_type="Server",
        attributes={"hostname": "db-01", "rack": "R3"},
        available=True,
    );
    root ++> db_server;
    db_server +>:Composition(quantity=1):+> AssetObject(
        name="disk-0",
        object_type="Disk",
        attributes={"size_gb": 500},
        available=True,
    );
    db_server +>:Dependency(required=True):+> license;

    # Workflow context node feeding the walker.
    wf = WorkflowContext(step="trace-and-update");
    root ++> wf;

    # Spawn a read-only trace first.
    reader = AssetMaintainer();
    root spawn reader;

    # Then an update pass that mutates web_server's hostname.
    updater = AssetMaintainer(
        pending_update={"hostname": "web-01-prod"},
    );
    root spawn updater;
}
```

```jac
"""RecursionError demo: a maintainer tries to model an infinitely expanding
type alias graph. The mypy crash is the hand-rolled recursion overflowing
Python's call stack while walking the dependency graph. Here we model that
same scenario natively in Jac — a Type node connected to its Component
nodes via ``DependsOn`` edges, and a walker that descends the dependency
chain. Because jac walkers do not auto-dedupe on cyclic graphs, the walker
must carry its own cycle guard; without it the recursion blows the stack
exactly like mypy's ``visit_type_alias_type`` did.
"""

node Type {
    has name: str = "";
    has is_alias: bool = False;
}

edge DependsOn {
    has note: str = "";
}

walker DependencyAnalyzer {
    has visited: list[str] = [];
    has depth_budget: int = 50;

    can start with Root entry {
        print(f"Resolving type graph (depth budget = {self.depth_budget})");
        visit [-->];
    }

    can descend with Type entry {
        if here.name in self.visited {
            print(f"[CYCLE] re-entered {here.name}; stopping (mimics mypy's missing guard)");
            disengage;
        }
        if len(self.visited) >= self.depth_budget {
            print(f"[RecursionError] depth {len(self.visited)} exceeded budget {self.depth_budget} on {here.name}");
            disengage;
        }
        self.visited.append(here.name);
        kind = "alias" if here.is_alias else "concrete";
        print(f"  -> resolving {kind} type {here.name} (seen so far: {self.visited})");
        visit [->:DependsOn:->];
    }
}

with entry {
    # A recursive type alias like mypy's: A = Callable[[A], A]
    a = Type(name="A", is_alias=True);
    b = Type(name="B", is_alias=True);
    c = Type(name="C", is_alias=True);
    leaf = Type(name="Leaf", is_alias=False);

    # Cycle: A -> B -> C -> A (the exact shape that crashed mypy)
    root ++> a;
    a +>:DependsOn(note="unfolds to"):+> b;
    b +>:DependsOn(note="concatenate"):+> c;
    c +>:DependsOn(note="recursive ref"):+> a;
    # plus one terminating branch off B
    b +>:DependsOn(note="base case"):+> leaf;

    root spawn DependencyAnalyzer(depth_budget=8);
}
```

```jac
"""KV/secret-mount count collector over an S3-like storage tree.

Models the consumption-billing path from hashicorp/vault#32090:
the collector recursively LISTs the storage backend to count KV
secrets and mounts, which on object stores is one ListObjectsV2 per
node. We expose the same recursive traversal as a walker so the
behavior is observable, and we wire a small demo tree.
"""

node LogicalMount {
    has mount_path: str = "";
    has mount_type: str = "kv-v2";
    has kv_count: int = 0;
}

node Secret {
    has name: str = "";
}

node AuthMount {
    has mount_path: str = "";
    has mount_type: str = "approle";
    has secret_id_count: int = 0;
}

edge NestedUnder {}
edge HostsSecret {}
edge HostsSecretID {}

walker CountCollector {
    has list_calls: int = 0;
    has secrets_seen: list[str] = [];

    can start with Root entry {
        print("billing tick: starting recursive LIST pass over storage");
        visit [-->];
    }

    can walk_logical with LogicalMount entry {
        self.list_calls += 1;
        print(f"LIST logical/{here.mount_path}/metadata/  (1 ListObjectsV2)");
        visit [-->];
    }

    can walk_auth with AuthMount entry {
        self.list_calls += 1;
        print(f"LIST auth/{here.mount_path}/secret_id  (1 ListObjectsV2)");
        visit [-->];
    }

    can tally_secret with Secret entry {
        self.list_calls += 1;
        self.secrets_seen.append(here.name);
        print(f"  counted secret: {here.name}");
    }
}

with entry {
    app = LogicalMount(mount_path="app", kv_count=3);
    team = LogicalMount(mount_path="team", kv_count=2);
    approle = AuthMount(mount_path="approle", mount_type="approle");

    s_app_a = Secret(name="db/password");
    s_app_b = Secret(name="api/key");
    s_app_c = Secret(name="tls/cert");
    s_team_a = Secret(name="ci/token");
    s_team_b = Secret(name="ops/ssh");

    role_1 = Secret(name="role/web/secret_id_1");
    role_2 = Secret(name="role/web/secret_id_2");

    root ++> app ++> team ++> approle;

    app +>:NestedUnder:+> s_app_a;
    app +>:NestedUnder:+> s_app_b;
    app +>:NestedUnder:+> s_app_c;

    team +>:NestedUnder:+> s_team_a;
    team +>:NestedUnder:+> s_team_b;

    approle +>:HostsSecretID:+> role_1;
    approle +>:HostsSecretID:+> role_2;

    print("=== consumption-billing tick (S3 backend) ===");
    collector = CountCollector();
    root spawn collector;

    print(f"\ntotal LIST calls emitted this tick: {collector.list_calls}");
    print(f"distinct secrets counted: {len(collector.secrets_seen)}");
}
