```jac
"""Runtime partition kernel: model SourcePartition/RepositorySurface traversal.

This program demonstrates the runtime-first POC: a SourcePartition holds a
projection integration contract that a ProducerProjection fulfills. A walker
walks the partition forest, enumerates projection families via the
EmitsProjection/BelongsToFamily chain, and reports a runtime-only
Repository BOM observation. The tree models the same embedded/external
placement semantics described in the issue without any hand-rolled
recursion.
"""

# ---- Archetypes ----------------------------------------------------------

node RepositorySurface {
    has surface_name: str = "";
    has vcs: str = "embedded";
}

node SourcePartition {
    has partition_name: str = "";
    has role: str = "runtime";
    has root_path: str = "";
}

node ProjectionFamily {
    has family_name: str = "";
    has integration: str = "";
    has observed: bool = False;
    has records: int = 0;
}

# ---- Typed edges (relationship carries meaning) ---------------------------

edge HoldsPartition {
    has placement: str = "embedded";
}

edge EmitsProjection {
    has contract: str = "ProducerProjection/v1";
    has admitted: bool = True;
}

edge BelongsToFamily {
    has priority: int = 0;
}

# ---- Walker: runtime BOM auditor ------------------------------------------

walker RuntimeBomAuditor {
    has observed_families: list = [];
    has total_records: int = 0;

    can start with Root entry {
        print("Codex runtime BOM audit (schema 1.0.0)");
        visit [-->];
    }

    can inspect_surface with RepositorySurface entry {
        print(f"surface[{here.surface_name}] vcs={here.vcs}");
        visit [->:HoldsPartition:->];
    }

    can inspect_partition with SourcePartition entry {
        status = "ADMITTED" if here.role == "runtime" else "OBSERVED";
        print(f"partition[{here.partition_name}] role={here.role} -> {status}");
        if here.role == "runtime" {
            visit [->:EmitsProjection:->];
        } else {
            disengage;
        }
    }

    can audit_family with ProjectionFamily entry {
        here.observed = True;
        here.records = here.records + 1;
        self.observed_families.append(here.family_name);
        self.total_records = self.total_records + 1;
        verdict = "OK" if here.observed else "MISSING";
        print(f"  family[{here.family_name}] integration={here.integration} -> {verdict}");
        visit [->:BelongsToFamily:->];
    }
}

# ---- Demo wiring ---------------------------------------------------------

with entry {
    # Runtime source partition: the POC subject.
    runtime_partition = SourcePartition(
        partition_name="codex-runtime",
        role="runtime",
        root_path=".codex/repo-runtime/"
    );

    # Observed subject partition: dotfiles fixture, role=subject, not admitted.
    subject_partition = SourcePartition(
        partition_name="dotfiles",
        role="subject",
        root_path="./"
    );

    # Surfaces: embedded placement first, external placement second.
    embedded_surface = RepositorySurface(
        surface_name="dotfiles",
        vcs="embedded"
    );
    external_surface = RepositorySurface(
        surface_name="codex-runtime",
        vcs="external"
    );

    # Compose the universe via the embedded surface (root holds the
    # root surface which then branches to the partition forest).
    root ++> embedded_surface;
    root ++> external_surface;

    embedded_surface +>:HoldsPartition(placement="embedded"):+> runtime_partition;
    embedded_surface +>:HoldsPartition(placement="embedded"):+> subject_partition;
    external_surface +>:HoldsPartition(placement="external"):+> runtime_partition;

    # Projection families emitted by the runtime partition (Layer 3).
    runtime_partition +>:EmitsProjection(contract="ProducerProjection/v1", admitted=True):+>
        ProjectionFamily(family_name="uv-workspace", integration="uv-projection", records=3)
        +>:BelongsToFamily(priority=1):+>
        ProjectionFamily(family_name="python-project", integration="pep621-projection", records=2)
        +>:BelongsToFamily(priority=2):+>
        ProjectionFamily(family_name="lock-state", integration="uv-lock-projection", records=1);

    # Subject partition emits no projection families in this POC.

    auditor = RuntimeBomAuditor();
    root spawn auditor;

    print(
        f"runtime BOM audit complete: {auditor.total_records} families observed "
        f"across {auditor.observed_families}"
    );
}
