"""Kanban task tree with persisted parent runtime anchor.

Models the essential scenario from SL4: nested tasks form a parent/child
tree via typed ``ParentOf`` edges. The first keep-alive on a nested child
sets the parent's ``runtime_started_at`` once and bumps its generation;
later nested activity must not re-anchor. Completion, reassignment, or
deletion of the parent clears the anchor. A walker audits the tree and
reports which parents are anchored and on which generation they sit,
traversing each task exactly once via typed ``ParentOf`` edges only.
"""

# --- Entity archetypes -----------------------------------------------------

node Task {
    has title: str = "";
    has assignee: str = "";
    has state: str = "open";        # open | in_progress | done | blocked
    has depth: int = 0;
    # Parent runtime anchor fields (inert on non-nested tasks).
    has runtime_started_at: str = "";   # ISO-ish stamp; "" means unanchored
    has generation: int = 0;

    def clear_anchor() -> str {
        cleared = self.runtime_started_at != "";
        self.runtime_started_at = "";
        self.generation = 0;
        label = "cleared" if cleared else "already empty";
        return f"[CLEAR] {self.title}: {label}";
    }

    def first_anchor(child_title: str) -> str {
        if self.runtime_started_at == "" {
            self.runtime_started_at = "2025-01-01T00:00:00Z";
            self.generation = self.generation + 1;
            return (f"[ANCHORED] parent={self.title} gen={self.generation} "
                    f"by child={child_title}");
        }
        return (f"[kept] parent={self.title} gen={self.generation} "
                f"child={child_title} did NOT re-anchor");
    }
}

# --- Typed edges -----------------------------------------------------------

edge ParentOf {
    # Slot in the parent's child list (preserves declaration order).
    has slot: int = 0;
}

# --- Audit walker ----------------------------------------------------------

walker ParentAnchorAuditor {
    has report_lines: list[str] = [];

    can start with Root entry {
        self.report_lines = [];
        visit [-->];
    }

    can audit with Task entry {
        # Audit this task exactly once, then descend only via typed
        # ParentOf edges so we never re-visit or cross-tree-walk.
        label = here.first_anchor(here.title);
        self.report_lines.append(label);
        visit [->:ParentOf:->] else { self.report_lines; };
    }
}

# --- Cascade-clear walker --------------------------------------------------

walker CascadeClear {
    has cleared_lines: list[str] = [];

    can start with Root entry {
        self.cleared_lines = [];
        visit [-->];
    }

    can cascade with Task entry {
        # Reassignment / archive / delete on a parent clears its anchor;
        # cascade only along typed ParentOf edges.
        self.cleared_lines.append(here.clear_anchor());
        visit [->:ParentOf:->] else { self.cleared_lines; };
    }
}

# --- Demo wiring -----------------------------------------------------------

with entry {
    # Build a small tree:
    #   root -> Epic -> [StoryA, StoryB] -> [TaskA1, TaskA2, TaskB1]
    epic = Task(title="Epic", assignee="alice", depth=1);
    story_a = Task(title="StoryA", assignee="bob", depth=2);
    story_b = Task(title="StoryB", assignee="carol", depth=2);
    task_a1 = Task(title="TaskA1", assignee="dan", depth=3);
    task_a2 = Task(title="TaskA2", assignee="dan", depth=3);
    task_b1 = Task(title="TaskB1", assignee="erin", depth=3);

    root ++> epic;
    epic +>:ParentOf(slot=0):+> story_a;
    epic +>:ParentOf(slot=1):+> story_b;
    story_a +>:ParentOf(slot=0):+> task_a1;
    story_a +>:ParentOf(slot=1):+> task_a2;
    story_b +>:ParentOf(slot=0):+> task_b1;

    # 1. First nested keep-alive anchors each parent once; the auditor
    #    visits every task exactly once via ParentOf edges only.
    auditor = ParentAnchorAuditor();
    root spawn auditor;
    for line in auditor.report_lines {
        print(line);
    }

    # 2. Reassignment / archive of the Epic clears its anchor; nested
    #    max-runtime readers will see "no anchor" again.
    epic.assignee = "frank";          # explicit assignee change
    clearer = CascadeClear();
    root spawn clearer;
    for line in clearer.cleared_lines {
        print(line);
    }

    # 3. Ordinary (non-nested) tasks remain attempt-scoped: their anchor
    #    fields stay empty and generation stays 0.
    print(f"[non-nested] {epic.title} runtime_started_at="
          f"'{epic.runtime_started_at}' gen={epic.generation}");
}
```

```jac
"""OSINT v0.9 bounded recursive lead discovery.

Models the essential scenario from issue #17:
- Entities (Target, Query, Finding, Action) are graph nodes.
- Discovery, evidence, verification, and dispatch are typed edges.
- A walker performs the bounded recursive discovery loop with explicit
  cycle guards, budget enforcement, and decision recording, replacing
  the hand-rolled queue/recursion machinery of the Python prototype.
"""

edge Discover {
    has rationale: str = "";
    has gain: float = 0.0;
}

edge LeadsTo {
    has weight: float = 0.0;
}

edge Verify {
    has tool: str = "";
}

edge Dispatch {
    has action: str = "";
}

node Target {
    has canonical_id: str = "";
    has kind: str = "";
    has confidence: float = 0.0;
    has verified: bool = False;
    has visited: bool = False;
    has bonus_gain: float = 0.3;

    def expected_gain() -> float {
        base = self.confidence;
        bonus = self.bonus_gain if not self.verified else 0.0;
        return base + bonus;
    }
}

node ProviderQuery {
    has query: str = "";
    has expected_gain: float = 0.0;
    has consumed: bool = False;
}

node Finding {
    has summary: str = "";
    has confidence: float = 0.0;
    has verified: bool = False;
    has kept: bool = True;
}

node Action {
    has name: str = "";
    has kind: str = "";
    has eligible: bool = True;
    has dispatched: bool = False;
}

walker Discovery {
    has max_depth: int = 4;
    has max_nodes: int = 12;
    has min_confidence: float = 0.4;
    has visited_ids: list[str] = [];
    has depth: int = 0;
    has seen_count: int = 0;
    has findings: list[str] = [];
    has decisions: list[str] = [];

    can start with Root entry {
        print("OSINT v0.9 bounded discovery starting");
        visit [-->] else { disengage; }
    }

    can consider_target with Target entry {
        if here.visited {
            label = "skip-cycle";
            self.decisions.append(f"{here.canonical_id}: {label}");
            disengage;
        }
        if self.seen_count >= self.max_nodes {
            label = "stop-budget-nodes";
            self.decisions.append(f"{here.canonical_id}: {label}");
            disengage;
        }
        if self.depth >= self.max_depth {
            label = "stop-budget-depth";
            self.decisions.append(f"{here.canonical_id}: {label}");
            disengage;
        }
        if here.confidence < self.min_confidence {
            label = "defer-low-confidence";
            self.decisions.append(f"{here.canonical_id}: {label}");
            disengage;
        }
        here.visited = True;
        self.visited_ids.append(here.canonical_id);
        self.seen_count += 1;
        self.findings.append(here.canonical_id);
        gain = here.expected_gain();
        next_label = "verify-via-action" if here.verified else "queue-provider-query";
        self.decisions.append(
            f"{here.canonical_id}: accept (gain={gain:.2f}) -> {next_label}"
        );
        visit [->:Discover:->];
    }

    can follow_lead with ProviderQuery entry {
        if here.consumed {
            label = "skip-repeated-query";
            self.decisions.append(f"query:{here.query}: {label}");
            disengage;
        }
        if here.expected_gain < self.min_confidence {
            label = "skip-low-gain-query";
            self.decisions.append(f"query:{here.query}: {label}");
            here.consumed = True;
            disengage;
        }
        here.consumed = True;
        self.decisions.append(
            f"query:{here.query}: pursue (gain={here.expected_gain:.2f})"
        );
        self.depth += 1;
        visit [->:LeadsTo:->];
        self.depth -= 1;
    }

    can dispatch_action with Action entry {
        if not here.eligible {
            label = "reject-ineligible";
            self.decisions.append(f"action:{here.name}: {label}");
            disengage;
        }
        if here.dispatched {
            label = "skip-already-dispatched";
            self.decisions.append(f"action:{here.name}: {label}");
            disengage;
        }
        here.dispatched = True;
        self.decisions.append(f"action:{here.name}: dispatch ({here.kind})");
        visit [->:Verify:->];
    }

    can record_finding with Finding entry {
        if not here.kept {
            label = "drop-contradicted";
            self.decisions.append(f"finding:{here.summary}: {label}");
            disengage;
        }
        if here.verified {
            label = "verified";
        } else {
            label = "tool-unverified-kept";
        }
        self.decisions.append(
            f"finding:{here.summary}: {label} (conf={here.confidence:.2f})"
        );
    }
}

with entry {
    t_alice = Target(canonical_id="t:alice", kind="person", confidence=0.85);
    t_blog = Target(canonical_id="t:blog", kind="site", confidence=0.55, verified=True);
    t_forum = Target(canonical_id="t:forum", kind="site", confidence=0.20);
    t_alias = Target(canonical_id="t:alias", kind="person", confidence=0.70);
    t_cycle = Target(canonical_id="t:cycle", kind="person", confidence=0.65);

    q_search = ProviderQuery(query="search:alias", expected_gain=0.72);
    q_dns = ProviderQuery(query="dns:blog", expected_gain=0.30);
    q_forum = ProviderQuery(query="forum:post", expected_gain=0.55);

    a_whois = Action(name="whois", kind="verify", eligible=True);
    a_enrich = Action(name="enrich-profile", kind="enrich", eligible=True);
    a_blocked = Action(name="leaked-creds", kind="verify", eligible=False);

    f_match = Finding(summary="alias-match", confidence=0.80, verified=True);
    f_hint = Finding(summary="username-hint", confidence=0.45, verified=False);
    f_noise = Finding(summary="spammy-mention", confidence=0.10, kept=False);

    t_alice +>:Discover(rationale="initial-seed", gain=0.9):+> t_blog;
    t_alice +>:Discover(rationale="co-occurrence", gain=0.6):+> t_alias;
    t_blog +>:Discover(rationale="mention", gain=0.4):+> t_forum;
    t_alias +>:Discover(rationale="alias-of", gain=0.7):+> t_cycle;
    t_cycle +>:Discover(rationale="back-edge", gain=0.1):+> t_alice;

    t_blog +>:LeadsTo(weight=0.8):+> q_search;
    t_forum +>:LeadsTo(weight=0.2):+> q_dns;
    t_alias +>:LeadsTo(weight=0.6):+> q_forum;

    q_search +>:Verify(tool="search-index"):+> f_match;
    q_dns +>:Verify(tool="dns-resolver"):+> f_hint;
    q_forum +>:Dispatch(action="enrich-profile"):+> a_enrich;
    a_enrich +>:Verify(tool="profile-enricher"):+> f_match;

    root +>:Dispatch(action="leaked-creds"):+> a_blocked;
    a_blocked +>:Verify(tool="breach-db"):+> f_noise;

    root ++> t_alice;

    print("=== graph wired ===");

    w = Discovery(
        max_depth=3,
        max_nodes=10,
        min_confidence=0.35
    );
    root spawn w;

    print("\n=== decision trail ===");
    for d in w.decisions {
        print(f"  - {d}");
    }
    print(f"\n=== accepted findings ({len(w.findings)}) ===");
    for f in w.findings {
        print(f"  * {f}");
    }
    print(f"\n=== nodes visited: {w.seen_count} / budget {w.max_nodes} ===");
    print(f"=== max depth reached: {w.depth} / budget {w.max_depth} ===");
}
